/* Bilingual playbook content — complete edition, DE fully localized */
window.__PB_I18N = {"de":{"data":{"cob":[{"id":"bau","icon":"ti-tools","accent":"#e87a16","bg":"var(--en-orange-light)","title":"Bau- und Ausbauhandwerk","types":["Elektro","Sanitär-Heizung-Klima (SHK)","Zimmerei & Tischlerei","Fliesen & Estrich","Maler & Trockenbau","Dachdecker & Gerüstbau"],"policies":{"must":[{"id":"cov_1","name":"Betriebshaftpflicht mit Bau-Deckungskonzept","desc":"Zahlt, wenn die eigene Arbeit jemanden verletzt oder fremdes Eigentum beschädigt. Im Handwerk entscheiden genau die Klauseln, die einfache Policen beschneiden: Schäden an der Sache, an der gerade gearbeitet wird (Bearbeitungs- und Tätigkeitsschäden), und Schäden, die erst nach der Abnahme auftauchen — denn genau da passieren die Schadenfälle im Handwerk.","signal":"Jeder Betrieb, der auf fremden Grundstücken arbeitet, hat das Risiko ab dem ersten Auftrag — nach Nachbesserungen und Gewährleistungsterminen fragen.","when":"","cross":"","claim":"Die Lötverbindung eines Installateurs versagt sechs Wochen nach der Abnahme und setzt den ausgebauten Keller des Kunden unter Wasser — rund 35.000 € für Trocknung, Boden und Maler. Ohne Bearbeitungsschäden- und Nachhaftungsklausel könnte die Police genau das ablehnen. Klauselumfang im aktuellen Bedingungswerk prüfen."},{"id":"cov_2","name":"Kfz-/Flottenversicherung","desc":"Die Kfz-Haftpflicht ist für jedes Fahrzeug gesetzliche Pflicht; die Kaskodeckung schützt die eigenen Transporter und das, was ein Unfall mit dem Betrieb macht.","signal":"Ab mehreren Fahrzeugen lohnt der Blick auf eine Flottenlösung — fragen, wer fährt und was mitfährt.","when":"","cross":"","claim":"Ein Azubi fährt mit dem voll beladenen Transporter an der Kreuzung auf — 60.000 € Personenschaden beim anderen Fahrer plus ein Totalschaden voller Werkzeug. Die Haftpflicht ist gesetzlich abgedeckt; ob der Transporter und die Ladung ersetzt werden, hängt davon ab, was abgeschlossen wurde."},{"id":"cov_3","name":"Geschäftsinhalt + Betriebskosten/Betriebsunterbrechung","desc":"Die Inhaltsversicherung ersetzt Werkstatt, Lager und Maschinen zum heutigen Neuwert; die Betriebskostendeckung zahlt Miete, Löhne und Leasing weiter, solange der Betrieb nicht arbeiten kann.","signal":"Jeder Betrieb mit Werkstatt oder Materiallager — fragen, wann die Versicherungssumme zuletzt eine Rechnung gesehen hat.","when":"","cross":"","claim":"Ein Wochenendeinbruch räumt die Werkstatt leer: 45.000 € an Maschinen und Material. Drei Wochen lang fallen Aufträge aus, und 12.000 € Fixkosten laufen trotzdem weiter. Zwei Policen, ein Ereignis."}],"rec":[{"id":"cov_4","name":"Bauleistungsversicherung","desc":"Deckt das unfertige Bauwerk und gelieferte, noch nicht eingebaute Materialien. Weder die Gebäudeversicherung des Kunden noch die eigene Inhaltsversicherung greifen auf der Baustelle.","signal":"Neubauten, Rohbau, größere Sanierungen.","when":"","cross":"","claim":"Ein Sturm reißt über Nacht den frisch aufgestellten Dachstuhl vom Rohbau — 55.000 € für zerstörtes Holz und Neuaufbau. Für jede Gebäudeversicherung existiert das Haus noch gar nicht; nur die Bauleistung zahlt."},{"id":"cov_5","name":"Montageversicherung","desc":"Schützt technische Anlagen (Heizungen, Photovoltaik, Elektroanlagen) während der Montagephase — geliefert, halb aufgebaut und genau dann am verwundbarsten.","signal":"Betriebe, die hochwertige Anlagen installieren, statt nur zu bauen.","when":"","cross":"","claim":"Eine gelieferte Wärmepumpe für 18.000 € wird am Tag vor der Inbetriebnahme von einem herabfallenden Balken beschädigt. Noch nicht übergeben, noch nicht Eigentum des Kunden — die Montageversicherung zahlt."},{"id":"cov_6","name":"Kautionsversicherung","desc":"Keine Schadenpolice, sondern ein Bürgschaftsprodukt: Der Versicherer stellt Gewährleistungs- und Vertragserfüllungsbürgschaften, damit Auftraggeber keine Sicherheiten einbehalten und die Bankkreditlinie frei bleibt.","signal":"Auftraggeber behalten 5 % Sicherheit ein, öffentliche Ausschreibungen, Bürgschaftsklauseln im Vertrag.","when":"","cross":"entlastet die Bankkreditlinie — ein Liquiditätsargument, kein Versicherungsargument.","claim":"Ein Betrieb hat über acht laufende Aufträge 5 % Sicherheitseinbehalt — 40.000 € eigenes Geld, jahrelang gebunden. Bürgschaften holen dieses Geld noch im selben Monat zurück in den Betrieb."},{"id":"cov_7","name":"Werkzeug unterwegs","desc":"Außenversicherung oder Transportdeckung für Werkzeug und Ausrüstung, die im Bus und auf der Baustelle leben — dort, wo die stationäre Inhaltsversicherung nicht mehr hinreicht.","signal":"„Meine ganze Ausrüstung ist im Bus”, über Nacht beladene Anhänger.","when":"","cross":"","claim":"Ein verschlossener Baustellenanhänger wird über Nacht aufgebrochen, 22.000 € Elektrowerkzeug sind weg. Die Werkstatt-Inhaltsversicherung lehnt ab — das Gerät hatte das Grundstück verlassen. Nacht- und Fahrzeugklauseln in den Bedingungen prüfen."}],"opt":[{"id":"cov_8","name":"Vermögensschaden-Haftpflicht","desc":"Deckt reine Vermögensschäden aus falscher Planung und Beratung. Die Betriebshaftpflicht trägt die handwerkliche Arbeit; diese Police trägt die Planungsentscheidung dahinter.","signal":"Der Betrieb plant selbst — fragen: „Planen Sie, oder bauen Sie nur nach fremden Zeichnungen?”","when":"","cross":"","claim":"Ein Zimmerer mit Planungsleistung dimensioniert einen Balken zu schwach; der Boden hängt durch, und der Bauherr klagt wegen des Planungsfehlers, nicht der Ausführung — 50.000 €, die die Haftpflicht als Planungsverschulden ausschließen würde."},{"id":"cov_9","name":"Firmen-Rechtsschutz","desc":"Zahlt Anwalt und Gericht, wenn der Betrieb kämpfen muss: offene Rechnungen, Gewährleistungsvorwürfe, Arbeitsrechtsstreit.","signal":"Jeder Betrieb, der schon einmal eine offene Rechnung „abgeschrieben” hat, weil Klagen zu teuer wirkte.","when":"","cross":"","claim":"Ein Kunde verweigert die Schlussrechnung über 28.000 € wegen angeblicher Mängel; zwei Jahre Gutachten und Gericht kosten 14.000 €, bevor der Betrieb gewinnt. Der Rechtsschutz hat die Kosten getragen — ohne ihn geben viele Betriebe die Forderung schlicht auf."},{"id":"cov_10","name":"Gruppen-Unfall, bKV, bAV","desc":"Die Gruppen-Unfallversicherung zahlt dort, wo die gesetzliche Unfallversicherung nicht zahlt: Freizeit, Invaliditäts-Einmalleistungen, der Inhaber selbst. bKV und bAV sind Bindungsinstrumente in einem Handwerk ohne Fachkräfte.","signal":"„Wir finden keine Leute” — oder ein Inhaber ganz ohne private Unfallabsicherung.","when":"","cross":"","claim":"Ein Dachdecker zertrümmert sich beim Sonntagsfußball das Sprunggelenk — drei Monate Ausfall, null von der Berufsgenossenschaft, weil es kein Arbeitsunfall war. Die Gruppen-Unfall zahlt Einmalleistung und Tagegeld, und der Betrieb behält einen loyalen Mitarbeiter statt ihn an Geldsorgen zu verlieren."},{"id":"cov_11","name":"Cyberversicherung","desc":"Zahlt IT-Krisenhilfe, Datenwiederherstellung, Betriebsunterbrechung und die Folgen von Zahlungsbetrug. Handwerksbetriebe glauben, bei ihnen gebe es nichts zu holen; Angreifer wissen: schwache E-Mail-Sicherheit und hohe Rechnungen.","signal":"Digitale Angebote und Rechnungen, Online-Banking.","when":"","cross":"","claim":"Das E-Mail-Konto des Betriebs wird still gekapert; der Betrüger verschickt die echte Schlussrechnung über 19.000 € mit getauschter IBAN. Der Kunde zahlt an den Kriminellen und weigert sich, doppelt zu zahlen — Geld und Kundenbeziehung sind weg. Die Cyberdeckung zahlt Forensik und je nach Bedingungswerk den Betrugsschaden — Zahlungsbetrugs-Baustein prüfen."}]}},{"id":"reinigung","icon":"ti-spray","accent":"#0f94a7","bg":"var(--en-iceblue-light)","title":"Gebäudereinigung & Facility Services","types":["Unterhaltsreinigung","Büro- und Praxisreinigung","Glas- und Fassadenreinigung","Sonderreinigung","Hausmeisterdienste","Bauendreinigung"],"policies":{"must":[{"id":"cov_12","name":"Betriebshaftpflicht","desc":"Zahlt, wenn die Reinigungsarbeit jemanden verletzt oder Kundeneigentum beschädigt. Das ganze Risiko spielt sich in fremden Gebäuden ab — entscheidend sind Tätigkeitsschäden an der bearbeiteten Sache (der polierte Schreibtisch, der gestrippte Boden) und Schlüsselverlust, beides in Basispolicen eingeschränkt oder gedeckelt.","signal":"Generalschlüssel, Alarmcodes, Zugang nach Feierabend.","when":"","cross":"","claim":"Eine Mitarbeiterin verliert den Generalschlüssel eines Bürokomplexes; der Vermieter lässt die komplette Schließanlage tauschen — 25.000 €. Der zweite Klassiker: Ein Besucher stürzt auf frisch gewischtem Boden ohne Warnschild und bricht sich die Hüfte — 60.000 € Personenschaden. Schlüsselverlust-Sublimits in den Bedingungen prüfen."},{"id":"cov_13","name":"Kfz-/Flottenversicherung","desc":"Kfz-Haftpflicht ist je Fahrzeug Pflicht — und Reinigungskolonnen sind täglich zwischen Objekten unterwegs. Fahrzeugschäden sind hier ein Häufigkeitsrisiko, keine Seltenheit.","signal":"Mehrere Objekte pro Tag, Kolonnen in Firmenwagen.","when":"","cross":"","claim":"Zwischen dem zweiten und dritten Objekt des Vormittags streift ein Kolonnenfahrzeug in einer engen Hofeinfahrt ein geparktes Auto — 7.000 €. Klein, aber der dritte solche Schaden im Jahr wird zum Prämiengespräch; ein Flottenvertrag steuert das besser als fünf Einzelpolicen."}],"rec":[{"id":"cov_14","name":"Firmen-Rechtsschutz","desc":"Zahlt Anwalt und Gericht, wenn der Betrieb in einen Streit gezogen wird. Reinigung ist personalintensiv mit hoher Fluktuation — gestritten wird vor allem im Arbeitsrecht.","signal":"Viele Beschäftigte, Lohnfragen, Kündigungsgeschichten.","when":"","cross":"","claim":"Eine gekündigte Reinigungskraft klagt auf Kündigungsschutz; das Arbeitsgerichtsverfahren kostet 8.000 € Anwaltskosten, obwohl man sich vernünftig einigt. In der ersten Instanz vor dem Arbeitsgericht trägt jede Seite ihren Anwalt selbst — egal wer gewinnt. Genau dafür lohnt diese Deckung."},{"id":"cov_15","name":"Geschäftsinhalt + Betriebskosten","desc":"Ersetzt Maschinenpark und Lagerbestand zum Neuwert und trägt die Fixkosten, wenn das Depot brennt oder unter Wasser steht. Wachsende Reinigungsfirmen sammeln mehr Maschinen an, als ihnen bewusst ist.","signal":"Aufsitz-Scheuersaugmaschinen, Lagerräume, ein Depot.","when":"","cross":"","claim":"Ein Einbruch ins Depot kostet zwei Aufsitz-Scheuersaugmaschinen und einen Chemikalienvorrat — 18.000 €. Die Versicherungssumme war seit der halben Flottengröße nicht angefasst worden; ohne Vorsorgeklausel hätte die Unterversicherung die Zahlung gekürzt."},{"id":"cov_16","name":"Gruppen-Unfallversicherung","desc":"Zahlt Einmalleistungen und Tagegeld für Unfälle, die die gesetzliche Deckung ignoriert — vor allem alles außerhalb der Arbeit. Glas- und Fassadenkolonnen arbeiten in der Höhe, und ihr Privatleben trägt denselben Körper.","signal":"Arbeit in der Höhe, körperlich fordernde Teams.","when":"","cross":"","claim":"Ein Fassadenreiniger bricht sich beim Wochenendausflug ein Bein — Monate Ausfall, und die Berufsgenossenschaft schuldet nichts, weil es kein Arbeitsunfall war. Die Gruppen-Unfall zahlt, und der Arbeitgeber, der sie eingerichtet hat, bleibt in guter Erinnerung."}],"opt":[{"id":"cov_17","name":"Cyberversicherung","desc":"Zahlt Krisenreaktion und Haftung, wenn die eigenen Systeme leaken oder verschlüsselt werden. Die Einsatzplanungssoftware einer Reinigungsfirma enthält etwas besonders Sensibles: Zugangscodes und Gebäudepläne der Kunden.","signal":"Planungs-Apps, gespeicherte Alarmcodes, Kundenportale.","when":"","cross":"","claim":"Das Planungstool wird gehackt und Alarmcodes der Kunden liegen offen; jeder betroffene Kunde muss informiert, Schlösser und Codes getauscht, eine Forensikfirma beauftragt werden — 20.000 € noch vor jeder Klage, plus ein Vertrauensproblem, das nur schnelle, finanzierte Reaktion eindämmt."},{"id":"cov_18","name":"bKV","desc":"Ein kleiner, arbeitgeberfinanzierter Gesundheits-Zuschuss (Zahn, Physio, Vorsorge), der in einer Niedriglohn-Branche mit hoher Fluktuation weit über seinen Preis wirkt.","signal":"Klagen über Fluktuation und Bewerber, die nicht erscheinen.","when":"","cross":"","claim":"Eine Reinigungskraft bekommt eine 900-€-Zahnrechnung großteils über die bKV des Arbeitgebers erstattet — genau die Art konkreter, persönlicher Vorteil, der jemanden davon abhält, für 50 Cent mehr pro Stunde weiterzuziehen."}]}},{"id":"galabau","icon":"ti-plant-2","accent":"#009284","bg":"var(--en-leaf-light)","title":"Garten- und Landschaftsbau (inkl. Winterdienst)","types":["GaLaBau","Grünpflege","Baumpflege","Pflasterarbeiten","Winterdienst","Bewässerungstechnik"],"policies":{"must":[{"id":"cov_19","name":"Betriebshaftpflicht","desc":"Zahlt bei Personen- und Sachschäden aus der Arbeit — und in diesem Gewerk entscheiden zwei Erweiterungen alles: vertraglich übernommene Verkehrssicherungs- und Streupflichten (die Winterdienst-Haftung, die der Eigentümer abgibt) und die Umwelt-Bausteine für Pflanzenschutz- und Betriebsmitteleinsatz.","signal":"Winterverträge, Spritzprogramme, Arbeiten nahe an Nachbargrundstücken.","when":"","cross":"","claim":"An einem Januarmorgen stürzt ein Fußgänger auf Blitzeis auf einem Kundenparkplatz, den der Betrieb streuen sollte — Oberschenkelhalsbruch und 45.000 € Personenschaden, gerichtet gegen den Betrieb, nicht den Eigentümer, weil die Pflicht vertraglich übertragen war. Prüfen, dass Winterdienst ausdrücklich mitversichert ist."},{"id":"cov_20","name":"Fahrbare Maschinen","desc":"Eine Maschinenversicherung für den selbstfahrenden Park: Bagger, Radlader, Aufsitzmäher. Sie deckt Diebstahl, Bedienunfälle und Schäden überall dort, wo die Maschine arbeitet — was die gebäudegebundene Inhaltsversicherung nicht kann.","signal":"Maschinen, die über Nacht auf offenen Baustellen oder Anhängern stehen.","when":"","cross":"","claim":"Ein Minibagger für 38.000 € verschwindet über ein langes Wochenende von einer eingezäunten, aber unbewachten Baustelle. Keine Inhaltsversicherung zahlt außerhalb des Betriebsgrundstücks; die Maschinenversicherung ersetzt ihn — und die Saison ist gerettet."},{"id":"cov_21","name":"Flottenversicherung","desc":"Gesetzlich vorgeschriebene Haftpflicht je Fahrzeug — plus die Praxis, dass dieses Gewerk täglich schwere Anhänger zieht. Anhängervorfälle sind sein typischer Kfz-Schaden.","signal":"Zugfahrzeuge mit Anhängern, Maschinen im Schlepp.","when":"","cross":"","claim":"Ein Anhänger mit Aufsitzmäher reißt sich auf der Bundesstraße los und trifft Leitplanke und nachfolgendes Auto — ein Haftpflichtschaden im fünfstelligen Bereich plus der zerstörte Mäher. Die Haftpflichtseite ist Pflichtdeckung; der Mäher braucht die Maschinenversicherung oben."}],"rec":[{"id":"cov_22","name":"Bauleistungsversicherung","desc":"Deckt die unfertigen Außenanlagen: Mauern, Beläge, Pflanzungen und geliefertes Material vor der Abnahme — was keine Gebäude- oder Grundstückspolice anfasst.","signal":"Neuanlagen, Projekte in Bauphasen, Ausschreibungen.","when":"","cross":"","claim":"Tage vor der Übergabe unterspült Starkregen eine frisch gebaute Stützmauer, sie sackt teilweise ein — 30.000 € Wiederaufbau. Der Kunde hat noch nicht abgenommen; der Schaden gehört dem Betrieb, und die Bauleistung trägt ihn."},{"id":"cov_23","name":"Geschäftsinhalt + Betriebskosten","desc":"Neuwert für Halle, Werkstatt und das Saisongerät darin, plus die Fixkosten, die weiterlaufen, wenn die Basis ausfällt.","signal":"Ein Hof oder eine Halle voller Geräte im Winterlager.","when":"","cross":"","claim":"Ein Hallenbrand im Februar vernichtet eingelagerte Mäher, Trimmer und den Bewässerungsbestand fürs Frühjahr — 50.000 € Gerät, dazu der Wettlauf, zur Saison startklar zu sein, während Miete und Löhne weiterlaufen."},{"id":"cov_24","name":"Firmen-Rechtsschutz","desc":"Finanziert den Rechtsstreit, wenn Kunden die Zahlung mit Mängelbehauptungen verweigern — der häufigste Streit dieses Gewerks.","signal":"Geschichten über offene Schlussrechnungen, „die Pflanzen sind eingegangen”-Diskussionen.","when":"","cross":"","claim":"Ein Kunde behält 22.000 € ein und behauptet, die Pflanzung sei misslungen; das Gutachten beweist, dass er nie wie angewiesen gewässert hat. Bis dahin: 9.000 € Anwalts- und Gutachterkosten — getragen vom Rechtsschutz."}],"opt":[{"id":"cov_25","name":"Kautionsversicherung","desc":"Vom Versicherer gestellte Vertragserfüllungs- und Gewährleistungsbürgschaften, typischerweise bei öffentlichen Ausschreibungen und größeren Gewerbeprojekten verlangt.","signal":"Kommunale Aufträge, Bürgschaftsklauseln in Ausschreibungen.","when":"","cross":"","claim":"Eine Stadt verlangt eine Vertragserfüllungsbürgschaft für einen 200.000-€-Parkauftrag. Die Kautionslinie stellt sie in Tagen; ohne sie würde die Bank Barhinterlegung verlangen — und der Betrieb könnte gar nicht bieten."},{"id":"cov_26","name":"Gruppen-Unfall / bKV","desc":"Unfall-Einmalleistungen jenseits des gesetzlichen Systems und ein Gesundheits-Zuschuss für Teams, die körperlich hart arbeiten.","signal":"Verschlissene Mannschaften, Einstellungsprobleme.","when":"","cross":"","claim":"Ein Landschaftsgärtner schneidet sich beim privaten Brennholzmachen schwer in die Hand — privat, also zahlt die Berufsgenossenschaft nichts. Die Gruppen-Unfall zahlt die Einmalleistung, die Monate reduzierter Einsatzfähigkeit überbrückt."},{"id":"cov_27","name":"Cyberversicherung","desc":"Krisenreaktion und Betrugsdeckung, sobald Angebote, Rechnungen und Banking digital laufen.","signal":"Digitale Angebote, Rechnungen per E-Mail.","when":"","cross":"","claim":"Eine gefälschte Lieferanten-Mail leitet eine Materialzahlung über 15.000 € auf ein Betrügerkonto um. Das Geld ist weg, bevor jemand anruft; Betrugs-Baustein und Krisenteam der Cyberpolice machen den Unterschied zwischen einer schlechten Woche und einem schlechten Jahr — Baustein prüfen."}]}},{"id":"gastro","icon":"ti-tools-kitchen-2","accent":"var(--en-burgundy)","bg":"var(--en-rose-50)","title":"Gastronomie & Hotellerie","types":["Restaurants","Cafés","Imbiss & Systemgastronomie","Bars","Hotels & Pensionen","Catering"],"policies":{"must":[{"id":"cov_28","name":"Betriebshaftpflicht","desc":"Zahlt, wenn Gäste verletzt werden oder erkranken: der Sturz auf nassem Boden, die Verbrennung durch den fallenden Teller, das Essen, das einen Tisch ins Krankenhaus schickt, der Mantel, der aus der Garderobe verschwindet. Alkoholausschank gehört selbstverständlich ins Bedingungswerk.","signal":"Jeder Betrieb mit Gästen im Haus — die Frage ist nur, ob das Bedingungswerk zum Konzept passt (Bar, Terrasse, Catering außer Haus).","when":"","cross":"","claim":"Ein Gast rutscht auf einem verschütteten Getränk aus, das niemand weggewischt hat — Zahn und Jochbein gebrochen, 25.000 € inklusive Zahnrekonstruktion. Zweiter Klassiker: Nach einem Catering haben zwölf Hochzeitsgäste Salmonellen, und die Forderungen kommen als Gruppe."},{"id":"cov_29","name":"Geschäftsinhaltsversicherung","desc":"Ersetzt Küche, Kühltechnik und Einrichtung zum heutigen Neuwert nach Brand, Wasser, Einbruch oder Sturm. Die Gastronomie investiert laufend nach — Vorsorge und Unterversicherungsverzicht sind hier bares Geld, kein Kleingedrucktes.","signal":"Jede frische Renovierung oder neue Küchenlinie, von der die Versicherungssumme nichts weiß.","when":"","cross":"","claim":"Ein Fritteusenbrand zum Feierabend zerstört den Küchenblock — 80.000 € Technik. Die Police war nach dem Umbau aktualisiert, also zahlt der Neuwert voll; der Kollege die Straße runter mit zehn Jahre alter Versicherungssumme hätte eine anteilige Kürzung geschluckt."},{"id":"cov_30","name":"Betriebskosten-/Betriebsunterbrechungsdeckung","desc":"Zahlt Miete, Löhne und Leasing weiter, solange das Restaurant nicht bewirten kann. Bei dünnen Margen und hohen Fixkosten ist die Unterbrechung oft schlimmer als der Brand selbst.","signal":"Teure Lagen, finanzierte Einrichtung.","when":"","cross":"","claim":"Der Küchenbrand von oben schließt das Restaurant für acht Wochen. 50.000 € an Miete, Löhnen und Leasing werden fällig — bei null Umsatz. Die Unterbrechungsdeckung zahlt, und der Betrieb macht wieder auf, statt aufzugeben."},{"id":"cov_31","name":"Betriebsschließungsversicherung","desc":"Zahlt, wenn das Gesundheitsamt den Betrieb nach dem Infektionsschutzgesetz schließt: Salmonellen, Noroviren, ein positiver Befund in der Küche. Die gastrospezifische Police, die die meisten Wirte erst im Ernstfall kennengelernt haben.","signal":"Jeder Lebensmittelbetrieb — fragen, was zehn Tage Zwangsschließung kosten würden.","when":"","cross":"","claim":"Ein Norovirus-Fall aus der Küche führt zu zehn Tagen behördlicher Schließung, Desinfektion und Vernichtung offener Ware — rund 30.000 € an entgangener Marge, Entsorgung und Reinigung. Bedingungen und Krankheitenliste unterscheiden sich je Tarifgeneration stark — aktuelle Liste prüfen."}],"rec":[{"id":"cov_32","name":"Gewerbliche Gebäudeversicherung","desc":"Feuer, Wasser, Sturm und — aktiv ansprechen — Elementardeckung für alle, denen die Immobilie selbst gehört.","signal":"Der Betreiber oder die Familie besitzt das Gebäude.","when":"","cross":"","claim":"Ein Sommersturm deckt einen Teil des Dachs über den Gästezimmern ab; 60.000 € Gebäudeschaden sind das Problem des Eigentümers, nicht des Mieters — und nur eine Gebäudepolice zahlt."},{"id":"cov_33","name":"Cyberversicherung","desc":"Krisenhilfe, Wiederherstellung und Haftung, wenn die digitale Seite ausfällt: Reservierungssystem, Kasse, Gästedaten.","signal":"Online-Buchung, Kartenzahlung, Gäste-WLAN.","when":"","cross":"","claim":"Ransomware sperrt Kasse und Reservierungssystem an einem Freitag; das Wochenende läuft auf Papier und Zuruf, Online-Buchungen springen ab, der Wiederherstellungs-Spezialist kostet 18.000 €. Offengelegte Gästedaten setzen die DSGVO-Meldung obendrauf."},{"id":"cov_34","name":"Firmen-Rechtsschutz","desc":"Rechtskosten für die zwei Streits, die die Gastronomie wirklich hat: den Vermieter und das Personal.","signal":"Mietverhandlungen, hohe Fluktuation.","when":"","cross":"","claim":"Der Vermieter setzt über eine Indexklausel eine strittige Mieterhöhung durch; sie durchzufechten kostet 10.000 € Anwaltskosten über 18 Monate — getragen vom Rechtsschutz, der aus „das können wir uns nicht leisten” eine Verhandlung gemacht hat."}],"opt":[{"id":"cov_35","name":"bKV","desc":"Ein arbeitgeberfinanzierter Gesundheits-Zuschuss, der sichtbar für die Leute sorgt — in einer Branche, in der alle einstellen.","signal":"„Montags haben wir zu, weil uns Personal fehlt.\"","when":"","cross":"","claim":"Der Sous-Chef bekommt über die bKV eine schnelle Physio für die Schulter statt drei Monate Wartezeit — und lehnt das Angebot vom Hotel gegenüber ab."},{"id":"cov_36","name":"Gruppen-Unfall","desc":"Einmalleistungen für die Verbrennungen, Schnitte und Stürze des Küchenalltags — und für alles nach Feierabend, wo die gesetzliche Deckung schweigt.","signal":"Küchenlastige Teams.","when":"","cross":"","claim":"Ein Kellner verbrüht sich zu Hause beim Einkochen schwer die Hand — kein gesetzlicher Schutz, drei Wochen Ausfall. Die Gruppen-Unfall zahlt das Tagegeld, das ihn über Wasser hält."},{"id":"cov_37","name":"Kunstversicherung","desc":"Allgefahrendeckung für Kunst in Hotels und gehobenen Häusern, die Inhaltspolicen schlecht oder nur gedeckelt abbilden.","signal":"Originale in der Lobby, eine Sammlung im Restaurant.","when":"","cross":"","claim":"Ein Wasserschaden ruiniert ein 15.000-€-Gemälde in der Hotellobby; die Kunstpolice zahlt zum vereinbarten Wert, wo die Inhaltsversicherung über Zeitwert diskutiert hätte."}]}},{"id":"handel","icon":"ti-building-store","accent":"#187caa","bg":"#e6f3fa","title":"Einzelhandel","types":["Mode & Schuhe","Lebensmittel & Feinkost","Elektronik & Telekommunikation","Möbel & Einrichtung","Sport & Freizeit","Kiosk & Convenience"],"policies":{"must":[{"id":"cov_38","name":"Betriebshaftpflicht","desc":"Zahlt, wenn ein Kunde im oder durch das Geschäft verletzt wird: der Sturz am nassen Eingang, das kippende Regaldisplay, die Verkehrssicherungspflicht auf dem Gehweg davor. Bei Publikumsverkehr den ganzen Tag ist das ein Häufigkeitsrisiko.","signal":"Jedes Geschäft mit einer Tür zum Publikum.","when":"","cross":"","claim":"An einem Regensamstag rutscht eine Kundin direkt hinterm Eingang aus — keine Matte, kein Schild — und bricht sich das Handgelenk. 15.000 € Personenschaden und eine Lektion über die Fußmatte, die die Police aufgefangen hat."},{"id":"cov_39","name":"Geschäftsinhaltsversicherung","desc":"Ersetzt Ware, Einrichtung und Technik zum Neuwert nach Brand, Einbruch, Wasser oder Sturm. Die Ware ist das Betriebskapital — und sie schwankt mit der Saison. Genau deshalb entscheiden Vorsorge und Unterversicherungsverzicht, ob voll oder gekürzt gezahlt wird.","signal":"Fragen, was zur Saisonspitze auf der Fläche und im Lager liegt — und was in der Police steht.","when":"","cross":"","claim":"Ein Einbruch Ende November räumt 70.000 € Weihnachtsware aus. Die Versicherungssumme spiegelte einen ruhigen März; nur Vorsorgeklausel und Verzicht haben die Zahlung vor einer anteiligen Kürzung gerettet, die den Inhaber Zehntausende gekostet hätte."},{"id":"cov_40","name":"Betriebskosten-/Betriebsunterbrechungsdeckung","desc":"Zahlt die Miete in der Toplage und die Löhne weiter, solange das Geschäft für Reparaturen zu ist. Im Handel interessiert es die Miete nicht, dass der Laden voller Trocknungsgeräte steht.","signal":"A-Lagen-Mieten, finanzierter Ladenbau.","when":"","cross":"","claim":"Ein Rohrbruch über der Decke schließt das Geschäft sechs Wochen im besten Quartal. 25.000 € Miete und Löhne werden gegen null Umsatz fällig — die Unterbrechungsdeckung zahlt, und die verpasste Saison wird kein verpasstes Jahr."}],"rec":[{"id":"cov_41","name":"Cyberversicherung","desc":"Krisenhilfe, Wiederherstellung und Haftung, wenn Webshop, Kasse oder Kundendatenbank getroffen werden. Sobald ein Geschäft online verkauft oder wirbt, hält es genau das, was Angreifer zu Geld machen: Zahlungsströme und Kundendaten.","signal":"Ein Webshop, Newsletter-Listen, Kartenterminals.","when":"","cross":"","claim":"Kartenskimming-Code sitzt drei Wochen im Webshop-Checkout; Forensik, Pflichtinformation der Kunden und Plattformbereinigung kosten 25.000 € — noch vor einem Cent Reputationsreparatur."},{"id":"cov_42","name":"Elektronikversicherung","desc":"Eine Allgefahrenpolice für die Elektronik, auf der das Geschäft läuft: Kassen, Scanner, Etikettendrucker, Digital Signage. Sie zahlt bei Überspannung, Sturz und dem verschütteten Kaffee, den die Inhaltsversicherung als „Bedienschaden\" ablehnt.","signal":"Moderne Kassensysteme, Bildschirme im Schaufenster.","when":"","cross":"","claim":"Eine Überspannung nach Netzarbeiten killt das Kassensystem und zwei Displays — 12.000 €, gezahlt als Elektronikschaden, wo die Inhaltspolice diskutiert hätte."},{"id":"cov_43","name":"Transportversicherung (Waren)","desc":"Versichert die Ware, während sie sich bewegt: vom Großhändler, zwischen Filialen, im eigenen Transporter. Die Inhaltsversicherung endet an der Ladentür.","signal":"Eigene Abholfahrten, Warentransfer zwischen Filialen.","when":"","cross":"","claim":"Der Transporter des Inhabers wird auf einer Warenfahrt zwischen Filialen aufgefahren; 18.000 € Modeware sind zerdrückt und durchnässt. Die Kfz-Haftpflicht zahlt den anderen Fahrer — die Ware zahlt nur die Transportdeckung."},{"id":"cov_44","name":"Firmen-Rechtsschutz","desc":"Rechtskosten für die zwei chronischen Streits des Handels: den Gewerbemietvertrag und das Arbeitsrecht.","signal":"Indexmiet-Briefe, Personalfluktuation.","when":"","cross":"","claim":"Der Vermieter zieht eine Indexklausel für eine kräftige Mieterhöhung; die Berechnung anzufechten kostet 8.000 € Anwaltskosten und endet in einem tragbaren Kompromiss — ein Streit, den sich das Geschäft nur leisten konnte, weil die Police die Anwälte zahlte."}],"opt":[{"id":"cov_45","name":"Betriebsschließungsversicherung","desc":"Zahlt, wenn das Gesundheitsamt einen Lebensmittelhändler nach dem Infektionsschutzgesetz schließt.","signal":"Jedes Geschäft mit unverpackten Lebensmitteln.","when":"","cross":"","claim":"Ein Nagetierbefund schließt ein Feinkostgeschäft für eine Woche Schädlingsbekämpfung und Grundreinigung — 12.000 € entgangene Marge und vernichtete offene Ware, plus die Reinigungsrechnung."},{"id":"cov_46","name":"Gewerbliche Gebäudeversicherung","desc":"Für den Händler, dem das Gebäude gehört: Feuer, Wasser, Sturm — und die Elementarfrage laut gestellt.","signal":"Eigengenutzte Immobilie.","when":"","cross":"","claim":"Sturmschäden an Fassade und Dach summieren sich auf 40.000 € — ein Gebäudeschaden, den weder Inhalt noch Unterbrechung anfassen."},{"id":"cov_47","name":"Gruppen-Unfall / bKV","desc":"Unfall-Einmalleistungen jenseits des gesetzlichen Systems und ein Gesundheits-Zuschuss — Bindungsinstrumente im Filialbetrieb, der ständig einstellt.","signal":"Mehrere Filialen, chronisch offene Stellen.","when":"","cross":"","claim":"Eine Filialleiterin, die arbeitgeberfinanzierte Zahnleistungen und nach einem Radunfall eine private Einmalleistung bekommt, erzählt es jeder neuen Kollegin — billiger als eine einzige Recruiter-Rechnung."}]}},{"id":"immobilien","icon":"ti-building-skyscraper","accent":"#545241","bg":"var(--en-warmgrey-light)","title":"Immobilienwirtschaft & Hausverwaltung","types":["Hausverwaltungen (WEG & Miet)","Bestandshalter & Vermieter","Immobilienmakler","kleine Projektentwicklung","Objekteigentümer","Ferienvermietung"],"policies":{"must":[{"id":"cov_48","name":"Vermögensschaden-Haftpflichtversicherung","desc":"Zahlt, wenn ein beruflicher Fehler Kunden Geld kostet, ohne dass etwas kaputtgeht: die verpasste Frist, die falsche Abrechnung, der verpatzte Eigentümerbeschluss. Für Wohnimmobilienverwalter und Makler berufsrechtlich vorgeschrieben — und reine Vermögensschäden sind genau das, was die Betriebshaftpflicht ausschließt.","signal":"Jeder Verwalter und Makler mit Erlaubnis; Höhe gegen die aktuellen gesetzlichen Mindestanforderungen prüfen.","when":"","cross":"","claim":"Ein Verwalter lässt beim Versichererwechsel die Gebäudeversicherung einer WEG verfallen; dann findet ein Brand das Gebäude unterversichert vor, und die Eigentümer verklagen den Verwalter auf die Differenz von über 100.000 €. Diese Forderung landet auf der Vermögensschaden-Police — oder beim Verwalter persönlich."},{"id":"cov_49","name":"Betriebshaftpflicht inkl. Haus- und Grundbesitzerhaftpflicht","desc":"Zahlt, wenn jemand durch das Gebäude oder Grundstück verletzt wird: der vereiste Gehweg, die lockere Stufe, der fallende Ziegel. Verwalter tragen sie für verwaltete Objekte, Eigentümer für die eigenen.","signal":"Jedes verwaltete oder eigene Gebäude.","when":"","cross":"","claim":"Ein lockerer Dachziegel löst sich bei einer Böe und verletzt eine Passantin — 50.000 € Personenschaden gegen den Eigentümer wegen verletzter Instandhaltungspflicht, verteidigt und gezahlt von der Haus- und Grundbesitzerhaftpflicht."},{"id":"cov_50","name":"Gewerbliche Gebäudeversicherung","desc":"Der Kern-Vermögensschutz für Bestandshalter: Feuer, Wasser, Sturm — und den Elementar-Baustein aktiv ansprechen, denn Starkregenschäden sind der am schnellsten wachsende Schaden im Segment.","signal":"Jedes eigene Gebäude — fragen, welche davon Elementardeckung haben.","when":"","cross":"","claim":"Ein Wolkenbruch drückt die Kanalisation zurück und flutet Keller und Heizanlage eines Gebäudes — 70.000 €. Ohne Elementar-Baustein zahlt die Standard-Gebäudepolice bei Rückstau und Oberflächenwasser nichts."}],"rec":[{"id":"cov_51","name":"Mietkautionsversicherung","desc":"Ersetzt die Barkaution durch eine Bürgschaft: Mieter binden keine drei Monatsmieten, Vermieter halten trotzdem Sicherheit.","signal":"Jedes Vermietergespräch über Neuvermietung.","when":"","cross":"","claim":"Ein Gewerbemieter zieht ein, ohne 9.000 € bar zu hinterlegen; der Vermieter hält stattdessen die Versichererbürgschaft und vermietet schneller — ein Produkt, das sich im Vermietungsgespräch von selbst verkauft."},{"id":"cov_52","name":"Photovoltaikversicherung","desc":"Versichert die Dachanlage selbst (Sturm, Hagel, Feuer, Technikausfall, Diebstahl) und den Einspeiseertrag, den sie verdient. Gebäudepolicen nehmen eine PV-Anlage nicht automatisch sauber mit.","signal":"PV auf Bestandsdächern, WEG-Beschlüsse zu Solar.","when":"","cross":"","claim":"Ein Wechselrichterdefekt löst einen kleinen Dachbrand aus; 35.000 € an Modulen, Dach und Ertragsausfall. Der Gebäudeversicherer zeigt auf die PV-Anlage, der PV-Versicherer aufs Dach — außer die Zuordnung wurde bei der Eindeckung geklärt. Genau das ist der Job des Vermittlers."},{"id":"cov_53","name":"Firmen-Rechtsschutz","desc":"Rechtskosten für die Streits, die die Woche eines Verwalters füllen: Mietrückstände, Räumungen, WEG-Konflikte.","signal":"Jeder Verwalter mit offenen Verfahren.","when":"","cross":"","claim":"Eine Räumungsklage wegen Rückständen zieht sich 18 Monate durchs Gericht — 12.000 € Rechtskosten, bevor die Wohnung zurück ist. Der Rechtsschutz hat sie getragen; der Mietausfall war schlimm genug."},{"id":"cov_54","name":"Bauleistungsversicherung","desc":"Deckt Sanierungs- und Dachprojekte im Bestand, solange sie halb fertig sind — das Fenster, in dem weder Gebäudepolice noch die Deckung des Handwerkers das Eigentümerinteresse voll schützt.","signal":"Geplante Fassaden-, Dach- oder energetische Sanierungen.","when":"","cross":"","claim":"Mitten in der Sanierung treibt ein Sturm Regen durchs geöffnete Dach in drei frisch renovierte Etagen — 45.000 €. Die Gebäudepolice nennt es Baurisiko; die Bauleistung ist genau für dieses Fenster gebaut."}],"opt":[{"id":"cov_55","name":"Cyberversicherung","desc":"Krisenreaktion und Haftung, wenn die Systeme des Verwalters gehackt werden. Eine Hausverwaltung hält Bankverbindungen, Hausgeldkonten und persönliche Daten ganzer Eigentümergemeinschaften — ein reiches, weiches Ziel.","signal":"Digitale Eigentümerportale, SEPA-Einzugsläufe.","when":"","cross":"","claim":"Das E-Mail-Konto des Verwalters wird kompromittiert, und Eigentümer erhalten ein überzeugendes „neues Konto für Hausgeldzahlungen\" — 30.000 € landen bei einem Betrüger, verteilt über ein Dutzend Eigentümer, bevor jemand anruft. Reaktionskosten, Meldungen und Haftung folgen."},{"id":"cov_56","name":"Kunstversicherung","desc":"Deckung zum vereinbarten Wert für Kunst in repräsentativen Foyers und verwalteten Prestige-Objekten.","signal":"Originale in Eingangshallen.","when":"","cross":"","claim":"Umzugshelfer beschädigen bei einem Umbau eine Skulptur im Foyer — 10.000 € zum vereinbarten Wert, ohne Zeitwert-Diskussion."}]}},{"id":"beratung","icon":"ti-briefcase","accent":"#b31767","bg":"var(--en-violet-light)","title":"Beratende Berufe & Finanzdienstleister","types":["Unternehmensberatung","Finanz- & Versicherungsvermittlung","Lohn- & Buchhaltungsdienstleister","Sachverständige & Gutachter","Personalberatung","Übersetzer & Dolmetscher"],"policies":{"must":[{"id":"cov_57","name":"Vermögensschaden-Haftpflichtversicherung","desc":"Zahlt, wenn ein Rat, eine Berechnung oder eine verpasste Frist den Mandanten Geld kostet. Die Kernpolice des Segments, denn das Produkt IST der Rat — und Fehler machen hier nichts kaputt, sie vernichten nur Wert. Genau das schließt die Betriebshaftpflicht aus. Für mehrere erlaubnispflichtige Berufe gesetzlich vorgeschrieben.","signal":"Jeder Beratungsbetrieb; Pflichtstatus und Mindestsummen je Erlaubnis prüfen.","when":"","cross":"","claim":"Ein Lohnbüro rechnet ein Jahr lang mit falschen Sozialversicherungs-Parametern; der Mandant steht vor 60.000 € Nachzahlungen und Säumniszuschlägen und reicht die Rechnung direkt weiter. Die Vermögensschaden-Police verteidigt, verhandelt und zahlt, was geschuldet ist."},{"id":"cov_58","name":"Betriebshaftpflicht","desc":"Die gewöhnliche Büro- und Besucherhaftung: Ein Besucher stolpert, die Laptoptasche fegt die Technik des Mandanten vom Tisch. Klein neben dem Beratungsrisiko, aber die Schäden sind real und günstig zu decken.","signal":"Jedes Büro mit Besuchern oder Arbeit beim Mandanten vor Ort.","when":"","cross":"","claim":"Der Vertreter eines Mandanten stolpert im Besprechungsraum über ein Präsentationskabel und bricht sich den Ellbogen — 12.000 €, sauber ein Haftpflichtfall, sauber aus der Vermögensschaden-Police ausgeschlossen."},{"id":"cov_59","name":"Cyberversicherung","desc":"Krisenhilfe, Wiederherstellung, Meldung und Haftung, wenn Mandantendaten abfließen oder Systeme verschlüsselt werden. Für eine Beratung sind die Daten die Beziehung: Mandate, Finanzen, persönliche Unterlagen.","signal":"Cloud-Tools, Homeoffice, Mandantenportale.","when":"","cross":"","claim":"Ransomware verschlüsselt den Dateiserver samt Jahren von Mandantenakten; Wiederherstellung, Forensik und DSGVO-Meldung an jeden Betroffenen kosten 30.000 € — und die finanzierte, professionelle Reaktion ist es, die die drei größten Mandate vom Gehen abhält."}],"rec":[{"id":"cov_60","name":"Geschäftsinhalt + Elektronikversicherung","desc":"Neuwertdeckung fürs Büro plus eine Allgefahren-Schicht für die Hardware, auf der es läuft: Laptops, Server, Präsentationstechnik — inklusive Sturz, Überspannung und Diebstahl aus dem Auto, was Inhaltspolicen ausschließen oder deckeln.","signal":"Mobile Teams, finanzierte IT.","when":"","cross":"","claim":"Ein Rohrbruch übers Wochenende durchnässt Serverschrank und vier Arbeitsplätze — 22.000 €, aufgeteilt zwischen Inhaltsschaden (Möbel, Ausbau) und Elektronikschaden (die Hardware, zu Konditionen, die eine reine Inhaltspolice nicht bieten würde)."},{"id":"cov_61","name":"Firmen-Rechtsschutz","desc":"Rechtskosten für die eigenen Kämpfe der Kanzlei oder Beratung — vor allem offene Honorare und Arbeitsrechtsstreit, die zwei Fälle, die Beratungen am häufigsten schlucken, weil das Verklagen eines Kunden teuer wirkt.","signal":"Ärger mit Außenständen, wachsende Belegschaft.","when":"","cross":"","claim":"Ein Kunde verweigert ein Projekthonorar über 25.000 € — die Leistung sei „nicht brauchbar\" gewesen; zwei Instanzen kosten 11.000 € Gebühren, gezahlt von der Police. Der Betrieb hat eingezogen statt abgeschrieben."},{"id":"cov_62","name":"Dienstreiseversicherung","desc":"Kranken-, Rücktransport-, Gepäck- und Haftpflichtdeckung für Dienstreisende — dort, wo gesetzliche und private Krankenversicherung im Ausland Lücken lassen.","signal":"Berater beim Kunden vor Ort, internationale Projekte.","when":"","cross":"","claim":"Ein Berater bricht beim Auslandsprojekt mit Blinddarmentzündung zusammen; Behandlung und medizinisch begleiteter Rücktransport kosten 15.000 € — ein Reisepolice-Fall, den der Betrieb sonst aus Kulanz gezahlt hätte."}],"opt":[{"id":"cov_63","name":"bAV / bKV","desc":"Arbeitgeberfinanzierte Alters- und Gesundheitsvorsorge — die Standardwährung im Wettbewerb um qualifizierte Köpfe.","signal":"Recruiting-Frust, Gegenangebote.","when":"","cross":"","claim":"Eine Senior-Analystin mit zwei Angeboten nimmt das mit finanzierter bAV und Arbeitgeber-bKV — Benefits, die einen Bruchteil der Gehaltserhöhung kosten, die der Wettbewerber gebraucht hätte."},{"id":"cov_64","name":"Gruppen-Unfallversicherung","desc":"Unfall-Einmalleistungen dort, wo das gesetzliche System nicht hinreicht: Freizeit — und der Inhaber, der oft gar keinen gesetzlichen Unfallschutz hat.","signal":"Inhaber ohne private Unfallpolice.","when":"","cross":"","claim":"Die Gründungspartnerin reißt sich beim Skifahren die Kniebänder — drei Monate reduzierte Kapazität, null gesetzliche Leistungen, weil es privat war und sie Inhaberin ist. Die Einmalleistung der Gruppen-Unfall überbrückt, was ihr Ausfall kostet."}]}},{"id":"it","icon":"ti-code","accent":"#0f6f9c","bg":"#e6f3fa","title":"IT- und Digitaldienstleister","types":["Softwareentwicklung","IT-Systemhäuser & Managed Services","Webentwicklung","IT-Beratung","Hosting & Cloud","E-Commerce-Dienstleister"],"policies":{"must":[{"id":"cov_65","name":"Vermögensschaden-Haftpflicht für IT-Dienstleister","desc":"Zahlt, wenn Code, Konfiguration oder Beratung den Kunden Geld kostet, ohne etwas Physisches zu zerstören: das verpatzte Update, die falsch konfigurierte Firewall, die Datenmigration mit Verlusten. Die Kernhaftung der IT-Firma, denn ihre Fehler sind fast nie Sachschäden.","signal":"Jede Firma, die Software ausliefert oder Kundensysteme betreut; IT-Bedingungswerk und Kombination mit der Betriebshaftpflicht prüfen.","when":"","cross":"","claim":"Ein fehlerhaftes Release legt die Produktionsplanung eines Kunden zwei Tage lahm; der Kunde stellt 120.000 € Stillstandskosten in Rechnung. Die Betriebshaftpflicht zuckt mit den Schultern — nichts wurde beschädigt. Die IT-Vermögensschaden-Police verteidigt und zahlt."},{"id":"cov_66","name":"Betriebshaftpflicht","desc":"Die physische Haftung, die es auch im Digitalgeschäft gibt: der Techniker, dem der Switch des Kunden herunterfällt, der Besucher, der im Büro stolpert. Meist im Paket mit der IT-Vermögensschaden-Police — und das Paket ist der Punkt.","signal":"Arbeit beim Kunden vor Ort.","when":"","cross":"","claim":"Bei einer Rack-Migration rutscht einem Techniker die Storage-Einheit des Kunden aus der Hand — 18.000 € Hardware. Sachschaden, also zahlt die Haftpflicht-Hälfte des Pakets."},{"id":"cov_67","name":"Cyberversicherung","desc":"Krisenreaktion, Wiederherstellung, Unterbrechung und Haftung, wenn die IT-Firma selbst gehackt wird. Doppelt kritisch: Der eigene Ausfall kaskadiert in jeden betreuten Kunden — und ein IT-Dienstleister, der die eigene professionelle Krisenreaktion nicht finanzieren kann, verliert den Raum.","signal":"Admin-Zugriff auf Kundensysteme, Managed-Services-Verträge.","when":"","cross":"","claim":"Ein Angreifer kompromittiert das Fernwartungstool des MSP und arbeitet sich Richtung Kundennetze vor. Eindämmung, Forensik über mehrere Umgebungen und Kundeninformation kosten 80.000 € — und das Krisenteam des Versicherers an der Seite der Firma ist es, was die Kunden vom Kündigen abhält."}],"rec":[{"id":"cov_68","name":"Elektronikversicherung","desc":"Allgefahrendeckung für Entwicklungs- und Serverhardware, inklusive Überspannung, Sturz und Diebstahl — die Ausfallarten, die Inhaltspolicen ausschließen.","signal":"Eigenes Rack, hochgerüstete Workstations.","when":"","cross":"","claim":"Eine defekte USV lässt eine Spannungsspitze durch und grillt zwei Server und einen Switch — 16.000 €, gezahlt als Elektronikschaden."},{"id":"cov_69","name":"Firmen-Rechtsschutz","desc":"Rechtskosten für den typischen Streit der Branche: den Kunden, der nicht abnimmt. Abnahme, Scope und Zahlung sind die Stellen, an denen IT-Firmen leise ausbluten.","signal":"„Der Kunde nimmt das Release nicht ab.\"","when":"","cross":"","claim":"Ein Kunde verweigert die Abnahme einer Plattform über 60.000 € wegen „fehlender Features\", die nie im Scope waren; die Zahlung durchzusetzen kostet 14.000 € Gebühren — getragen von der Police, und die Rechnung wird bezahlt."},{"id":"cov_70","name":"Geschäftsinhalt + Betriebskosten","desc":"Neuwert fürs Büro und die Fixkosten, die weiterlaufen, wenn es unbenutzbar ist. Schlank, aber real, sobald Räume und Leute existieren.","signal":"Eigenes Büro, wachsendes Team.","when":"","cross":"","claim":"Ein Elektrobrand macht das Büro einen Monat unbenutzbar; 10.000 € Miete und laufende Kosten stehen gegen ein Team am Küchentisch — die Betriebskostendeckung zahlt, denn den Mietvertrag interessiert das nicht."}],"opt":[{"id":"cov_71","name":"bAV","desc":"Arbeitgeberfinanzierte Altersvorsorge — im IT-Recruiting fast schon Hygienefaktor.","signal":"Jedes Einstellungsgespräch in dieser Branche.","when":"","cross":"","claim":"Ein Entwickler mit zwei Angeboten fragt im ersten Gespräch nach der Altersvorsorge — die Firma mit finanzierter bAV antwortet in einem Satz; die ohne verliert Kandidaten, von denen sie nie erfährt."},{"id":"cov_72","name":"Dienstreiseversicherung","desc":"Kranken- und Rücktransportdeckung für Projektmitarbeiter beim Kunden.","signal":"Berater beim Kunden eingebettet, internationale Rollouts.","when":"","cross":"","claim":"Ein Engineer landet beim Auslands-Rollout nach einem Rollerunfall im Krankenhaus; Behandlung und Rücktransport kosten 12.000 € — ein Fall für die Reisepolice, kein Gehaltsstreit."}]}},{"id":"agentur","icon":"ti-palette","accent":"#9b2fae","bg":"var(--en-violet-light)","title":"Agenturen, Marketing & Medien","types":["Werbe- & Kreativagenturen","Social Media & Performance-Marketing","Foto- & Videoproduktion","PR & Kommunikation","Design & Branding","Verlage & Content"],"policies":{"must":[{"id":"cov_73","name":"Betriebshaftpflicht + Vermögensschaden-Haftpflicht","desc":"Das Paar, das Agenturleben abdeckt: Betriebshaftpflicht für die physische Welt (Set, Büro, Event) und Vermögensschaden für das echte Agenturrisiko — veröffentlichte Arbeit, die fremde Rechte verletzt, oder ein Kampagnenfehler, der den Kunden Geld kostet. Rechtsverletzungen und Fehlausführung sind reine Vermögensschäden, und nur ein medienkundiges Bedingungswerk trägt sie.","signal":"Jede Firma, die für Kunden veröffentlicht; vor dem Angebot prüfen, welcher Baustein Rechtsverletzungen trägt.","when":"","cross":"","claim":"Eine Kampagne geht mit einem Stockfoto raus, dessen Lizenz Außenwerbung nicht abdeckte; die Agentur des Fotografen fordert 20.000 €. Zweiter Klassiker: Ein Buchungsfehler schaltet die Anzeige des Kunden im falschen Markt, und der Kunde stellt die verbrannten 45.000 € Mediabudget in Rechnung."},{"id":"cov_74","name":"Cyberversicherung","desc":"Krisenreaktion und Haftung, wenn Konten oder Systeme der Agentur getroffen werden. Agenturen halten etwas besonders Gefährliches: Admin-Zugriff auf Werbekonten, Shops und Social-Kanäle der Kunden — plus Budgetgewalt über fremdes Geld.","signal":"Verwaltete Werbekonten, Kunden-Logins im Passwort-Tool.","when":"","cross":"","claim":"Ein gephishter Login lässt einen Angreifer über Nacht ins Werbekonto eines Kunden; 35.000 € Kundenbudget verbrennen in Betrugsplatzierungen, bevor der Alarm losgeht. Der Kunde will es von der Agentur zurück — die Cyberdeckung finanziert Reaktion und Haftungsgespräch."}],"rec":[{"id":"cov_75","name":"Elektronikversicherung","desc":"Allgefahrendeckung für Kamera-, Schnitt- und Produktionstechnik, inklusive der Ausfallarten, die unterwegs zählen: Sturz, Diebstahl aus dem Fahrzeug, Wasser.","signal":"Drehs, Equipment, das reist.","when":"","cross":"","claim":"Ein Kamera-Kit im Wert von 28.000 € wird beim Location-Mittagessen aus dem Crew-Van gestohlen — ein Elektronik-/Equipmentschaden; die Büro-Inhaltspolice galt ab der Bürotür nicht mehr."},{"id":"cov_76","name":"Geschäftsinhalt + Betriebskosten","desc":"Neuwert für Studio und Ausbau plus die Fixkosten, die laufen, wenn die Fläche ausfällt.","signal":"Eigenes Studio, Schnittplätze.","when":"","cross":"","claim":"Ein Sprinklerdefekt durchnässt Studio und Schnittplatz — 30.000 € Ausbau und Wochen Leerlauf-Miete, aufgeteilt zwischen Inhalts- und Betriebskostenschaden."},{"id":"cov_77","name":"Firmen-Rechtsschutz","desc":"Rechtskosten für die chronischen Kämpfe der Agentur: Honorare und Nutzungsrechte, wenn die Beziehung kippt.","signal":"Scope-Creep-Geschichten, Kunden, die Arbeiten über die Lizenz hinaus nutzen.","when":"","cross":"","claim":"Ein Ex-Kunde fährt Kampagnen-Assets zwei Jahre nach Lizenzende weiter; die Nutzungsrechte durchzusetzen kostet 9.000 € Anwaltskosten — getragen von der Police, und der Vergleich hat das Jahr bezahlt."}],"opt":[{"id":"cov_78","name":"Dienstreiseversicherung","desc":"Kranken-, Rücktransport- und equipmentnahe Deckung für Produktionen und Pitches außer Haus.","signal":"Drehs im Ausland, reisende Crews.","when":"","cross":"","claim":"Eine Producerin bricht sich an einer Auslandslocation den Knöchel; Behandlung und vorzeitige Rückreise kosten 8.000 € — ein Fall für die Reisepolice, keine Produktionsüberschreitung."},{"id":"cov_79","name":"Kunstversicherung","desc":"Deckung zum vereinbarten Wert für Agenturen mit Sammlung oder Ausstellungsflächen.","signal":"Originale an den Wänden, Büros im Galerie-Stil.","when":"","cross":"","claim":"Nach einem Kunden-Event ist ein 12.000-€-Werk beschädigt; die Kunstpolice zahlt zum vereinbarten Wert, wo die Inhaltsversicherung über Zeitwert gestritten hätte."}]}},{"id":"heilberufe","icon":"ti-stethoscope","accent":"#009284","bg":"var(--en-leaf-light)","title":"Heilberufe & Pflege","types":["Physiotherapie","Ergotherapie & Logopädie","Heilpraktiker","ambulante Pflegedienste","Hebammenpraxen","Podologie"],"policies":{"must":[{"id":"cov_80","name":"Betriebs- und Berufshaftpflicht","desc":"Zahlt, wenn die Behandlung einen Patienten verletzt — und verteidigt, wenn ein Patient das nur behauptet. In Hands-on-Berufen ist der Personenschaden aus der Behandlung das Kernrisiko, das Berufsrecht verlangt die Deckung meist, und die Verteidigungsfunktion zählt so viel wie die Zahlung: Auch der unbegründete Vorwurf braucht Gutachter und Anwälte.","signal":"Jede behandelnde Praxis; berufsrechtliche Anforderung je Beruf prüfen.","when":"","cross":"","claim":"Einer Physiotherapie-Manipulation wird die Verschlimmerung eines Bandscheibenschadens angelastet; der Patient fordert 70.000 €. Der Gutachterstreit dauert zwei Jahre — die Police finanziert durchgehend die Verteidigung und zahlt nur, was wirklich geschuldet ist."},{"id":"cov_81","name":"Geschäftsinhalt + Elektronikversicherung","desc":"Neuwert für die Praxiseinrichtung plus Allgefahrendeckung für die Behandlungsgeräte — finanziert, empfindlich und mehr wert, als irgendjemand im Kopf hat.","signal":"Gerätelastige Praxen, Leasingverträge.","when":"","cross":"","claim":"Ein Wasserschaden am Wochenende ruiniert das Stoßwellengerät und zwei Behandlungsliegen — 25.000 €, das Gerät bezahlt über die Elektronikdeckung zu Konditionen, die eine reine Inhaltspolice nicht bieten würde."},{"id":"cov_82","name":"Betriebskostendeckung","desc":"Zahlt Miete und Gehälter weiter, solange die Praxis nicht behandeln und abrechnen kann. Praxen rechnen pro Sitzung ab; sind die Räume zu, ist der Umsatz ab Tag eins null.","signal":"Hohe Einrichtungsfinanzierung, angestellte Therapeuten.","when":"","cross":"","claim":"Ein Wasserschaden schließt die Praxis für fünf Wochen; 30.000 € Miete, Gehälter und Leasing werden ohne eine abrechenbare Sitzung fällig — die Betriebskostendeckung zahlt, und die Praxis öffnet zahlungsfähig wieder."}],"rec":[{"id":"cov_83","name":"Cyberversicherung","desc":"Krisenhilfe, Wiederherstellung und Meldung, wenn Patientendaten offenliegen oder die Praxissoftware verschlüsselt ist. Patientenakten sind Gesundheitsdaten — die sensibelste DSGVO-Kategorie mit den strengsten Pflichten und den hässlichsten Schlagzeilen.","signal":"Digitale Patientenakte, Online-Terminbuchung.","when":"","cross":"","claim":"Ransomware verschlüsselt die Praxissoftware an einem Montag: keine Termine, keine Akten, keine Abrechnung. Wiederherstellung und Pflichtmeldung kosten 22.000 € — und die finanzierte Krisenreaktion ist es, die aus der Datenschutzbeschwerde kein Bußgeld werden lässt."},{"id":"cov_84","name":"Firmen-Rechtsschutz","desc":"Rechtskosten für die Streits, die Praxen wirklich haben: Abrechnungsrückforderungen der Kostenträger, Arbeitsrecht, berufsrechtliche Verfahren. Branchenspezifische Heilberufe-Varianten existieren — Verfügbarkeit prüfen.","signal":"Kassenprüfungen, wachsendes Team.","when":"","cross":"","claim":"Eine Krankenkassenprüfung fordert 18.000 € Abrechnungen zurück; die Gegenwehr mit spezialisiertem Anwalt kostet 7.000 € und drückt die Rückforderung um zwei Drittel — ein Kampf, der sich nur lohnt, weil die Police ihn bezahlt hat."},{"id":"cov_85","name":"Flottenversicherung","desc":"Beim ambulanten Pflegedienst SIND die Autos der Betrieb: ein Dutzend Kleinwagen auf täglichen Touren heißt, Kfz-Schäden sind Monatsrealität — und eine unversicherte Lücke stoppt Touren.","signal":"Pflegedienste mit Tourenplänen.","when":"","cross":"","claim":"Die Morgentour einer Pflegekraft endet in einem Kreuzungsunfall — Personenschaden-Haftung plus Totalschaden. Der Flottenvertrag fängt beides auf und stellt vor der Nachmittagstour ein Ersatzfahrzeug."}],"opt":[{"id":"cov_86","name":"Gruppen-Unfall / bKV","desc":"Unfall-Einmalleistungen jenseits des gesetzlichen Systems und ein Arbeitgeber-Gesundheitszuschuss — doppelt glaubwürdig von einem Arbeitgeber aus dem Gesundheitswesen.","signal":"Körperlich belastete Teams, Recruiting-Schmerz.","when":"","cross":"","claim":"Eine Pflegekraft hebt zu Hause schwer und erleidet einen Bandscheibenvorfall — privat, also keine gesetzlichen Unfallleistungen. Die Gruppen-Unfall zahlt die Einmalleistung, die bKV beschleunigt ihre Physio; beide Geschichten machen im Team die Runde."},{"id":"cov_87","name":"Betriebsschließungsversicherung","desc":"Zahlt, wenn das Gesundheitsamt eine Einrichtung nach dem Infektionsschutzgesetz schließt.","signal":"Tagespflege-Strukturen, Gruppensettings.","when":"","cross":"","claim":"Ein Norovirus-Ausbruch schließt eine Tagespflege für eine Woche Desinfektion — rund 10.000 € an ausgefallenen Entgelten und Reinigung, gedeckt, wo das Bedingungswerk den Einrichtungstyp einschließt; Umfang prüfen."}]}},{"id":"pflegefitness","icon":"ti-scissors","accent":"#c0246f","bg":"var(--en-rose-50)","title":"Körperpflege & Fitness","types":["Friseursalons","Kosmetik & Nagelstudios","Barbershops","Fitnessstudios","Yoga & Personal Training","nicht-therapeutische Massage"],"policies":{"must":[{"id":"cov_88","name":"Betriebshaftpflicht","desc":"Zahlt, wenn die Dienstleistung selbst den Kunden verletzt — die Verätzung, die allergische Reaktion, die Trainingsverletzung durch falsche Anleitung — und wenn die Räume es tun: der nasse Boden, die lose Matte. In diesem Segment ist die Behandlungsschäden-Klausel das Herz der Police, denn die Verletzung passiert DURCH die Leistung.","signal":"Jeder Betrieb mit Behandlung oder Anleitung; nach neuen Angeboten fragen (Peelings, EMS), die das Bedingungswerk vielleicht nicht kennt.","when":"","cross":"","claim":"Eine Färbung geht schief, die Kundin erleidet Kopfhautverätzungen und stellenweisen Haarverlust — 18.000 € Schmerzensgeld und Behandlungskosten. In der Studio-Variante: Die falsch bestückte Maschine eines Trainers lässt ein Gewicht auf den Fuß eines Mitglieds fallen."},{"id":"cov_89","name":"Geschäftsinhalt + Betriebskosten","desc":"Neuwert für Einrichtung und Geräte plus Miete und Löhne, die weiterlaufen, solange das Studio zu ist. Diese Betriebe SIND ihre Räume; keine Räume, kein Umsatz.","signal":"Frische Renovierungen, geleaste Geräte.","when":"","cross":"","claim":"Ein Nachtbrand zerstört einen Salon eine Woche nach dem Umbau — 40.000 € Ausbau und Ware, plus sechs Wochen Miete und Löhne, getragen von der Betriebskostendeckung, während der Wiederaufbau läuft."}],"rec":[{"id":"cov_90","name":"Cyberversicherung","desc":"Krisenreaktion und Meldung, wenn Buchungssysteme und Mitgliederdaten offenliegen. Studios halten Namen, Gesundheitsnotizen und Zahlungsmandate — ein komplettes Identitäts-Kit.","signal":"Buchungs-Apps, Abo-Abrechnung.","when":"","cross":"","claim":"Das Konto der Buchungsplattform wird gehackt und Zahlungsdaten der Mitglieder liegen offen; Meldung, Forensik und Plattformwechsel kosten 12.000 € — und die ruhige, finanzierte Reaktion hält die Mitglieder vom Kündigen ab."},{"id":"cov_91","name":"Elektronikversicherung","desc":"Allgefahrendeckung für Studio- und Behandlungstechnik: EMS-Geräte, Laser- und Kosmetikgeräte, Soundanlagen — finanzierte Technik, die an Überspannung und verschütteten Flüssigkeiten stirbt, was Inhaltspolicen ausschließen.","signal":"Gerätegestützte Angebote.","when":"","cross":"","claim":"Eine Überspannung killt das EMS-System — 9.000 € und eine abgesagte Trainingswoche; gezahlt als Elektronikschaden."},{"id":"cov_92","name":"Firmen-Rechtsschutz","desc":"Rechtskosten für Mietvertrag und Team — die zwei Streits, die dieses Segment wirklich hat.","signal":"Mietverhandlungen, Trainer-Fluktuation.","when":"","cross":"","claim":"Der Vermieter bestreitet die erlaubte Nutzung, als der Salon Kosmetikbehandlungen dazunimmt; den Mietstreit zu klären kostet 6.000 € Gebühren — getragen von der Police."}],"opt":[{"id":"cov_93","name":"bKV / Gruppen-Unfall","desc":"Gesundheits-Zuschuss und Unfall-Einmalleistungen als Bindungsinstrumente in einem Gewerbe mit hoher Fluktuation, in dem ausgebildete Leute nebenan aufmachen können.","signal":"Klagen über Fluktuation.","when":"","cross":"","claim":"Eine Stylistin bleibt trotz Abwerbeversuch, weil die bKV des Arbeitgebers im Frühjahr ihre 800-€-Zahnrechnung übernommen hat — Loyalität zum Bruchteil einer Neubesetzung."},{"id":"cov_94","name":"Gewerbliche Gebäudeversicherung","desc":"Für das eigengenutzte Studio: Feuer, Wasser, Sturm am Gebäude selbst.","signal":"Eigene Immobilie.","when":"","cross":"","claim":"Sturmschäden an Dach und Verglasung des Studios kosten 20.000 € — ein Gebäudeschaden, den weder Inhalt noch Unterbrechung anfassen."}]}},{"id":"kfz","icon":"ti-car","accent":"#4a4838","bg":"var(--en-warmgrey-light)","title":"Kfz-Gewerbe","types":["Freie Werkstätten","Karosserie & Lack","Reifenservice","Fahrzeugaufbereitung","Kfz-Handel","Abschlepp- & Pannendienste"],"policies":{"must":[{"id":"cov_95","name":"Betriebshaftpflicht mit Kfz-Gewerbe-Deckungskonzept","desc":"Zahlt für Personen- und Sachschäden aus dem Betrieb — und, existenziell, für Schäden an Kundenfahrzeugen in Obhut: beim Bewegen, Bearbeiten, Verwahren. Eine Standard-Haftpflicht schließt Sachen in Obhut klassisch AUS — und genau das ist in diesem Gewerbe das ganze Geschäftsmodell. Die Gewerbelösung trägt auch rote Kennzeichen und Probefahrten.","signal":"Jeder Hof voller Kundenautos; Obhuts-Klausel und Rote-Kennzeichen-Deckung prüfen, bevor irgendetwas zugesagt wird.","when":"","cross":"","claim":"Ein Mitarbeiter rangiert ein Kundenauto auf dem Hof und verschätzt sich an einem Pfeiler — 22.000 € an einem Premiumfahrzeug. Standardpolice: als Obhutsschaden ausgeschlossen. Kfz-Gewerbe-Deckung: bezahlt. Zweiter Klassiker: die Probefahrt, die an der Kreuzung endet."},{"id":"cov_96","name":"Geschäftsinhaltsversicherung","desc":"Neuwert für das Betriebskapital der Werkstatt: Hebebühnen, Diagnostik, Werkzeug und das Ersatzteillager.","signal":"Frisch aufgerüstete Diagnose- und Kalibriertechnik, die älter ist als die Versicherungssumme.","when":"","cross":"","claim":"Ein Einbruch zielt auf genau das, was sich weiterverkauft: 30.000 € an Diagnosegeräten und Werkzeugwagen in einer Nacht weg — ersetzt zu heutigen Preisen, weil die Versicherungssumme aktuell war."},{"id":"cov_97","name":"Umwelt-Bausteine","desc":"Die Haftungs-Erweiterungen für das, was eine Werkstatt zwangsläufig handhabt: Öle, Kraftstoffe, Kühlmittel, Batterien. Wenn sie entweichen, ist die Rechnung eine öffentlich-rechtliche Sanierungsanordnung, kein normaler Schadenersatz — und nur die Umwelt-Bausteine zahlen.","signal":"Jede Werkstatt — fragen, wie Flüssigkeiten gelagert werden und wohin der Abscheider entwässert.","when":"","cross":"","claim":"Ein defekter Ölabscheider lässt Altöl ins Erdreich; die Behörde ordnet Aushub und Sanierung an — 50.000 €, fällig unabhängig vom Verschulden. Umfang von Umwelthaftpflicht- und Umweltschadendeckung in den Bedingungen prüfen."}],"rec":[{"id":"cov_98","name":"Betriebskostendeckung","desc":"Zahlt Miete, Löhne und Leasing, die weiterlaufen, während die Werkstatt nicht arbeiten kann. Hallen voller halbfertiger Aufträge verdienen während eines Wiederaufbaus nichts.","signal":"Gemietete Halle, finanzierte Ausstattung.","when":"","cross":"","claim":"Ein Elektrobrand schließt die Werkstatt für sieben Wochen; 35.000 € Fixkosten werden gegen null Durchsatz fällig — gezahlt von der Unterbrechungsdeckung. Der Kundenstamm überlebt die Schließung, weil der Betrieb sie überlebt."},{"id":"cov_99","name":"Maschinenversicherung","desc":"Zahlt beim inneren Ausfall hochwertiger stationärer Technik — den Bruch von innen, den Feuer- und Inhaltspolicen nicht decken.","signal":"Hebebühnen, Achsmessstände, Lackierkabinen.","when":"","cross":"","claim":"Die Hydraulik einer Hebebühne versagt mitten im Service — 15.000 € Reparatur und ein Beinahe-Unfall-Bericht, der allen neu erklärt, was „Maschinenbruch\" bedeutet."},{"id":"cov_100","name":"Firmen-Rechtsschutz","desc":"Rechtskosten für den Dauerzustand des Gewerbes: angefochtene Reparaturrechnungen und Gewährleistungsvorwürfe.","signal":"Geschichten über Kunden, die nicht zahlen.","when":"","cross":"","claim":"Ein Kunde bestreitet eine Motorreparatur über 4.000 € und droht mit Gericht; der Rechtsschutz zahlt Anwalt und den Gutachter, der die Diagnose beweist — die Rechnung wird bezahlt, und der Google-Bewertungskrieg bleibt kurz."}],"opt":[{"id":"cov_101","name":"Cyberversicherung","desc":"Krisendeckung für das digitale Rückgrat der Werkstatt: Planungssoftware, Diagnosesysteme, Kundendaten.","signal":"Digitale Auftragskarten, vernetzte Diagnose.","when":"","cross":"","claim":"Ransomware sperrt das Werkstattsystem; eine Woche keine Auftragskarten, keine Historie, keine Rechnungen — 14.000 € an Wiederherstellung und verlorenem Durchsatz."},{"id":"cov_102","name":"Gruppen-Unfall / bKV","desc":"Unfall-Einmalleistungen und Gesundheits-Zuschuss für ein Gewerbe, das hart um Mechatroniker kämpft.","signal":"Offene Stellen, die in Monaten gemessen werden.","when":"","cross":"","claim":"Ein Mechaniker bricht sich beim Mountainbiken das Handgelenk — kein gesetzlicher Schutz, sechs Wochen Ausfall; die Gruppen-Unfall zahlt das Tagegeld, das ihn finanziell heil hält."},{"id":"cov_103","name":"Kautionsversicherung","desc":"Versichererbürgschaften, wo Franchise- oder Partnerverträge Sicherheiten verlangen.","signal":"Markenpartner-Verträge mit Bürgschaftsklauseln.","when":"","cross":"","claim":"Ein Servicepartner-Vertrag verlangt eine 25.000-€-Garantie; die Kautionslinie stellt sie, ohne die Kreditlinie anzufassen."}]}},{"id":"bildung","icon":"ti-school","accent":"#0f7fa0","bg":"var(--en-iceblue-light)","title":"Bildung & Training","types":["Private Bildungsträger","Nachhilfeinstitute","Fahrschulen","Musik- & Kunstschulen","Coaching & Seminare","Sprachschulen"],"policies":{"must":[{"id":"cov_104","name":"Betriebshaftpflicht","desc":"Zahlt, wenn Teilnehmer in den Räumen, bei Veranstaltungen oder auf Ausflügen verletzt werden — und verteidigt den Aufsichtspflicht-Vorwurf, der jedem Vorfall mit Minderjährigen folgt. Die Erwartung der Eltern ist hoch und emotional; die Verteidigungsfunktion der Police zählt so viel wie ihre Zahlung.","signal":"Minderjährige in Kursen, Aktivitäten außer Haus, Gruppengrößen.","when":"","cross":"","claim":"Auf einem Kursausflug stürzt ein Neunjähriger vom Klettergerüst und bricht sich den Arm; die Eltern werfen mangelnde Aufsicht vor und fordern 40.000 €. Die Police finanziert die Verteidigung und zahlt, was die Aufsichtslage tatsächlich hergibt."},{"id":"cov_105","name":"Geschäftsinhalt + Elektronikversicherung","desc":"Neuwert für Unterrichtsräume und Ausstattung, mit Allgefahrendeckung für die Technik — und bei Musikschulen für die Instrumente, deren Bewertung und Außeneinsatz ausdrücklich geregelt gehören.","signal":"Instrumentenbestände, Laptop-Klassenräume.","when":"","cross":"","claim":"Ein geplatztes Heizungsrohr über ein Feiertagswochenende ruiniert das Klavier einer Musikschule und drei Schüler-Celli — 20.000 €, korrekt gezahlt nur, weil die Instrumente einzeln gelistet und bewertet waren statt pauschal im „Inhalt\"."}],"rec":[{"id":"cov_106","name":"Cyberversicherung","desc":"Krisenreaktion und Meldung, wenn Teilnehmerdaten oder Kursplattformen getroffen werden. Bildungsträger halten Kinderdaten und Zahlungsdaten der Eltern — eine Kombination, bei der die Öffentlichkeit null Toleranz für schlampigen Umgang hat.","signal":"Online-Kursplattformen, Ratenzahlung.","when":"","cross":"","claim":"Die Anmeldeplattform wird gehackt und Teilnehmerdaten inklusive Kinderdaten liegen offen; Forensik und Benachrichtigung jeder Familie kosten 15.000 € — und die professionell abgewickelte Reaktion ist es, die die Anmeldezahlen vor dem Einbruch bewahrt."},{"id":"cov_107","name":"Firmen-Rechtsschutz","desc":"Rechtskosten für die Streits, die Träger wirklich haben: Erstattungsforderungen, Vertragsstreit mit Teilnehmern, Auseinandersetzungen mit freien Dozenten.","signal":"Diskussionen über Stornobedingungen.","when":"","cross":"","claim":"Ein Elternteil verlangt volle Erstattung plus Schadenersatz, nachdem ein Kurs mitten im Jahr umgebaut wurde; der Streit geht vor Gericht und kostet 6.000 € Gebühren — getragen von der Police."},{"id":"cov_108","name":"Vermögensschaden-Haftpflicht","desc":"Zahlt, wenn falscher Rat oder ein Verwaltungsfehler einen Teilnehmer Geld kostet, ohne dass jemand verletzt wird: die verpasste Prüfungsanmeldung, der falsche Qualifikationsweg. Relevant, sobald Ergebnisse zugesagt werden.","signal":"Zertifizierte Abschlüsse, Prüfungsvorbereitungs-Versprechen.","when":"","cross":"","claim":"Ein Prüfungsvorbereiter berät falsch zur Anmeldefrist, und eine Schülerin verliert ein Jahr; die Familie beziffert Kursgebühren und entgangenes Einkommen auf 15.000 € — ein reiner Vermögensschaden, den nur diese Police deckt."}],"opt":[{"id":"cov_109","name":"Flottenversicherung","desc":"Für Fahrschulen sind die Fahrzeuge das Klassenzimmer: Doppelpedal-Autos im Dauereinsatz mit Fahranfängern — ein eigenes Kfz-Risikoprofil mit eigenem Deckungskonzept.","signal":"Jede Fahrschule.","when":"","cross":"","claim":"Ein Fahrschüler erstarrt an der Kreuzung, und die Bremse des Fahrlehrers kommt eine halbe Sekunde zu spät — 12.000 € über zwei Fahrzeuge. Die Häufigkeit ist hier die Geschichte; das spezielle Fahrschul-Deckungskonzept preist und managt sie."},{"id":"cov_110","name":"Gruppen-Unfallversicherung","desc":"Teilnehmer-Unfallschutz als Qualitätsmerkmal privater Träger — denn die gesetzliche Schüler-Unfallversicherung deckt Schulkontexte, keine privaten Kurse.","signal":"Eltern, die im Anmeldeformular nach Versicherung fragen.","when":"","cross":"","claim":"Eine Teilnehmerin verstaucht sich im Tanzkurs den Knöchel; die Gruppen-Unfall des Trägers zahlt eine Leistung ganz ohne Haftungsfrage — und die Anmeldebroschüre, die diese Deckung erwähnt, gewinnt den nächsten Vergleich gegen das Studio ohne."},{"id":"cov_111","name":"Dienstreiseversicherung","desc":"Kranken- und Rücktransportdeckung für reisende Dozenten und Trainer.","signal":"Trainer unterwegs, Seminare im Ausland.","when":"","cross":"","claim":"Eine Trainerin erkrankt bei einem Auslandsseminar; Behandlung und Umbuchung kosten 5.000 € — ein Fall für die Reisepolice."}]}},{"id":"events","icon":"ti-confetti","accent":"#d4651a","bg":"var(--en-orange-light)","title":"Veranstaltungen & Events","types":["Eventagenturen","Veranstaltungstechnik & Verleih","Messebau","Catering & mobile Gastronomie","DJs & Künstlerdienstleister","Hochzeits- & Eventplanung"],"policies":{"must":[{"id":"cov_112","name":"Betriebshaftpflicht mit Veranstalter-Deckungskonzept","desc":"Zahlt, wenn Besucher verletzt werden oder Eigentum beim Event beschädigt wird: der versagende Aufbau, das Kabel, über das jemand stolpert, die übernommenen Verkehrssicherungspflichten des ganzen Geländes. Eine Standard-Betriebshaftpflicht trägt das Veranstalterrisiko nicht automatisch, und Tarife deckeln Größe und Art der akzeptierten Events.","signal":"Jede Firma, die Events durchführt oder baut; gedeckte Größen und Formate vorab klären.","when":"","cross":"","claim":"Ein Traversenelement kommt während einer Show herunter und verletzt eine Besucherin schwer — 150.000 € Personenschaden gegen den Veranstalter. Genau für diesen Schaden existiert das Veranstalter-Deckungskonzept — und genau über ihn würde eine Standardpolice streiten."},{"id":"cov_113","name":"Elektronikversicherung + Transportdeckung","desc":"Das Paar, das dem Equipment folgt: Allgefahren-Elektronikdeckung für Ton, Licht und Video (inklusive gemieteter und geliehener Einheiten) und Transportdeckung für die Stunden im Transporter — denn die stationäre Inhaltspolice endet am Lagertor, und Event-Technik lebt auf der Straße.","signal":"Über Nacht beladene Transporter vor Shows, Mietequipment im Bestand.","when":"","cross":"","claim":"In der Nacht vor einem Festival werden 60.000 € Lichttechnik aus dem Transporter am Autobahnhotel gestohlen. Inhaltspolice: nicht auf dem Grundstück, abgelehnt. Die Elektronik-Transport-Kombination: bezahlt — und die Mietersatzbeschaffung rechtzeitig zur Türöffnung finanziert."},{"id":"cov_114","name":"Flottenversicherung","desc":"Gesetzlich vorgeschriebene Haftpflicht je Fahrzeug — und operativ das Rückgrat: Transporter und Anhänger mit schweren, sperrigen Lasten unter Termindruck.","signal":"Jeder Technik- und Baubetrieb.","when":"","cross":"","claim":"Ein Anhänger mit Bühnenpodesten schert auf nasser Rampe aus und beschädigt Anhänger, Ladung und ein geparktes Auto — Haftung, Eigenschaden und Ladungsfragen in einem Vorfall, sauber sortiert nur, weil Flotte, Transport und Equipment ineinandergreifend platziert waren."}],"rec":[{"id":"cov_115","name":"Montageversicherung","desc":"Schützt Bühnen, Stände und Konstruktionen bei Auf- und Abbau — der Phase, in der die meisten Sachschäden passieren und die Grenze zur Haftpflicht bewusst gezogen werden muss.","signal":"Eigener Bühnen- oder Messebau.","when":"","cross":"","claim":"Beim Aufbau kollabiert ein Bühnensegment, zerstört sich selbst und reißt eine Furche in den Hallenboden — 25.000 €, verteilt auf Eigenschaden (Montageversicherung) und Hallenschaden (Haftpflicht). Zu wissen, welche Police welche Hälfte nimmt, ist die Platzierungsarbeit."},{"id":"cov_116","name":"Geschäftsinhalt","desc":"Neuwert für Lager und Werkstatt, in denen das Equipment überwintert.","signal":"Nebensaison-Lager voller Werte.","when":"","cross":"","claim":"Ein Lagerbrand im Januar nimmt Podesterie, Verkabelung und Cases — 45.000 €, in einem Moment, in dem kein Umsatz da ist, um es aufzufangen."},{"id":"cov_117","name":"Firmen-Rechtsschutz","desc":"Rechtskosten für die Dauerkämpfe der Branche: Absagen, Vertragsstreit, offene Gagen.","signal":"Storno-Geschichten, Anzahlungsstreit.","when":"","cross":"","claim":"Ein Firmenkunde sagt ein fertig produziertes Event zwei Wochen vorher ab und verweigert die Stornogebühr; den 30.000-€-Vertrag durchzusetzen kostet 8.000 € Anwaltskosten — gezahlt von der Police."}],"opt":[{"id":"cov_118","name":"Cyberversicherung","desc":"Krisenreaktion und Meldung, wenn Ticketsysteme und Teilnehmerdaten getroffen werden.","signal":"Eigene Ticketshops, Teilnehmerdatenbanken.","when":"","cross":"","claim":"Der Ticketshop wird einen Monat lang geskimmt; Kartendaten-Meldung und Forensik kosten 18.000 € — noch vor der Erstattungswelle."},{"id":"cov_119","name":"Gruppen-Unfall","desc":"Einmalleistungen für Rigger und Aufbauteams, deren Risikoprofil nicht mit der Schicht endet.","signal":"Crews, die in der Höhe arbeiten.","when":"","cross":"","claim":"Ein Rigger verletzt sich beim privaten Klettern am freien Tag — kein gesetzlicher Schutz; die Einmalleistung der Gruppen-Unfall überbrückt die Monate der Genesung."},{"id":"cov_120","name":"Veranstaltungsausfallversicherung","desc":"Deckt Kosten und entgangene Einnahmen, wenn ein Event nicht stattfinden kann (Wetter, Ausfall von Schlüsselkünstlern, Venue-Ausfall). Eine Spezialsparte mit engem Annahmeappetit und Einzelfall-Underwriting.","signal":"Wann immer das ganze Jahr eines Kunden an einem Termin hängt.","when":"","cross":"","claim":"Ein Open Air wird verregnet, und 80.000 € versenkte Kosten verdampfen — der Schaden, für den es die Ausfalldeckung gibt. Bedarf notieren und je Einzelfall platzieren; nie eine Antwort zu Konditionen improvisieren."}]}},{"id":"produktion","icon":"ti-building-factory-2","accent":"#246b8f","bg":"#e6f3fa","title":"Leichte Produktion & Großhandel","types":["Metall- & Kunststoffverarbeitung","kleine Lebensmittelproduktion","Verpackung & Konfektionierung","technischer Großhandel","Baustoffhandel","Import & Distribution"],"policies":{"must":[{"id":"cov_121","name":"Betriebshaftpflicht / industrielle Haftpflicht mit erweiterter Produkthaftpflicht","desc":"Zahlt, wenn das Produkt nach dem Werkstor jemanden verletzt oder etwas beschädigt. Sobald unter eigenem Namen produziert, bearbeitet oder verkauft wird, ist die erweiterte Produkthaftpflicht der Kern — sie trägt die teuren Folgeszenarien wie die Aus- und Einbaukosten des Kunden für ein defektes Teil. Rückrufkosten aktiv ansprechen, denn der Rückruf trifft auch den fehlerfreien Zulieferer in der Kette. Ab einer gewissen Größe wird daraus eine industrielle Platzierung statt eines Standard-Gewerbetarifs.","signal":"Produkte unter eigenem Namen, Eigenmarken-Produktion, Zulieferung an größere Marken.","when":"","cross":"","claim":"Ein gefertigtes Bauteil versagt in der Baugruppe eines Kunden; der Kunde ruft die Charge zurück und reicht 90.000 € für Ausbau, Einbau und Rückruflogistik weiter. Eine Basis-Produkthaftpflicht zahlt einen Bruchteil; die erweiterte Deckung mit Rückruf-Baustein trägt es."},{"id":"cov_122","name":"Geschäftsinhalt + Maschinenversicherung","desc":"Neuwert für Anlagen und Läger, plus Maschinenbruchdeckung für den Ausfall VON INNEN — den Spindelcrash, den Antriebsschaden — den Feuerpolicen nicht anfassen.","signal":"Produktionslinien, CNC-Parks, volle Rohstofflager.","when":"","cross":"","claim":"Ein CNC-Spindelcrash zerlegt das Bearbeitungszentrum — 45.000 € Reparatur. Kein Feuer, kein Sturm, kein Einbruch: Nur die Maschinenversicherung zahlt, und die Unterbrechungsdeckung (nächster Punkt) übernimmt den Stillstand."},{"id":"cov_123","name":"Betriebsunterbrechung","desc":"Zahlt den entgangenen Deckungsbeitrag und die weiterlaufenden Kosten, solange die Produktion steht. In der Fertigung ist der Engpass existenziell: eine Maschine, ein Lager, ein Schlüsselkunde.","signal":"Fragen, der Ausfall welcher einen Maschine alles stoppt.","when":"","cross":"","claim":"Ein Brand an der einzigen Fertigungslinie stoppt die Produktion drei Monate; 250.000 € Deckungsbeitrag und laufende Kosten sind der eigentliche Schaden — ein Mehrfaches des Brandschadens selbst. Diese Deckung entscheidet, ob die Kundenliste überlebt."}],"rec":[{"id":"cov_124","name":"Transportversicherung (Waren / Verkehrshaftung)","desc":"Versichert die eigene Ware in Bewegung, ein- und ausgehend, und wo relevant die Haftung als Frachtführer für fremde Ware. Im Großhandel ist die Ware unterwegs das zweite Lager.","signal":"Importcontainer, eigene Auslieferflotte, Incoterms-Gespräche.","when":"","cross":"","claim":"Ein Importcontainer kommt seewassergeschädigt an — 35.000 € Ware ruiniert, bevor sie je das Lager erreicht hat, das die Inhaltspolice schützt. Die Transportdeckung zahlt; die Inhaltspolice könnte es nie."},{"id":"cov_125","name":"Flottenversicherung","desc":"Gesetzlich vorgeschrieben je Fahrzeug und operativ zentral für den Auslieferbetrieb.","signal":"Eigene LKW auf täglichen Touren.","when":"","cross":"","claim":"Ein Lieferwagen-Unfall bedeutet Totalschaden und einen verletzten anderen Fahrer — der Flottenvertrag fängt Haftungs- und Eigenschadenseite auf und hält den Lieferplan mit einem Ersatzfahrzeug am Leben."},{"id":"cov_126","name":"Cyberversicherung","desc":"Krisenreaktion, Wiederherstellung und Unterbrechungsdeckung für die Produktions-IT: ERP, Lagerverwaltung, Maschinensteuerung. Der Ransomware-Stillstand ist die moderne Betriebsunterbrechung — und Sachpolicen decken ihn nicht.","signal":"ERP-gesteuerte Planung, vernetzte Maschinen.","when":"","cross":"","claim":"Ransomware verschlüsselt ERP und Lagersystem; Kommissionierung, Produktionsplanung und Fakturierung stehen zehn Tage — 120.000 € Unterbrechung und Wiederherstellung, nichts davon ein Sachschaden."}],"opt":[{"id":"cov_127","name":"Montageversicherung","desc":"Schützt gelieferte Maschinen während Installation und Inbetriebnahme beim Kunden — dem Fenster, in dem sie von niemandem bezahlt und allem ausgesetzt sind.","signal":"Verträge mit Lieferung plus Installation.","when":"","cross":"","claim":"Eine Maschine wird bei der Inbetriebnahme beim Kunden durch einen Hebefehler beschädigt — 30.000 €, exakt in der Lücke zwischen Transportdeckung (endete bei Anlieferung) und Sachpolice des Kunden (noch nicht abgenommen)."},{"id":"cov_128","name":"Photovoltaikversicherung","desc":"Anlagen- und Ertragsdeckung für die Hallendach-Anlage.","signal":"Produktionshallen mit PV.","when":"","cross":"","claim":"Hagel zerlegt ein Drittel der Dachanlage — 40.000 € an Modulen und entgangener Einspeisung, ein PV-Schaden, über den die Gebäudedeckung streiten würde."},{"id":"cov_129","name":"Kautionsversicherung","desc":"Bürgschaften für Liefer- und Rahmenverträge, die Sicherheiten verlangen.","signal":"Bürgschaftsklauseln in Kundenverträgen.","when":"","cross":"","claim":"Ein Rahmenvertrag verlangt eine Vertragserfüllungsbürgschaft über 50.000 €; die Kautionslinie stellt sie — und die Kreditlinie bleibt frei für Rohmaterial."},{"id":"cov_130","name":"bAV / Gruppen-Unfall / bKV","desc":"Alters-, Unfall- und Gesundheitsleistungen als Bindungspaket für gewerbliche Fachkräfte.","signal":"Zerspaner, deren Nachbesetzung Monate dauert.","when":"","cross":"","claim":"Ein Maschinenführer wird beim privaten Motorradunfall verletzt, bekommt die Gruppen-Unfall-Einmalleistung und hält seinen Lebensstandard durch die Genesung — die Geschichte tut mehr für die Bindung als jedes Poster."},{"id":"cov_131","name":"Betriebsschließungsversicherung","desc":"Zahlt bei behördlicher Schließung in der Lebensmittelproduktion nach dem Infektionsschutzgesetz.","signal":"Jede Lebensmittellinie.","when":"","cross":"","claim":"Ein Listerienbefund schließt die Produktion für zwei Wochen Grundreinigung und Chargenvernichtung — 60.000 € an Ausfall und Entsorgung; Erregerliste im aktuellen Bedingungswerk prüfen."}]}},{"id":"landwirtschaft","icon":"ti-tractor","accent":"#4e7a27","bg":"var(--en-leaf-light)","title":"Landwirtschaft & Direktvermarktung","types":["Ackerbau","Tierhaltung","Sonderkulturen & Obstbau","Lohnunternehmen","Hofläden & Direktvermarktung","Energiewirte (Biogas/PV)"],"policies":{"must":[{"id":"cov_132","name":"Landwirtschaftliche Betriebshaftpflicht","desc":"Zahlt für die Verletzungen und Schäden, die ein Hof durch bloßes Existieren erzeugt: ausbrechende Tiere, auslaufende Gülle, Maschinen auf öffentlichen Straßen, Besucher auf dem Hof. Die Tierhalterhaftung allein ist verschuldensunabhängig — der Halter haftet für das, was das Tier tut, egal ob jemand etwas falsch gemacht hat.","signal":"Jeder Betrieb; prüfen, ob das Bedingungswerk den tatsächlichen Mix trägt (Tierhaltung, Lohnarbeit, Besucher, Hofevents).","when":"","cross":"","claim":"Rinder brechen in der Dämmerung durch einen Zaun auf die Straße; ein Auto erfasst eines, der Fahrer wird schwer verletzt — 200.000 € aus verschuldensunabhängiger Tierhalterhaftung. Dieses eine Szenario rechtfertigt die Police."},{"id":"cov_133","name":"Landwirtschaftliche Inhaltsversicherung","desc":"Neuwert für das, was der Hof hält: Ernte, Vorräte, Futter, Betriebseinrichtung und Tiere im Rahmen des Bedingungswerks. Das Vermögen eines Hofs liegt in seinen Scheunen — und Feuer ist sein ältester Feind.","signal":"Volle Läger nach der Ernte, gemischte Lagerung von Heu und Maschinen.","when":"","cross":"","claim":"Ein Scheunenbrand nimmt das Heulager und zwei abgestellte Maschinen — 120.000 € in einer Nacht. Die Zahlung entsprach dem Schaden nur, weil die Summen nach der Ernte neu bewertet waren — fragen, wann das zuletzt passiert ist."},{"id":"cov_134","name":"Fahrbare Maschinen + gewerbliche Gebäudeversicherung","desc":"Maschinendeckung für den selbstfahrenden Park (Traktoren, Erntetechnik — enormes Kapital, das draußen arbeitet und in der Saison brennt oder bricht) und Gebäudedeckung für die Hofgebäude gegen Feuer, Sturm und Elementar.","signal":"Jeder mechanisierte Betrieb — fragen, was der Mähdrescher wert ist und was sein Ausfall mitten in der Ernte kostet.","when":"","cross":"","claim":"Ein Mähdrescher fängt in Erntewoche eins auf dem Feld Feuer — 150.000 € Maschinenschaden plus die Jagd nach Ersatzkapazität, während die Frucht steht. Die Maschinenpolice zahlt die Maschine; die Gebäudepolice hätte die Scheune übernommen, in der er zum Glück nicht stand."}],"rec":[{"id":"cov_135","name":"Photovoltaikversicherung","desc":"Anlagen- und Ertragsversicherung für Dach- und Freiflächenanlagen — für viele Höfe inzwischen ein eigener Ertragszweig.","signal":"Einspeiseerlöse in den Büchern, Ausbaupläne.","when":"","cross":"","claim":"Ein Hagelsturm zerstört 40.000 € an Modulen auf dem Scheunendach und Monate an Einspeiseerlösen — ein PV-Schaden, der Hardware und Ertrag beides deckt."},{"id":"cov_136","name":"Firmen-Rechtsschutz","desc":"Rechtskosten für die typischen Kämpfe des Hofs: Pachtstreit, Nachbarschaftskonflikte, Förderrückforderungen, Arbeitsrecht. Spezielle Agrar-Varianten existieren — Verfügbarkeit prüfen.","signal":"Gepachtete Flächen, Förderabhängigkeit.","when":"","cross":"","claim":"Ein Verpächter kündigt ein langjähriges Pachtverhältnis nicht ordnungsgemäß; die Pacht durchs Gericht zu verteidigen kostet 9.000 € Gebühren — getragen von der Police, und die Fläche bleibt in der Fruchtfolge."},{"id":"cov_137","name":"Betriebskostendeckung","desc":"Zahlt die laufenden Kosten nach einem Großschaden, während der Betrieb wieder aufbaut.","signal":"Finanzierte Betriebe mit Kapitaldienst.","when":"","cross":"","claim":"Nach dem Scheunenbrand von oben laufen Futterzukäufe, Kapitaldienst und Löhne monatelang weiter, bis sich der Betrieb normalisiert — 30.000 € fortlaufende Kosten, die die Betriebskostendeckung auffängt."}],"opt":[{"id":"cov_138","name":"Produkthaftpflicht / Betriebsschließung bei Direktvermarktung","desc":"Der Hofladen macht den Landwirt zum Lebensmittelunternehmer — mit Lebensmittel-Produkthaftung und dem Risiko der behördlichen Schließung, das die Basis-Hofpolice nie vorgesehen hat.","signal":"Hofläden, Verarbeitung, Marktstände, Online-Verkauf.","when":"","cross":"","claim":"Eine Charge Rohmilchkäse aus der Hofkäserei wird mit Erkrankungen in Verbindung gebracht; Rückruf, Vernichtung und zwei Wochen behördliche Schließung des Ladens kosten 25.000 € — Schäden, die in Produkthaftpflicht und Schließungsdeckung leben, nicht in der Basispolice. Prüfen, dass Verarbeitung und Verkauf mitversichert sind."},{"id":"cov_139","name":"Cyberversicherung","desc":"Krisendeckung für den digitalen Kern des Hofs: Melkroboter, Fütterungssysteme, Stallsteuerung, Herdenmanagement-Daten.","signal":"Automatisierte Ställe, Smart-Farming-Tools.","when":"","cross":"","claim":"Herdenmanagement und Melksystem werden von Ransomware verschlüsselt; Handbetrieb, Wiederherstellung und verlorene Milchqualitätsdaten kosten 20.000 € über eine schlimme Woche."},{"id":"cov_140","name":"Gruppen-Unfall / bKV","desc":"Unfall-Einmalleistungen und Gesundheits-Zuschüsse dort, wo das landwirtschaftliche gesetzliche System endet: Freizeit, Leistungsniveau und die mitarbeitenden Familienangehörigen, deren Status oft unklar ist.","signal":"Familienarbeitskräfte, Generationenübergabe.","when":"","cross":"","claim":"Der Sohn des Landwirts verunglückt in seinen Einarbeitungsjahren schwer beim privaten Sport — die gesetzlichen Leistungen sind dünn, und die Gruppen-Unfall-Einmalleistung ist es, die die Familie durchträgt. Ernteertrags- und Tierversicherungen sind Spezialsparten mit eigenem Markt — offen sagen und gesondert platzieren."}]}}],"verticals":[{"id":"ver_145","deck":"vertical","title":"Bau- und Ausbauhandwerk","tagline":"Kolonnen auf fremdem Eigentum, Werte im Bus","icon":"ti-tools","category":"Haftpflicht","products":[{"id":"p_141","name":"Haftung nach Abnahme","why":"Handwerksmängel tauchen lange nach bezahlter Rechnung auf, und die Forderung landet beim Betrieb — ohne Nachhaftungs- und Bearbeitungsschäden-Klausel steigt die Police genau dann aus.","pivot":"Wer zahlt, wenn Ihre Arbeit Monate nach der Abnahme einen Schaden verursacht?","listen":"Nachbesserungen, Gewährleistungsterminen, „wir sind jeden Tag in fremden Häusern.\""},{"id":"p_142","name":"Werkzeug unterwegs","why":"Die stationäre Inhaltspolice endet an der Werkstatttür, und das Kapital eines Handwerksbetriebs fährt in Transportern herum — die Lücke ist total, nicht teilweise.","pivot":"Was ist der Wiederbeschaffungswert von dem, was gerade in den Bussen liegt?","listen":"„meine ganze Ausrüstung ist im Bus\", über Nacht beladene Anhänger"},{"id":"p_143","name":"Bauleistung / Montage","why":"Ein unfertiges Bauwerk und eine gelieferte, noch nicht eingebaute Anlage gehören in keine Police für fertige Gebäude — der Betrieb trägt den Schaden bis zur Übergabe.","pivot":"Sind Sie auf Neubauten unterwegs, oder installieren Sie hochwertige Anlagen?","listen":"Rohbau, gelieferten, noch nicht eingebauten Geräten auf der Baustelle"},{"id":"p_144","name":"Kaution","why":"Einbehaltene Sicherheiten und Bankbürgschaften binden die Liquidität über Jahre; Versichererbürgschaften geben sie frei — ein Finanzierungsgespräch im Versicherungsgewand.","pivot":"Behalten Auftraggeber Sicherheiten ein oder verlangen Bürgschaften?","listen":"„die Kreditlinie ist eng\", öffentlichen Ausschreibungen"}]},{"id":"ver_150","deck":"vertical","title":"Gebäudereinigung & Facility Services","tagline":"Schlüssel in der Hand, in fremden Räumen","icon":"ti-spray","category":"Haftpflicht","products":[{"id":"p_146","name":"Schlüsselverlust & Tätigkeitsschäden","why":"Die zwei wahrscheinlichsten Schäden des Gewerks — der verlorene Generalschlüssel und die beschädigte Fläche unter dem Tuch — sind genau die zwei Dinge, die Basispolicen einschränken oder deckeln.","pivot":"Haben Sie Generalschlüssel oder Alarmcodes?","listen":"Zugang nach Feierabend, „wir haben den Generalschlüssel.\""},{"id":"p_147","name":"Rechtsschutz (Arbeitsrecht)","why":"Viel Personal plus hohe Fluktuation macht das Arbeitsgericht zum wahrscheinlichsten Gerichtssaal der Branche — und in erster Instanz zahlt jede Seite ihren Anwalt selbst, egal wer gewinnt.","pivot":"Wie viele Leute — und wie viel Wechsel im Team?","listen":"Kündigungsgeschichten, Lohnstreit"},{"id":"p_148","name":"Flotte","why":"Tägliche Fahrten zwischen Objekten machen Kfz-Schäden zum Häufigkeitsthema, das Einzelpolicen schlecht und ein Flottenvertrag gut managt.","pivot":"Wie kommen die Kolonnen zwischen den Objekten hin und her?","listen":"mehreren Objekten pro Tag"},{"id":"p_149","name":"Cyber","why":"Die Einsatzplanungssoftware hält Alarmcodes und Gebäudepläne der Kunden — ein Hack hier ist ein physischer Sicherheitsvorfall bei allen Kunden gleichzeitig.","pivot":"Wo liegen Zugangscodes und Einsatzpläne?","listen":"Planungs-Apps, Kundenportalen"}]},{"id":"ver_155","deck":"vertical","title":"Garten- und Landschaftsbau","tagline":"Maschinen im Freien, Pflichten auf fremdem Grund","icon":"ti-plant-2","category":"Haftpflicht","products":[{"id":"p_151","name":"Winterdienst-Haftung","why":"Streuverträge übertragen die Verkehrssicherungspflicht des Eigentümers auf den Betrieb — ein vereister Morgen kann eine sechsstellige Personenschadenforderung direkt an den Unternehmer bringen.","pivot":"Räumen oder streuen Sie im Winter?","listen":"„der Winterdienst hält uns über die Saison\", Jahresverträgen"},{"id":"p_152","name":"Fahrbare Maschinen","why":"Bagger und Mäher arbeiten und schlafen draußen, wo keine Inhaltspolice hinreicht — und sie sind der einfachste hochwertige Diebstahl im deutschen Gewerbe.","pivot":"Bleibt Gerät über Nacht auf Anhängern oder Baustellen?","listen":"„das bleibt alles auf dem Hänger.\""},{"id":"p_153","name":"Umwelt-Bausteine","why":"Abdrift und Kraftstoffleckagen erzeugen öffentlich-rechtliche Sanierungsanordnungen, die Standard-Bedingungswerke ausschließen — der Behörde ist egal, wer schuld war.","pivot":"Bringen Sie Pflanzenschutzmittel aus?","listen":"„wir behandeln Flächen\", Spritzplänen"},{"id":"p_154","name":"Bauleistung","why":"Mauern, Beläge und Pflanzungen gehören bis zur Abnahme dem Betrieb — Wetterschäden davor sind allein sein Verlust.","pivot":"Stehen größere Neuanlagen an?","listen":"Ausschreibungssprache, Projekten in Phasen"}]},{"id":"ver_160","deck":"vertical","title":"Gastronomie & Hotellerie","tagline":"Gäste, Lebensmittel und eine Behörde, die schließen kann","icon":"ti-tools-kitchen-2","category":"Inhalt & Ertrag","products":[{"id":"p_156","name":"Betriebsschließung","why":"Das Gesundheitsamt kann einen Lebensmittelbetrieb per Verwaltungsakt schließen, und weder Haftpflicht noch Sachpolice zahlen dafür einen Cent — das eine Schließungsrisiko, das nur Lebensmittel haben.","pivot":"Was passiert, wenn das Gesundheitsamt Sie eine Woche zumacht?","listen":"Kontrollgeschichten, Hygiene-Audits"},{"id":"p_157","name":"Unterversicherung Inhalt","why":"Die Gastronomie investiert laufend nach — Versicherungssummen altern hier schneller als überall sonst, und eine veraltete Summe kürzt die Zahlung anteilig, genau wenn die Küche brennt.","pivot":"Wann hat die Versicherungssumme zuletzt Ihre Küchenrechnungen gesehen?","listen":"frischer Renovierung, neuer Küchenlinie"},{"id":"p_158","name":"Betriebsunterbrechung","why":"Dünne Margen auf hohen Fixkosten heißen: Die Schließung übertrifft meist den Brand — Miete und Löhne pausieren nicht für Reparaturen.","pivot":"Wie lange tragen Rücklagen Miete und Löhne?","listen":"knappen Margen, hoher Fixmiete"},{"id":"p_159","name":"bKV / Benefits","why":"In der Branche mit dem schlimmsten Personalmangel unterscheidet ein sichtbarer Gesundheits-Benefit einen Arbeitgeber pro Euro stärker als jede Lohnerhöhung.","pivot":"Wie schwer ist es gerade, Leute zu finden?","listen":"„montags haben wir zu, weil uns Personal fehlt.\""}]},{"id":"ver_165","deck":"vertical","title":"Einzelhandel","tagline":"Die Ware ist das Kapital, die Kundschaft das Risiko","icon":"ti-building-store","category":"Inhalt & Ertrag","products":[{"id":"p_161","name":"Saisonale Unterversicherung","why":"Der Warenwert zur Saisonspitze kann das Doppelte des Jahresschnitts sein, und der Einbrecher kennt den Kalender auch — eine März-Versicherungssumme trifft auf einen November-Schaden.","pivot":"Was liegt zur Saisonspitze auf der Fläche und im Lager — und was steht in der Police?","listen":"„vor Weihnachten ist das Lager voll.\""},{"id":"p_162","name":"Cyber / Kasse","why":"Kasse und Webshop sind die Umsatzleitung — stehen sie, ist der Laden offen und verdient nichts, und Kartendaten bringen Meldepflichten obendrauf.","pivot":"Was passiert, wenn samstags die Kasse ausfällt?","listen":"Webshop, Kartenzahlung"},{"id":"p_163","name":"Betriebsunterbrechung","why":"Der Mietvertrag in der A-Lage fakturiert durch den Wiederaufbau weiter — die Miete ist der Schaden, selbst wenn die Ware gerettet ist.","pivot":"Setzt der Vermieter die Miete nach einem Wasserschaden aus? Eben","listen":"Gesprächen über die teure Lage"},{"id":"p_164","name":"Transport","why":"Ware im eigenen Transporter zwischen Großhandel und Filialen ist durch nichts gedeckt — die Inhaltspolice endet an der Ladentür, und die Kfz-Haftpflicht zahlt nur den anderen.","pivot":"Bewegen sich Waren zwischen Filialen oder über eigene Abholungen?","listen":"eigenen Fahrten zum Großmarkt"}]},{"id":"ver_170","deck":"vertical","title":"Immobilienwirtschaft & Hausverwaltung","tagline":"Fremdes Geld und fremde Gebäude","icon":"ti-building-skyscraper","category":"Vermögensschaden","products":[{"id":"p_166","name":"Pflicht-Vermögensschadenhaftpflicht","why":"Fehler von Verwaltern und Maklern vernichten Geld, nicht Sachen — und das Berufsrecht macht die Deckung zur Erlaubnisbedingung: Ein veraltetes Niveau ist Compliance-Lücke und persönliche Haftungslücke zugleich.","pivot":"Entspricht Ihre Deckung dem, was Ihre Erlaubnis verlangt?","listen":"neuen WEG-Mandaten, wachsenden verwalteten Einheiten"},{"id":"p_167","name":"Elementar","why":"Starkregen- und Rückstauschäden sind die am schnellsten wachsenden Gebäudeschäden Deutschlands, und die Standard-Gebäudepolice zahlt darauf ohne Elementar-Baustein nichts.","pivot":"Welche Gebäude im Bestand haben Elementardeckung?","listen":"Starkregen-Erzählungen, vollgelaufenen Kellern"},{"id":"p_168","name":"Photovoltaik","why":"Eine PV-Anlage ist weder klar Gebäude noch klar Inhalt — unzugeordnet zeigen nach dem Brand beide Versicherer aufeinander.","pivot":"Kommt PV auf die Dächer?","listen":"WEG-Beschlüssen zu Solar"},{"id":"p_169","name":"Rechtsschutz","why":"Miet- und WEG-Streit ist das Betriebsgeräusch dieses Geschäfts, und Rechtskosten entscheiden, welche Kämpfe bezahlbar sind.","pivot":"Wie viele offene Mietstreitigkeiten laufen gerade?","listen":"Räumungsklagen, Rückständen"}]},{"id":"ver_175","deck":"vertical","title":"Beratende Berufe & Finanzdienstleister","tagline":"Der Rat ist das Produkt, die Haftung ist persönlich","icon":"ti-briefcase","category":"Vermögensschaden","products":[{"id":"p_171","name":"Vermögensschaden-Haftpflicht","why":"Wenn das Produkt Rat ist, ist jeder Fehler ein reiner Vermögensschaden — die eine Kategorie, die die Betriebshaftpflicht ausdrücklich ausschließt und die das Gesetz bei erlaubnispflichtigen Berufen gedeckt sehen will.","pivot":"Was passiert, wenn ein Rat nachweislich falsch war und der Mandant ihn beziffert?","listen":"wachsenden Mandaten, neuen erlaubnispflichtigen Tätigkeiten"},{"id":"p_172","name":"Cyber","why":"Mandantendaten sind die ganze Beziehung; ein Leak ist DSGVO-Fall, Haftungsfall und Reputationsereignis zugleich — und nur finanzierte, professionelle Reaktion fängt alle drei.","pivot":"Wo liegen die Mandantendaten, und wer kommt dran?","listen":"Cloud-Tools, Homeoffice"},{"id":"p_173","name":"Rechtsschutz","why":"Beratungen schreiben offene Honorare ab, weil Klagen teuer wirkt — Rechtsschutz macht aus Abschreibungen wieder Forderungen.","pivot":"Schon mal einem Honorar hinterhergelaufen und an Klage gedacht?","listen":"Forderungsärger"},{"id":"p_174","name":"Benefits","why":"In einem People-Business verlassen die Assets jeden Abend das Haus — Vorsorge- und Gesundheitsleistungen sind der günstigste Weg, dass sie wiederkommen.","pivot":"Wie halten Sie gute Leute davon ab, sich abwerben zu lassen?","listen":"Recruiting-Frust"}]},{"id":"ver_180","deck":"vertical","title":"IT- und Digitaldienstleister","tagline":"Ihr Fehler wird zum Stillstand des Kunden","icon":"ti-code","category":"Vermögensschaden","products":[{"id":"p_176","name":"IT-Vermögensschadenhaftpflicht","why":"Softwarefehler machen nichts kaputt, sie halten Dinge an — und die stehende Produktionslinie des Kunden ist ein reiner Vermögensschaden, den nur das IT-Deckungskonzept trägt.","pivot":"Wenn Ihr Update die Produktion des Kunden anhält — wer zahlt den Stillstand?","listen":"SLAs, Go-live-Terminen, Managed-Services-Verträgen"},{"id":"p_177","name":"Eigene Cyberdeckung","why":"Der Hack einer IT-Firma kaskadiert in jeden betreuten Kunden, und ein Dienstleister, der die eigene Krisenreaktion nicht finanzieren kann, verliert über Nacht sein Glaubwürdigkeits-Kapital.","pivot":"Blieben Ihre Kunden, wenn es Sie selbst erwischt?","listen":"Admin-Zugriff auf Kundensysteme"},{"id":"p_178","name":"Elektronik","why":"Die Produktionsanlage der Firma ist ihre Hardware, und die Arten, wie Hardware wirklich stirbt — Überspannung, Sturz, Diebstahl — schließen Inhaltspolicen genau aus.","pivot":"Was ist die Hardware in Büro und Rack wert?","listen":"eigenem Serverraum, Workstations"},{"id":"p_179","name":"Rechtsschutz","why":"Abnahme- und Scope-Streit ist der typische Konflikt der Branche — gewonnen wird er mit finanzierten Anwälten, nicht mit E-Mail-Threads.","pivot":"Gibt es Streit um Projektabnahmen?","listen":"„der Kunde nimmt nicht ab.\""}]},{"id":"ver_185","deck":"vertical","title":"Agenturen, Marketing & Medien","tagline":"Veröffentlichte Arbeit, fremde Rechte","icon":"ti-palette","category":"Vermögensschaden","products":[{"id":"p_181","name":"Medienhaftung / Vermögensschaden","why":"Alles, was eine Agentur ausliefert, ist Veröffentlichung — und Veröffentlichungsrisiko (Bildrechte, Marken, Persönlichkeitsrechte) ist reiner Vermögensschaden, den nur ein medienkundiges Bedingungswerk trägt.","pivot":"Wer klärt Bild-, Musik- und Markenrechte — und wer zahlt, wenn es schiefgeht?","listen":"Stockfotos, Influencer-Kampagnen"},{"id":"p_182","name":"Cyber","why":"Admin-Zugriff auf Kunden-Werbekonten plus Budgetgewalt heißt: Ein gephishter Login gibt fremdes Geld aus — und der Kunde will es von der Agentur zurück.","pivot":"Verwalten Sie Werbekonten und Budgets Ihrer Kunden?","listen":"„wir fahren deren komplettes Performance-Budget.\""},{"id":"p_183","name":"Elektronik","why":"Produktionstechnik verdient unterwegs und wird aus Transportern gestohlen — genau dort, wo die Büro-Inhaltspolice nicht mehr gilt.","pivot":"Was fährt in einem Transporter zum Dreh?","listen":"Kameralisten, Mietequipment"},{"id":"p_184","name":"Rechtsschutz","why":"Nutzungsrechts- und Honorarstreit kommt nach dem Ende der Beziehung, wenn der Goodwill weg ist und nur finanzierte Durchsetzung wirkt.","pivot":"Schon mal nach Projektende über Nutzungsrechte gestritten?","listen":"Scope-Creep-Geschichten"}]},{"id":"ver_190","deck":"vertical","title":"Heilberufe & Pflege","tagline":"Körperkontakt plus die sensibelsten Daten","icon":"ti-stethoscope","category":"Haftpflicht","products":[{"id":"p_186","name":"Berufshaftpflicht","why":"Behandlung am Körper macht Personenschadens-Vorwürfe statistisch unvermeidlich — und die Verteidigung des unbegründeten Vorwurfs kostet so viel wie die Zahlung des begründeten.","pivot":"Wer verteidigt den Behandlungsfehler-Vorwurf — berechtigt oder nicht?","listen":"neuen Behandlungsmethoden, delegierten Behandlungen"},{"id":"p_187","name":"Cyber","why":"Patientenakten sind Gesundheitsdaten — die geschützteste DSGVO-Kategorie — und eine gesperrte Praxissoftware stoppt Behandlung, Terminplan und Abrechnung gleichzeitig.","pivot":"Was passiert, wenn die Praxissoftware an einem Montag verschlüsselt ist?","listen":"digitaler Patientenakte, Online-Terminen"},{"id":"p_188","name":"Betriebskostendeckung","why":"Praxen rechnen pro Sitzung ab; ein geschlossener Raum heißt null Umsatz ab Tag eins, während Miete, Gehälter und Geräteleasing voll weiterlaufen.","pivot":"Wenn die Praxis vier Wochen steht — was wird Ihnen trotzdem in Rechnung gestellt?","listen":"hoher Einrichtungsfinanzierung"},{"id":"p_189","name":"Flotte","why":"Beim ambulanten Dienst sind die Fahrzeuge die Leistung — ein Dutzend Kleinwagen auf täglichen Touren erzeugt monatliche Kfz-Schäden und verträgt keinen Tag ohne Ersatzfahrzeug.","pivot":"Wie viele Autos sind täglich auf Tour?\" (Pflegedienste)","listen":"Tourenplänen, fahrenden Mitarbeitern"}]},{"id":"ver_195","deck":"vertical","title":"Körperpflege & Fitness","tagline":"Den ganzen Tag am Kunden","icon":"ti-scissors","category":"Haftpflicht","products":[{"id":"p_191","name":"Behandlungs-/Trainingsschäden","why":"Die Verletzung passiert hier durch die Leistung selbst — Chemie auf Haut, Last auf Körpern — die Behandlungsschäden-Klausel ist das Herz der Police, und neue Angebote überholen alte Bedingungswerke.","pivot":"Was, wenn eine Färbung, eine Behandlung oder eine Einheit eine Verletzung auslöst?","listen":"neuen Angeboten (chemische Peelings, EMS-Training)"},{"id":"p_192","name":"Inhalt + BU","why":"Diese Betriebe sind ihre Räume — kein Studio, kein Umsatz — während Miete und geleaste Geräte durch den Wiederaufbau weiter fakturieren.","pivot":"Das Studio brennt Samstagnacht — wann öffnen Sie wieder, und wer zahlt solange die Miete?","listen":"frischer Renovierung, geleasten Geräten"},{"id":"p_193","name":"Cyber","why":"Buchungs- und Abo-Systeme halten Identitäts- und Zahlungspakete der Mitglieder, und die Krisenreaktion eines kleinen Studios ist ohne Deckung unbezahlbar.","pivot":"Wo liegen Mitglieder- und Zahlungsdaten?","listen":"Buchungs-Apps, Abo-Abrechnung"},{"id":"p_194","name":"Benefits","why":"Ausgebildete Leute können mit Stuhl und Spiegel nebenan aufmachen — Bindungs-Benefits sind billiger als der Umsatz, den sie mitnehmen.","pivot":"Wie verhindern Sie, dass ausgebildete Leute nebenan aufmachen?","listen":"Fluktuationsklagen"}]},{"id":"ver_200","deck":"vertical","title":"Kfz-Gewerbe","tagline":"Fremde Fahrzeuge in Obhut","icon":"ti-car","category":"Kfz & Flotte","products":[{"id":"p_196","name":"Obhutsschäden","why":"Die Standard-Haftpflicht schließt Schäden an Sachen in Obhut aus — und das ist in diesem Gewerbe das ganze Geschäftsmodell, jedes Auto auf dem Hof.","pivot":"Wessen Versicherung zahlt für das Kundenauto auf Ihrem Hof über Nacht — oder auf der Probefahrt?","listen":"vollen Höfen, roten Kennzeichen"},{"id":"p_197","name":"Umwelt","why":"Öle, Kraftstoffe und Batterien erzeugen beim Entweichen öffentlich-rechtliche Sanierungsanordnungen — fällig ohne Verschulden und aus Basis-Bedingungswerken ausgeschlossen.","pivot":"Wie werden Öle, Kraftstoffe und Batterien gelagert und entsorgt?","listen":"E-Fahrzeug-Arbeiten, Tankthemen"},{"id":"p_198","name":"Inhalt / Maschinen","why":"Diagnostik und Bühnen sind die Ertragskraft, sie sind Diebstahlsmagneten, und Maschinen versagen von innen auf Arten, die Feuerpolicen nie decken.","pivot":"Was würde es kosten, die Werkstatt von null neu auszurüsten?","listen":"neuer Diagnosetechnik, Kalibrierständen"},{"id":"p_199","name":"Rechtsschutz","why":"Bestrittene Rechnungen sind das Dauerwetter des Gewerbes, und das Gutachten, das sie gewinnt, kostet mehr als die meisten Rechnungen.","pivot":"Wie oft werden Reparaturrechnungen angefochten?","listen":"Gewährleistungsstreit"}]},{"id":"ver_205","deck":"vertical","title":"Bildung & Training","tagline":"Aufsichtspflicht, oft über Minderjährige","icon":"ti-school","category":"Haftpflicht","products":[{"id":"p_201","name":"Aufsichtshaftung","why":"Träger stehen in der Aufsichtspflicht der Eltern, und jeder Vorfall mit Minderjährigen kommt mit Aufsichts-Vorwurf — die Verteidigung ist hier das Produkt.","pivot":"Wer haftet, wenn ein Kind im Unterricht oder auf einem Ausflug verletzt wird?","listen":"Gruppengrößen, Aktivitäten außer Haus"},{"id":"p_202","name":"Cyber","why":"Kinderdaten plus Zahlungsdaten der Eltern ist die Kombination mit null öffentlicher Toleranz für schlampigen Umgang.","pivot":"Wo laufen Teilnehmerdaten und Kursplattformen?","listen":"Online-Angeboten, Ratenzahlung"},{"id":"p_203","name":"Vermögensschaden-Haftpflicht","why":"Falsche Anmeldeberatung oder ein verpatzter Qualifikationsweg kostet Teilnehmer Geld und Zeit — reiner Vermögensschaden, den die Haftpflicht ausschließt.","pivot":"Zertifizieren Sie Abschlüsse oder bereiten auf Prüfungen vor?","listen":"zugesagten Qualifikationen"},{"id":"p_204","name":"Gruppen-Unfall","why":"Die gesetzliche Schüler-Unfallversicherung gilt für Schulkontexte, nicht für private Kurse — Teilnehmer-Unfallschutz ist echte Lücke und sichtbares Qualitätsmerkmal zugleich.","pivot":"Welchen Unfallschutz haben Teilnehmer bei Ihnen — und fragen Eltern danach?","listen":"Fragen im Anmeldeformular"}]},{"id":"ver_210","deck":"vertical","title":"Veranstaltungen & Events","tagline":"Werte, die reisen, Menschen, die sich versammeln","icon":"ti-confetti","category":"Inhalt & Ertrag","products":[{"id":"p_206","name":"Technik unterwegs","why":"Event-Equipment verdient auf der Straße und in Hallen — genau dort, wo die stationäre Inhaltspolice längst nicht mehr gilt — und der Diebstahl passiert in der Nacht vor der Show.","pivot":"Wo schläft das Equipment in der Nacht vor der Show?","listen":"beladenen Transportern am Autobahnhotel"},{"id":"p_207","name":"Veranstalterhaftung","why":"Publikums- und Aufbaurisiko steckt nicht automatisch in einer Betriebshaftpflicht, und Tarife deckeln die akzeptierten Eventgrößen — Wachstum in größere Formate überholt die Deckung leise.","pivot":"Was war Ihre größte Veranstaltung — und auf welche bewerben Sie sich gerade?","listen":"Wachstum in größere Formate"},{"id":"p_208","name":"Montage","why":"Auf- und Abbau ist die Phase, in der Konstruktionen fallen und Venues beschädigt werden — in einer bewussten Grenzzone zwischen Montageversicherung und Haftpflicht.","pivot":"Bauen Sie Bühnen oder Stände selbst?","listen":"Rigging, Messeprojekten"},{"id":"p_209","name":"Cyber","why":"Ein eigener Ticketshop heißt: tausende Kartentransaktionen fremder Leute halten — ein Hack ist ein Massen-Melde-Ereignis mit Erstattungen obendrauf.","pivot":"Läuft das Ticketing über Sie, mit Teilnehmerdaten?","listen":"eigenen Shopsystemen"}]},{"id":"ver_215","deck":"vertical","title":"Leichte Produktion & Großhandel","tagline":"Eine Maschine, ein Rückruf, ein Engpass","icon":"ti-building-factory-2","category":"Inhalt & Ertrag","products":[{"id":"p_211","name":"Produkthaftung / Rückruf","why":"Sobald ein Produkt den Namen der Firma trägt, wandern Folgeschäden die Kette hinauf zurück — und die Rückruflogistik trifft auch den fehlerfreien Zulieferer, zu Kosten, die Basis-Bedingungswerke nicht tragen.","pivot":"Was passiert, wenn eine Charge aus dem Markt zurückmuss?","listen":"Eigenmarken-Produktion, Zulieferung an größere Marken"},{"id":"p_212","name":"Maschinen + BU","why":"Maschinen versagen von innen — ohne Feuer, ohne Einbruch, ohne Sach-Auslöser — und der Stillstand hinter der Engpassmaschine kostet meist ein Mehrfaches der Reparatur.","pivot":"Der Ausfall welcher einen Maschine stoppt alles?","listen":"„da läuft alles drüber.\""},{"id":"p_213","name":"Transport","why":"Im Großhandel ist das zweite Lager permanent auf Straße oder Wasser — dort, wo die Lager-Inhaltspolice nie gegolten hat.","pivot":"Wer trägt das Risiko auf ein- und ausgehender Ware?","listen":"Incoterms, eigener Auslieferflotte"},{"id":"p_214","name":"Cyber","why":"Ransomware im ERP ist ein voller Produktionsstillstand ohne Sach-Auslöser — die moderne Unterbrechung, die Sachpolicen strukturell nicht sehen können.","pivot":"Läuft die Produktionsplanung digital — und was passiert, wenn sie verschlüsselt ist?","listen":"ERP- und Lagerverwaltungssystemen"}]},{"id":"ver_220","deck":"vertical","title":"Landwirtschaft & Direktvermarktung","tagline":"Hof, Zuhause und Firma auf einem Gelände","icon":"ti-tractor","category":"Haftpflicht","products":[{"id":"p_216","name":"Landwirtschaftliche Haftpflicht","why":"Die Tierhalterhaftung ist verschuldensunabhängig — der Halter zahlt für das, was das Tier tut — und ein Hof erzeugt Haftung durch bloßes Existieren: Straßen, Besucher, Emissionen.","pivot":"Tiere, Maschinen auf öffentlichen Wegen, Besucher auf dem Hof — wo zieht Ihre Police die Grenze?","listen":"neuen Standbeinen (Hofevents, Pensionstiere)"},{"id":"p_217","name":"Inhalts- und Maschinenwerte","why":"Das Vermögen eines Hofs liegt in Scheunen und Maschinen, deren Werte mit dem Erntekalender schwanken — im Frühjahr gesetzte Summen treffen auf Herbstbrände.","pivot":"Wann wurden Ernte, Vorräte und Maschinenpark zuletzt neu bewertet?","listen":"neuer Erntetechnik, vollen Lagern"},{"id":"p_218","name":"Photovoltaik / Energie","why":"Dach- und Freiflächenanlagen sind ein zweiter Geschäftszweig mit eigenem Hardware- und Ertragsrisiko — der unklar zwischen Hof- und Gebäudepolice sitzt, wenn er nicht bewusst platziert wird.","pivot":"Verdient das Dach oder die Fläche schon mit?","listen":"Einspeisung, Biogas-Plänen"},{"id":"p_219","name":"Direktvermarktung","why":"Der Hofladen macht den Landwirt zum Lebensmittelunternehmer — mit Produkthaftung und der Schließungsmacht des Gesundheitsamts, die die Basis-Hofpolice nie vorgesehen hat.","pivot":"Macht der Hofladen Sie zum Lebensmittelunternehmer?","listen":"Verarbeitung, Märkten, Online-Verkauf"}]}],"objections":[{"id":"obj_221","deck":"objection","title":"Das macht alles mein Vertreter / mein Makler — da bin ich seit 20 Jahren","icon":"ti-heart-handshake","category":"Bestand","root":"Loyalität und Bequemlichkeit, nicht geprüfte Deckungsqualität. Zwanzig Jahre Beziehung heißen oft: zwanzig Jahre alte Versicherungssummen.","reframe":"„Das spricht für Sie — gute Betreuung soll man behalten, und ich will hier niemanden verdrängen. Die einzige Frage ist: Wann wurde zuletzt geprüft, ob die Verträge noch zum heutigen Betrieb passen? Unternehmen verändern sich schneller als Policen.\" Den Bestandsbetreuer nie angreifen — das verliert. Die sachliche Zweitmeinung mit dokumentiertem Ergebnis anbieten und die eigene Rolle und das eigene Mandat transparent machen; diese Offenheit zahlt direkt auf Vertrauen ein.","bridge":"„Wann hat zuletzt jemand Ihre Versicherungssummen gegen den heutigen Warenwert und die heutige Lohnsumme gehalten? Genau das biete ich Ihnen an — unverbindlich, schriftlich, und wenn alles passt, sage ich Ihnen genau das.\""},{"id":"obj_222","deck":"objection","title":"Ich bin doch über die Berufsgenossenschaft schon versichert","icon":"ti-shield-check","category":"Wissen","root":"Die verbreitetste Deckungsillusion im Markt — eine gesetzliche Arbeitgeberpflicht wird für Rundumschutz gehalten. Kein Widerstand, sondern eine Wissenslücke.","reframe":"„Richtig, und die brauchen Sie auch. Die Berufsgenossenschaft deckt die Arbeitsunfälle Ihrer Mitarbeiter. Sie deckt weder Ihre Haftung gegenüber Kunden, noch Ihre Einrichtung, noch Sie selbst als Inhaber — das sind drei völlig getrennte Baustellen.\" Nie etwas anbieten, was der Kunde per Gesetz hält. Wer diese Grenze sauber zieht — hier wie bei der Kfz-Haftpflicht — baut sofort Kompetenzvertrauen auf und unterscheidet sich von jedem Verkäufer, den der Kunde bisher erlebt hat.","bridge":"„Legen wir sauber auseinander, was Sie per Gesetz schon haben und wo wirklich noch nichts steht — dann reden wir nur über die echten Lücken.\""},{"id":"obj_223","deck":"objection","title":"Schicken Sie mir erst mal etwas Schriftliches","icon":"ti-mail","category":"Verzögerung","root":"Teils echter Prüfwunsch, teils höfliches Abwimmeln. Der Unterschied zeigt sich daran, ob ein Termin daran hängt.","reframe":"„Sehr gerne — das gehört bei mir ohnehin dazu; Sie bekommen die Analyse schriftlich und nachvollziehbar. Damit das Papier für Sie einen Wert hat: Welche zwei, drei Punkte sollen unbedingt drinstehen?\" Gegen die Schriftform nicht anreden — liefern, strukturieren und im selben Atemzug den Folgetermin fixieren. Das Dokument plus der gehaltene Termin *ist* das Verkaufsargument.","bridge":"„Ich schicke es Ihnen bis Donnerstag. Passt Anfang nächster Woche — fünfzehn Minuten, um die zwei markierten Punkte durchzugehen?\""},{"id":"obj_224","deck":"objection","title":"Mein Vertrag läuft noch bis …","icon":"ti-calendar-due","category":"Verzögerung","root":"Meistens schlicht die Wahrheit. Jahresverträge mit dreimonatiger Kündigungsfrist sind der Normalfall.","reframe":"„Völlig in Ordnung — genau deshalb ist jetzt der richtige Zeitpunkt: Wir prüfen in Ruhe, ohne Druck, und wenn es besser passt, merken wir den Stichtag vor. Und manches hat gar keinen Vorvertrag: Eine Cyberdeckung oder eine Gruppen-Unfall können Sie heute regeln, unabhängig davon.\" Die Antwort ist ein System, keine Rhetorik: Stichtagsliste, Wiedervorlagedisziplin, Unterstützung bei der Kündigung — und konsequent die vorvertragsfreien Lücken (Cyber, Rechtsschutz, Benefits) vor dem Stichtag verkaufen.","bridge":"„Wann ist Ihre Hauptfälligkeit? Ich lege unseren Prüftermin drei Monate davor — und bis dahin schließen wir die Lücken, die heute schon offen sind.\""},{"id":"obj_225","deck":"objection","title":"Ich muss darüber nachdenken","icon":"ti-clock","category":"Verzögerung","root":"Meist ein unausgesprochener Vorbehalt, kein echter Zeitbedarf — manchmal aber auch ernsthaftes Abwägen. Beides lässt sich unterscheiden: Echtes Abwägen akzeptiert einen konkreten Folgetermin; das Abwimmeln weicht ihm aus.","reframe":"„Selbstverständlich — es ist Ihr Betrieb, und das darf überlegt sein. Nach meiner Erfahrung ist beim Nachdenken meist ein bestimmter Punkt noch nicht rund. Welcher ist es bei Ihnen — die Deckung, die Kosten oder der Zeitpunkt?\" Echtes Abwägen respektieren, statt es aufbrechen zu wollen. Die Gewinnkombination ist dieselbe wie bei der Schriftform: strukturierte Zusammenfassung plus fester Termin. Ein vereinbartes zweites Gespräch konvertiert besser als ein erzwungenes erstes.","bridge":"„Welche Information würde Ihnen die Entscheidung leicht machen? Genau die bringe ich zum Folgetermin mit — passt Dienstag?\""},{"id":"obj_226","deck":"objection","title":"Zu teuer.\" / „Woanders habe ich es günstiger gesehen","icon":"ti-currency-euro","category":"Preis","root":"Die Prämie wird isoliert betrachtet — nicht gegen das Risiko und fast nie gegen die Qualität der Bedingungen. Portalpreise vergleichen selten gleiche Deckung.","reframe":"„Verstehe ich — teurer als was genau? Als ein anderes Angebot oder als das, was Sie eingeplant hatten? Und beim anderen Angebot: gleicher Unterversicherungsverzicht, gleiche Mitversicherung der Tätigkeitsschäden? Genau dort liegen die Unterschiede — die, die man erst im Schadenfall sieht.\" Nie mit einem Nachlass antworten — das beschädigt die Beraterposition. Das Bedingungsargument gewinnt: Neuwert, Vorsorge, Unterversicherungsverzicht und — wo der Tarif sie enthält — eine Innovationsgarantie, die den Vertrag nicht altern lässt. Das Merkmal benennen, das Detail im aktuellen Bedingungswerk bestätigen.","bridge":"„Was würde Sie ein einziger unversicherter Schaden aus Ihrem eigenen Gewerk kosten — der Wasserschaden nach der Abnahme, der Generalschlüssel? Gegen diese Zahl tritt die Prämie an, nicht gegen den Portalpreis.\""},{"id":"obj_227","deck":"objection","title":"Da muss ich erst meinen Steuerberater fragen","icon":"ti-calculator","category":"Vertrauen","root":"Der Steuerberater ist der vertrauteste externe Berater im Mittelstand. Keine Ausrede — die reale Entscheidungsstruktur, und eine Chance.","reframe":"„Gute Idee, der kennt Ihre Zahlen. Damit er das schnell bewerten kann, fasse ich Ihnen die Empfehlung mit Begründung auf einer Seite zusammen — Absetzbarkeit, Lohnsummenbezug, alles drauf. Bei bAV und bKV wird er ohnehin mitreden wollen.\" Den Steuerberater nie umgehen — ausrüsten und einbinden. Bei bAV und bKV ist er faktisch Mitentscheider, und ein überzeugter Steuerberater empfiehlt weiter. Steuerliche Aussagen sauber ihm überlassen: keine Steuerberatung durch den Vermittler.","bridge":"„Legen wir den Folgetermin so, dass Sie bis dahin sein Okay haben — oder holen wir ihn bei den Benefits-Themen direkt mit dazu?\""},{"id":"obj_228","deck":"objection","title":"Deckt meine Betriebshaftpflicht das nicht alles schon ab?","icon":"ti-stack-2","category":"Wissen","root":"Die Haftpflicht wird für Rundumschutz gehalten. Die üblichen Verwechslungen: eigene Ware und Einrichtung (braucht Inhaltsversicherung), eigener Stillstand (Betriebsunterbrechung), reine Vermögensschäden (Vermögensschaden-Haftpflicht), Cyber und die Kosten eigener Rechtsstreitigkeiten (Rechtsschutz).","reframe":"„Die Betriebshaftpflicht zahlt, wenn Sie *anderen* Schaden zufügen. Alles, was *Ihnen selbst* passiert — Ihre Ware, Ihr Stillstand, Ihre Daten, Ihre eigenen Rechtsstreitigkeiten — ist eine andere Police. Sie ist das Fundament, nicht das Dach.\" Die Zwei-Körbe-Erklärung (Haftung nach außen gegen eigene Schäden nach innen) ist die sauberste Darstellung überhaupt und funktioniert quer durch alle Branchen in Teil 1. Auf Papier aufzeichnen — die Skizze überlebt den Termin.","bridge":"„Sortieren wir Ihre Risiken in zwei Körbe — Schäden, die Sie verursachen, und Schäden, die Sie erleiden? Dann sehen Sie auf einen Blick, was die Haftpflicht trägt und was derzeit gar nichts trägt.\""},{"id":"obj_229","deck":"objection","title":"Bei uns ist in 30 Jahren nichts passiert","icon":"ti-history","category":"Wissen","root":"Gelebte Erfahrung schlägt Statistik — verständlich und in sich schlüssig.","reframe":"„Und das spricht für Ihren Betrieb. Nur: Versichert wird nicht die Vergangenheit, sondern das eine Jahr, das anders läuft. Der Kollege mit dem Wasserschaden hatte vorher auch 25 gute Jahre.\" Angstszenarien und Dramatik stoßen ab. Was wirkt, sind nüchterne Schadenbeispiele aus derselben Branche — am besten aus der Region — und die sichtbare Bereitschaft, Unnötiges wegzulassen.","bridge":"„Welcher Schaden würde Ihren Betrieb wirklich treffen — nicht der Kratzer, sondern der, von dem Sie sich sechs Monate erholen müssten? Über den reden wir; den Rest lassen wir weg.\""},{"id":"obj_230","deck":"objection","title":"Ich will nicht überversichert sein — ihr wollt doch immer nur verkaufen","icon":"ti-scale","category":"Vertrauen","root":"Das Erbe des provisionsgetriebenen Strukturvertriebs. Der Kunde schützt sich vor dem Verkäufer, nicht vor der Versicherung.","reframe":"„Den Einwand verstehe ich, und er ist berechtigt — genau deshalb dokumentiere ich jede Empfehlung mit Begründung im Beratungsprotokoll, und genauso dokumentiere ich, was Sie *nicht* brauchen. Wenn ich Ihnen heute zwei Dinge nenne, die Sie sich sparen können — nehmen Sie mir dann die eine Lücke ab, die ich ernst meine?\" Die gesetzliche Beratungs- und Dokumentationspflicht ist das stärkste Werkzeug gegen Misstrauen. Erst abwählen, dann empfehlen — die Reihenfolge ist die Botschaft.","bridge":"„Fangen wir mit dem an, was wegkann oder doppelt ist — danach reden wir über das, was fehlt.\""},{"id":"obj_231","deck":"objection","title":"Versicherungen zahlen im Ernstfall sowieso nicht","icon":"ti-shield-x","category":"Vertrauen","root":"Eine erlebte oder weitererzählte Schadenenttäuschung — fast immer verursacht durch Unterversicherung, verletzte Obliegenheiten oder eine nie geprüfte Police.","reframe":"„Diese Geschichten gibt es, und fast immer steckt dasselbe dahinter: Die Summe war zu niedrig, oder eine Obliegenheit war verletzt — und beides wusste vorher niemand. Genau deshalb prüfen wir das *vor* dem Schaden. Der Unterversicherungsverzicht und die Pflichten, die Sie einhalten müssen, stehen bei mir im Protokoll, nicht im Kleingedruckten.\" Unterversicherung mit Quotelung ist der häufigste reale Kürzungsgrund — deshalb ist der Unterversicherungs-Check die direkte Antwort auf diesen Einwand. Obliegenheiten und die Anzeigepflicht nach § 19 VVG offensiv erklären; Transparenz über die Spielregeln ist hier das Verkaufsargument.","bridge":"„Darf ich Ihnen an Ihrer aktuellen Police die zwei, drei Stellen zeigen, an denen es im Schadenfall typischerweise klemmt?\""},{"id":"obj_232","deck":"objection","title":"Das Geld ist gerade knapp","icon":"ti-receipt","category":"Preis","root":"Oft eine reale Liquiditätslage, kein Verhandlungsmanöver. Als Priorisierungssignal behandeln.","reframe":"„Dann sollten wir doppelt aufpassen, dass nicht ein einziger Schaden genau diese knappe Liquidität trifft. Machen wir Triage: Welches Risiko würde den Betrieb brechen, welches nur ärgern? Die erste Kategorie decken wir, den Rest parken wir bewusst — dokumentiert.\" Keine Nachlässe. Zahlweise-Optionen im aktuellen Tarif prüfen, statt sie zu versprechen. Das bewusste Zurückstellen im Beratungsprotokoll festhalten: Das dokumentierte „geprüft und zurückgestellt\" schützt den Kunden, schützt den Berater nach § 61 VVG — und schafft den legitimen Wiedereinstieg.","bridge":"„Wenn wir heute nur die eine existenzielle Lücke schließen und den Rest auf die Stichtagsprüfung legen — welche Lücke wäre das für Sie?\""},{"id":"obj_233","deck":"objection","title":"Dafür ist mein Betrieb zu klein","icon":"ti-building-store","category":"Cross-Selling","root":"Deckungen wie Cyber, Rechtsschutz oder Betriebsunterbrechung gelten als Konzernthemen.","reframe":"„Genau umgekehrt: Der Konzern zahlt den Schaden aus der Portokasse — bei Ihnen hängt am selben Schaden der ganze Betrieb. Genau dafür gibt es die kompakten Gewerbetarife: zugeschnitten auf Ihre Größe.\" Auf die kompakten Gewerbetarife als sichtbaren Beleg verweisen, dass die Deckung für diese Betriebsgröße gebaut wurde — und die Empfehlung auf die ein, zwei Deckungen begrenzen, hinter denen ein existenzieller Schaden steht. Kein Katalog.","bridge":"„Wie viele Wochen Stillstand verkraftet Ihr Konto, bevor es ernst wird? Das ist die einzige Zahl, die über ‚zu klein' entscheidet.\""},{"id":"obj_234","deck":"objection","title":"Cyber betrifft uns nicht — wir sind doch kein IT-Unternehmen","icon":"ti-lock","category":"Cross-Selling","root":"Cyber wird als Technikthema gelesen, nicht als Thema von Betriebsunterbrechung und Zahlungsbetrug.","reframe":"„Angreifer suchen keine IT-Firmen — sie suchen offene Türen. Und die Rechnung mit der geänderten Bankverbindung trifft den Handwerksbetrieb genauso wie die Kanzlei. Die Frage ist nicht, ob Sie IT verkaufen, sondern ob Ihr Betrieb eine Woche ohne E-Mail, Kasse und Buchhaltung läuft.\" Der wirksame Einstieg läuft über Betriebsunterbrechung und Überweisungsbetrug, nicht über Datenschutztheorie; die Meldepflichten der DSGVO sind das sachliche Zusatzargument, nicht der Aufhänger.","bridge":"„Was passiert bei Ihnen konkret, wenn morgen früh kein Rechner mehr aufgeht und die letzte Ausgangsrechnung auf ein falsches Konto bezahlt wurde?\""},{"id":"obj_235","deck":"objection","title":"Den Rest mache ich später dazu","icon":"ti-arrows-shuffle","category":"Cross-Selling","root":"Zustimmung im Grundsatz, Aufschub in der Praxis — und „später\" kommt ohne Auslöser nie. Der Rhythmus der Kündigungsfristen lässt „später\" besonders legitim wirken.","reframe":"„In Ordnung — aber zwischen jetzt und später ist die Lücke real. Machen wir zwei Dinge: Wir sortieren, was wirklich warten kann und was nicht, und wir schreiben ‚später' in den Kalender. Ein offenes ‚später' ist ein freundliches Nein, und das braucht keiner von uns beiden.\" „Später\" am konkreten Stichtag verankern und die Zurückstellung ins Beratungsprotokoll aufnehmen. Eine datierte, dokumentierte Zusage wird gehalten — ein mündliches „wir kommen darauf zurück\" nie.","bridge":"„Welches Datum tragen wir für die zweite Tranche ein — und ist etwas auf der Liste, das Ihnen bis dahin den Schlaf rauben würde?\""},{"id":"obj_236","deck":"objection","title":"Jetzt passt es nicht — kommen Sie nach der Saison wieder","icon":"ti-snowflake","category":"Verzögerung","root":"Bei Saisonbetrieben (Gastronomie, GaLaBau, Events, Handel) oft schlicht wahr — und zugleich riskant, denn die Hochsaison ist die höchste Exponierung.","reframe":"„Gerade weil das Ihre stärkste Zeit ist, ist es auch Ihr größtes Risiko — volles Lager, volle Auftragsbücher, volle Fläche. Ich brauche heute keine Entscheidung über alles: nur die eine Lücke, die in der Saison wehtut, und einen festen Termin danach für den Rest.\" Über den fest vereinbarten, dokumentierten Folgetermin lösen, statt den Abschluss im Erstkontakt zu erzwingen. Ein datiertes „Nein, aber im November\" wird in aller Regel gehalten — als Pipeline behandeln, nicht als Niederlage.","bridge":"„Welche Woche nach Saisonende trage ich verbindlich ein — und darf ich bis dahin wenigstens die Versicherungssumme fürs volle Lager anpassen lassen?\""}],"resources":[],"sections":[{"id":"cob","label":"Branchen & Deckungen","icon":"ti-shield-half","eyebrow":"Branche · Deckungsanalyse","headline":"Die Deckung kennen, bevor der Kunde das Risiko kennt.","blurb":"Sechzehn Branchengruppen, die Deckungen, auf die es jeweils ankommt, und das Signal im Kundengespräch, das zeigt, wann man sie anspricht. Eine Branche öffnen, um zu sehen, was Pflicht ist, was empfohlen wird und was situativ passt.","notice":{"on":false,"tone":"info","title":"","body":""}},{"id":"vertical","label":"Bedarf erkennen","icon":"ti-building-store","eyebrow":"BEDARF ERKENNEN","headline":"Die Lücke erkennen, bevor der Kunde den Betrieb beschreibt.","blurb":"Dieselben sechzehn Branchen, die Gesprächssignale je Branche und die Cross-Selling-Ansätze, die sich lohnen. Karte umdrehen für die Einstiegsfragen und worauf man hört.","notice":{"on":false,"tone":"info","title":"","body":""}},{"id":"objection","label":"Einwandbehandlung","icon":"ti-messages","eyebrow":"Einwandbehandlung","headline":"Aus dem Einwand den nächsten Schritt machen.","blurb":"Die Einwände, die tatsächlich kommen, was wirklich dahintersteckt und die Brückenfrage, die das Gespräch weiterführt. Karte umdrehen für den passenden Zug.","notice":{"on":false,"tone":"info","title":"","body":""}},{"id":"resources","label":"Ressourcen","icon":"ti-folder","eyebrow":"Ressourcen","headline":"Alles für die Zeit zwischen den Terminen.","blurb":"Leitfäden, Übersichten und Ansprechpartner hinter jedem Gespräch in diesem Playbook.","notice":{"on":false,"tone":"info","title":"","body":""}}],"resSections":[],"settings":{"toolName":"Producer Hub","toolTagline":"Vertriebsunterstützung Gewerbe","banner":{"on":false,"tone":"info","text":""},"tiers":{"must":{"label":"Pflicht & Fundament","sub":"Abschließen, bevor die Türen aufgehen"},"rec":{"label":"Empfohlen","sub":"Bei jedem passenden Kunden ansprechen"},"opt":{"label":"Situativ","sub":"Das Signal kennen und ansprechen, sobald es auftaucht"}}},"_contentVer":999},"cats":{"vertical":["Haftpflicht","Vermögensschaden","Inhalt & Ertrag","Kfz & Flotte"],"objection":["Bestand","Preis","Verzögerung","Vertrauen","Cross-Selling","Wissen"]},"tint":{"Haftpflicht":{"bg":"var(--en-rose-50)","dot":"var(--en-burgundy)"},"Vermögensschaden":{"bg":"var(--en-violet-light)","dot":"#b31767"},"Inhalt & Ertrag":{"bg":"var(--en-yellow-light)","dot":"var(--en-amber)"},"Kfz & Flotte":{"bg":"var(--en-iceblue-light)","dot":"#0f94a7"},"Bestand":{"bg":"var(--en-rose-50)","dot":"var(--en-burgundy)"},"Preis":{"bg":"var(--en-yellow-light)","dot":"var(--en-amber)"},"Verzögerung":{"bg":"var(--en-iceblue-light)","dot":"#0f94a7"},"Vertrauen":{"bg":"var(--en-violet-light)","dot":"#b31767"},"Cross-Selling":{"bg":"var(--en-leaf-light)","dot":"#009284"},"Wissen":{"bg":"var(--en-warmgrey-light)","dot":"#545241"}},"ui":{"spot":"Bedarf erkennen: ","when":"Wann: ","claimLabel":"Schadenbeispiel","listen":"Hinhören bei","reveal":"Umdrehen","tap":"Zum Umgang antippen","flip":"zurückdrehen","back":"Alle Branchen","noMatch":"Nichts passt zu diesem Filter.","searchInd":"Branchen durchsuchen…","searchObj":"Einwände durchsuchen…","covWord":"Deckungen","typesWord":"Betriebsarten","gaps":"Cross-Selling-Ansätze","rootLabel":"Was wirklich dahintersteckt","reframeLabel":"Anerkennen & umdeuten","bridgeLabel":"Die Brücke","all":"Alle","langBtn":"Translate to English","loading":"Playbook wird geladen…"}},"en":{"data":{"cob":[{"id":"bau","icon":"ti-tools","accent":"#e87a16","bg":"var(--en-orange-light)","title":"Construction & Finishing Trades (Bau- und Ausbauhandwerk)","types":["Electrical","plumbing/heating/climate (SHK)","carpentry & joinery","tile & screed","painting & drywall","roofing & scaffolding"],"policies":{"must":[{"id":"cov_237","name":"Betriebshaftpflicht with a construction wording","desc":"pays when the firm's work injures someone or damages someone else's property. For the trades, the decisive parts are the clauses most basic policies restrict: damage to the very thing being worked on (Bearbeitungs-/Tätigkeitsschäden) and damage that only shows up after acceptance — because that is exactly where trade claims happen.","signal":"every firm working on other people's property has this exposure from job one; ask what happens on callbacks.","when":"","cross":"","claim":"A plumber's solder joint fails six weeks after handover and floods the client's finished basement — around €35,000 in drying, flooring, and repainting. Without the working-damage and completed-work clauses, the policy could refuse exactly this. Verify the clause scope in the current conditions."},{"id":"cov_238","name":"Motor/fleet cover (Kfz-/Flottenversicherung)","desc":"motor liability is legally required for every vehicle; the comprehensive layer protects the firm's own vans and what a crash does to the business.","signal":"several vehicles means a fleet solution is worth checking; ask who drives and what rides along.","when":"","cross":"","claim":"An apprentice rear-ends a car at a junction with the fully loaded transporter — €60,000 injury claim to the other driver plus a written-off van full of tools. The liability part is legally covered; whether the van and its schedule gap are covered depends on what was bound."},{"id":"cov_239","name":"Contents + fixed-cost cover (Geschäftsinhalt + Betriebskosten/Betriebsunterbrechung)","desc":"the contents policy replaces workshop, warehouse, and machinery at today's replacement value; the fixed-cost cover pays the rent, wages, and leasing that keep running while the business can't work.","signal":"any firm with a workshop or stored material; ask when the sum insured last saw an invoice.","when":"","cross":"","claim":"A weekend burglary empties the workshop of €45,000 in machines and stock; the firm loses three weeks of jobs while replacing them, and €12,000 of fixed costs run on regardless. Two policies, one event."}],"rec":[{"id":"cov_240","name":"Bauleistungsversicherung (builders risk)","desc":"covers the unfinished structure and materials already delivered but not yet built in. Neither the client's home policy nor the trade's own contents policy responds on a construction site.","signal":"new builds, shell construction, major renovations.","when":"","cross":"","claim":"A storm tears the freshly erected roof truss off a shell build overnight — €55,000 in destroyed timber and re-erection. The building doesn't exist yet as far as any finished-building policy is concerned; only builders risk pays."},{"id":"cov_241","name":"Montageversicherung (erection/installation)","desc":"protects technical installations (heating systems, PV, electrical plant) during the installation phase, when they are delivered, part-assembled, and most vulnerable.","signal":"firms installing high-value systems rather than only building structures.","when":"","cross":"","claim":"A delivered €18,000 heat pump is damaged by a dropped beam the day before commissioning. Not yet handed over, not yet the client's — the installation cover pays."},{"id":"cov_242","name":"Kautionsversicherung (surety)","desc":"not a claims policy but a guarantee product: the insurer issues warranty and performance bonds so clients don't withhold cash retentions and the bank credit line stays free.","signal":"clients withholding 5% retentions, public tenders, bond requirements in contracts.","when":"","cross":"","claim":"A firm has 5% retention withheld across eight running jobs — €40,000 of its own money locked up for years. Bonds release that cash back into the business the month they're issued."},{"id":"cov_243","name":"Tools in transit","desc":"an off-premises extension or transport cover for the tools and gear that live in the vans and on sites, where the building-based contents policy no longer reaches.","signal":"\"my whole setup lives in the van,\" trailers loaded overnight.","when":"","cross":"","claim":"A locked site trailer is broken open overnight and €22,000 of power tools disappear. The workshop contents policy denies it — the gear had left the premises. Verify overnight and vehicle clauses in the conditions."}],"opt":[{"id":"cov_244","name":"Vermögensschaden-Haftpflicht (professional indemnity)","desc":"covers pure financial loss from wrong planning and advice. The Betriebshaftpflicht covers the physical work; this covers the design judgment behind it.","signal":"the firm designs as well as builds — ask \"do you plan, or only build to someone else's drawings?\"","when":"","cross":"","claim":"A design-and-build carpenter under-specifies a beam; the floor sags, and the owner sues over the planning error, not the workmanship — a €50,000 claim the liability policy would exclude as a planning fault."},{"id":"cov_245","name":"Firmen-Rechtsschutz (legal expenses)","desc":"pays lawyers and court costs when the firm has to fight: unpaid invoices, warranty accusations, employment disputes.","signal":"any firm that has ever \"written off\" an unpaid bill because suing felt too expensive.","when":"","cross":"","claim":"A client refuses the final €28,000 invoice claiming defects; two years of expert reports and court run to €14,000 in legal costs before the firm wins. Rechtsschutz carried those costs — without it, many firms simply give up the claim."},{"id":"cov_246","name":"Gruppen-Unfall, bKV, bAV (employee benefits)","desc":"group accident cover pays where the statutory accident insurance doesn't: leisure time, lump sums for disability, the owner personally. bKV (company health) and bAV (company pension) are retention tools in a trade starved of skilled workers.","signal":"\"we can't find people,\" or an owner with no personal accident cover at all.","when":"","cross":"","claim":"A roofer shatters his ankle playing Sunday football — three months out, zero from the Berufsgenossenschaft because it wasn't a workplace accident. The group accident policy pays a lump sum and daily benefit, and the firm keeps a loyal employee instead of losing him to money stress."},{"id":"cov_247","name":"Cyberversicherung","desc":"pays for IT-incident response, data restoration, business interruption, and the fallout of payment fraud. Trade firms think they have nothing to hack; attackers know they have weak email security and big invoices.","signal":"digital quoting and invoicing, online banking.","when":"","cross":"","claim":"The firm's email account is quietly hijacked; the fraudster sends the builder's real €19,000 final invoice with a swapped IBAN. The client pays the criminal, refuses to pay twice, and the relationship and the money are both gone. Cyber cover funds the forensics and, depending on the wording, the fraud loss — verify the payment-fraud module."}]}},{"id":"reinigung","icon":"ti-spray","accent":"#0f94a7","bg":"var(--en-iceblue-light)","title":"Cleaning & Facility Services","types":["Contract cleaning","office & practice cleaning","glass & facade cleaning","specialty cleaning","caretaker/janitorial services","post-construction cleaning"],"policies":{"must":[{"id":"cov_248","name":"Betriebshaftpflicht","desc":"pays when the cleaning work injures someone or damages client property. For cleaners the whole risk lives inside other people's buildings, so the two clauses that matter are damage to the property being worked on (the desk you polish, the floor you strip) and key loss (Schlüsselverlust) — both restricted or capped in basic policies.","signal":"master keys, alarm codes, after-hours access.","when":"","cross":"","claim":"A crew member loses the master key to an office complex; the landlord orders the entire locking system replaced — €25,000. A second classic: a visitor slips on a freshly mopped, unsigned lobby floor and fractures a hip — €60,000 in injury claims. Verify key-loss sublimits in the conditions."},{"id":"cov_249","name":"Motor/fleet cover","desc":"motor liability is legally required per vehicle, and cleaning crews are on the road between objects every day, which makes vehicle claims a frequency risk, not a rarity.","signal":"multiple objects serviced per day, crews in company cars.","when":"","cross":"","claim":"Between the second and third building of the morning, a crew van clips a parked car in a narrow courtyard — €7,000. Small, but the third such claim in a year is a premium conversation; a fleet contract manages that better than five single policies."}],"rec":[{"id":"cov_250","name":"Firmen-Rechtsschutz (legal expenses)","desc":"pays the lawyer and court when the firm is dragged into a dispute. Cleaning is headcount-heavy with high turnover, so employment law is where the fights actually happen.","signal":"many employees, wage-hour questions, dismissal stories.","when":"","cross":"","claim":"A dismissed cleaner files an unfair-dismissal suit; the labour court process costs €8,000 in legal fees even though the firm settles reasonably. In Germany each side pays its own lawyer at the labour court's first instance regardless of who wins — which is exactly why this cover earns its premium here."},{"id":"cov_251","name":"Contents + fixed-cost cover","desc":"replaces the machine park and stored supplies at replacement value and carries the fixed costs if the depot burns or floods. Growing cleaning firms accumulate more machinery than they realize.","signal":"ride-on scrubbers, storage units, a depot.","when":"","cross":"","claim":"A break-in at the depot takes two ride-on scrubbing machines and a stock of chemicals — €18,000. The sum insured hadn't been touched since the firm had half the machines; without a buffer clause, underinsurance would have cut the payout."},{"id":"cov_252","name":"Gruppen-Unfallversicherung (group accident)","desc":"pays lump sums and daily benefits for accidents the statutory cover ignores, above all anything outside work. Facade and glass crews work at height, and their private lives carry the same body.","signal":"work at height, physically demanding crews.","when":"","cross":"","claim":"A facade cleaner breaks a leg on a weekend hike — months off, and the Berufsgenossenschaft owes nothing because it wasn't a work accident. The group accident policy pays, and the employer who arranged it is remembered for it."}],"opt":[{"id":"cov_253","name":"Cyberversicherung","desc":"pays for incident response and liability when the firm's systems leak or lock. A cleaning company's scheduling software holds something uniquely sensitive: access codes and floor plans of client buildings.","signal":"scheduling apps, stored alarm codes, client portals.","when":"","cross":"","claim":"The scheduling tool is breached and client alarm codes are exposed; every affected client must be notified, locks and codes changed, and a forensics firm engaged — €20,000 before any lawsuit, plus a trust problem only fast, funded response can contain."},{"id":"cov_254","name":"bKV (company health insurance)","desc":"a small employer-paid health top-up (dental, physio, screenings) that punches far above its cost in a low-wage, high-turnover sector.","signal":"complaints about churn and no-shows in recruiting.","when":"","cross":"","claim":"A cleaner gets a €900 dental bill largely covered by the employer's bKV — the kind of concrete, personal benefit that keeps someone from leaving for 50 cents more per hour elsewhere."}]}},{"id":"galabau","icon":"ti-plant-2","accent":"#009284","bg":"var(--en-leaf-light)","title":"Landscaping & Grounds (GaLaBau, incl. winter service)","types":["Landscape construction","grounds maintenance","tree care","paving","winter/gritting service","irrigation"],"policies":{"must":[{"id":"cov_255","name":"Betriebshaftpflicht","desc":"pays when the work injures people or damages property, and in this trade two extensions decide everything: contractually assumed traffic-safety and gritting duties (the winter-service liability the property owner hands over), and the environmental modules for pesticide and fuel use.","signal":"winter contracts, spraying programs, work near neighboring property.","when":"","cross":"","claim":"On a January morning, a pedestrian slips on black ice in a customer's parking lot the firm was contracted to grit — a fractured femur and a €45,000 injury claim aimed at the firm, not the owner, because the duty was contractually transferred. Verify winter service is expressly covered."},{"id":"cov_256","name":"Mobile machinery cover (fahrbare Maschinen)","desc":"a machinery policy for the self-propelled fleet: excavators, loaders, ride-on mowers. It covers theft, operating accidents, and damage wherever the machine works — which the building-based contents policy cannot.","signal":"machines parked on open sites or trailers overnight.","when":"","cross":"","claim":"A €38,000 mini excavator vanishes from a fenced but unguarded site over a long weekend. No contents policy responds off-premises; the mobile machinery cover replaces it and the season is saved."},{"id":"cov_257","name":"Fleet cover","desc":"legally required liability per vehicle, plus the practical reality that this trade tows heavy trailers daily, and trailer incidents are its signature motor claim.","signal":"trucks with trailers, machines in tow.","when":"","cross":"","claim":"A trailer loaded with a ride-on mower detaches on a federal road and hits the crash barrier and a following car — a liability claim in the tens of thousands plus the destroyed mower. The liability side is mandatory cover; the mower needs the machinery policy above."}],"rec":[{"id":"cov_258","name":"Bauleistungsversicherung (builders risk)","desc":"covers the unfinished outdoor works: walls, paving, plantings, and delivered materials before handover, which no finished-property policy touches.","signal":"new installations, staged projects, tender work.","when":"","cross":"","claim":"Days before handover, heavy rain undermines a newly built retaining wall and it partially collapses — €30,000 to rebuild. The client hasn't accepted the work; the loss is the contractor's, and builders risk is the policy that carries it."},{"id":"cov_259","name":"Contents + fixed-cost cover","desc":"replacement value for the hall, workshop, and the seasonal gear stored in it, plus the fixed costs that keep running when the base of operations is out of action.","signal":"a yard or hall full of equipment each winter.","when":"","cross":"","claim":"A February hall fire destroys stored mowers, trimmers, and the irrigation stock for spring — €50,000 in equipment plus a scramble to be ready for the season while rent and wages run on."},{"id":"cov_260","name":"Firmen-Rechtsschutz","desc":"funds the legal fight when clients withhold payment claiming defects, the trade's most common dispute.","signal":"stories of unpaid final invoices, \"the plants died\" arguments.","when":"","cross":"","claim":"A client withholds €22,000 claiming plantings failed; the expert report proves the client never watered as instructed. Getting there costs €9,000 in legal and expert fees — costs the legal-expenses policy carried."}],"opt":[{"id":"cov_261","name":"Kautionsversicherung (surety)","desc":"insurer-issued performance and warranty bonds, typically demanded on public tenders and larger commercial projects.","signal":"municipal contracts, bond clauses in tenders.","when":"","cross":"","claim":"A town requires a performance bond on a €200,000 park contract. The surety line issues it in days; without it, the bank would demand cash collateral and the firm couldn't bid."},{"id":"cov_262","name":"Gruppen-Unfall / bKV","desc":"accident lump sums beyond the statutory system and a health top-up for crews doing hard physical work.","signal":"physically worn teams, hiring trouble.","when":"","cross":"","claim":"A landscaper cuts his hand badly with a chainsaw while cutting firewood at home — private, so the Berufsgenossenschaft pays nothing. The group accident policy pays the lump sum that bridges months of reduced capacity."},{"id":"cov_263","name":"Cyberversicherung","desc":"response and fraud cover once quoting, invoicing, and banking run digitally.","signal":"digital offers, email invoices.","when":"","cross":"","claim":"A spoofed supplier email redirects a €15,000 materials payment to a fraudster's account. The money is gone before anyone calls; the cyber policy's fraud module and response team are the difference between a bad week and a bad year — verify the module is included."}]}},{"id":"gastro","icon":"ti-tools-kitchen-2","accent":"var(--en-burgundy)","bg":"var(--en-rose-50)","title":"Food Service & Hospitality","types":["Restaurants","cafés","fast food & franchise units","bars","hotels & guesthouses","catering"],"policies":{"must":[{"id":"cov_264","name":"Betriebshaftpflicht","desc":"pays when guests are injured or made ill: the slip on a wet floor, the burn from a dropped plate, the food that sends a table to hospital, the coat that vanishes from the cloakroom. Alcohol service belongs in the wording as a matter of course.","signal":"every operation with guests on the premises — the question is only whether the wording fits the concept (bar, terrace, catering off-site).","when":"","cross":"","claim":"A guest slips on a spilled drink nobody cleared, breaking a tooth and cheekbone — €25,000 including dental reconstruction. Second classic: a catering job leaves twelve wedding guests with salmonella, and the claims arrive as a group."},{"id":"cov_265","name":"Geschäftsinhaltsversicherung (contents)","desc":"replaces kitchen, refrigeration, and interior at today's replacement value after fire, water, burglary, or storm. Hospitality reinvests constantly, so the buffer (Vorsorge) and waiver of underinsurance are real money, not fine print.","signal":"any recent renovation or new kitchen line the sum insured has never heard of.","when":"","cross":"","claim":"A fryer fire at closing time destroys the kitchen block — €80,000 in equipment. The policy was updated after the refit, so replacement value pays in full; the competitor down the street with a ten-year-old sum insured would have eaten a proportional cut."},{"id":"cov_266","name":"Fixed-cost / business-interruption cover","desc":"pays the rent, payroll, and leasing that continue while the restaurant can't serve. In a business of thin margins and high fixed costs, the interruption is often worse than the fire.","signal":"high-rent locations, financed fit-outs.","when":"","cross":"","claim":"The kitchen fire above closes the restaurant for eight weeks. €50,000 of rent, wages, and leasing fall due with zero revenue — the interruption cover pays it, and the business reopens instead of folding."},{"id":"cov_267","name":"Betriebsschließungsversicherung (ordered-closure cover)","desc":"pays when the health authority closes the operation under the Infection Protection Act: salmonella, norovirus, a positive finding in the kitchen. This is the hospitality-specific policy most owners only learned about the hard way.","signal":"every food business; ask what a ten-day forced closure would cost.","when":"","cross":"","claim":"A norovirus case traced to the kitchen triggers a ten-day ordered closure, deep disinfection, and destruction of open stock — roughly €30,000 in lost margin, disposal, and cleaning. Terms and covered diseases vary sharply by tariff generation — verify the current list."}],"rec":[{"id":"cov_268","name":"Commercial building cover (gewerbliche Gebäudeversicherung)","desc":"fire, water, storm, and (ask actively) natural-hazards cover for owners of the property itself.","signal":"the operator owns the building or the family does.","when":"","cross":"","claim":"A summer storm strips part of the roof over the guest rooms; €60,000 in building damage is the owner's problem, not the tenant's — and only a building policy responds."},{"id":"cov_269","name":"Cyberversicherung","desc":"response, restoration, and liability when the digital side fails: the reservation system, the POS, the guest data.","signal":"online booking, card payments, guest Wi-Fi.","when":"","cross":"","claim":"Ransomware locks the POS and reservation system on a Friday; the weekend runs on paper and guesswork, online bookings bounce, and the recovery specialist costs €18,000. Guest-data exposure adds GDPR notification on top."},{"id":"cov_270","name":"Firmen-Rechtsschutz","desc":"legal costs for the two disputes hospitality actually has: the landlord and the staff.","signal":"rent negotiations, high staff turnover.","when":"","cross":"","claim":"The landlord pushes a contested rent increase on the back of an index clause; fighting it through costs €10,000 in legal fees over 18 months — carried by the legal-expenses policy, which turned a \"we can't afford to argue\" into a negotiation."}],"opt":[{"id":"cov_271","name":"bKV (company health insurance)","desc":"an employer-paid health top-up that visibly cares for people in a sector where everyone is hiring.","signal":"\"we're closed Mondays because we have no staff.\"","when":"","cross":"","claim":"The sous-chef gets fast-track physio for a shoulder through the bKV instead of a three-month wait — and turns down the offer from the hotel across town."},{"id":"cov_272","name":"Gruppen-Unfall (group accident)","desc":"lump sums for the burns, cuts, and falls of kitchen life, and for everything that happens off the clock where the statutory cover is silent.","signal":"kitchen-heavy teams.","when":"","cross":"","claim":"A waiter scalds his hand badly at home canning fruit — no statutory cover, three weeks off. The group accident policy pays the daily benefit that keeps him whole."},{"id":"cov_273","name":"Kunstversicherung (fine art)","desc":"all-risk cover for art in hotels and upscale venues, which contents policies handle badly or cap low.","signal":"originals in the lobby, a collection in the restaurant.","when":"","cross":"","claim":"A water leak ruins a €15,000 painting in the hotel lobby; the art policy pays at agreed value, where the contents policy would have argued about depreciation."}]}},{"id":"handel","icon":"ti-building-store","accent":"#187caa","bg":"#e6f3fa","title":"Retail","types":["Fashion & shoes","food & delicatessen","electronics & telecom","furniture & interiors","sports & leisure","kiosk & convenience"],"policies":{"must":[{"id":"cov_274","name":"Betriebshaftpflicht","desc":"pays when a customer is hurt in the shop or by the shop: the slip at the wet entrance, the shelf display that topples, the traffic-safety duty on the pavement outside. With public foot traffic all day, this is a frequency exposure.","signal":"every shop with a door that opens to the public.","when":"","cross":"","claim":"On a rainy Saturday a customer slips just inside the entrance — no mat, no sign — and breaks a wrist. €15,000 in injury claims and a lesson about the doormat that the policy absorbed."},{"id":"cov_275","name":"Geschäftsinhaltsversicherung (contents)","desc":"replaces stock, fittings, and equipment at replacement value after fire, burglary, water, or storm. Stock *is* the working capital, and it swings with the season, which is why the buffer and the waiver of underinsurance decide whether a payout is full or cut.","signal":"ask what's on the floor and in the back at the seasonal peak versus what's in the policy.","when":"","cross":"","claim":"A burglary in late November clears €70,000 of Christmas stock. The policy's sum insured reflected a quiet March; only the buffer clause and waiver saved the payout from a proportional reduction that would have cost the owner tens of thousands."},{"id":"cov_276","name":"Fixed-cost / business-interruption cover","desc":"pays the prime-location rent and wages while the shop is closed for repairs. In retail the rent doesn't care that the shop is full of dehumidifiers.","signal":"A-location rents, financed fit-outs.","when":"","cross":"","claim":"A burst pipe above the ceiling closes the shop for six weeks in its best quarter. €25,000 of rent and payroll fall due against zero revenue — the interruption cover pays, and the missed season doesn't become a missed year."}],"rec":[{"id":"cov_277","name":"Cyberversicherung","desc":"response, restoration, and liability when the webshop, the POS, or the customer database is hit. The moment a shop sells or markets online, it holds exactly what attackers monetize: payment flows and customer data.","signal":"a webshop, newsletter lists, card terminals.","when":"","cross":"","claim":"Card-skimming code sits in the webshop checkout for three weeks; forensics, mandatory customer notification, and platform cleanup cost €25,000 — before a cent of the reputational repair."},{"id":"cov_278","name":"Elektronikversicherung","desc":"an all-risk policy for the electronics the shop runs on: tills, scanners, label printers, digital signage. It pays for the surge, the drop, and the spilled coffee that a standard contents policy calls \"operating damage\" and declines.","signal":"modern POS setups, screens in the window.","when":"","cross":"","claim":"A power surge after grid works kills the POS system and two display screens — €12,000, paid as an electronics claim where the contents policy would have argued."},{"id":"cov_279","name":"Transport cover (goods)","desc":"insures the shop's goods while they move: from the wholesaler, between branches, in the owner's own van. The contents policy stops at the shop door.","signal":"own pickup runs, multi-branch stock transfers.","when":"","cross":"","claim":"The owner's van is rear-ended on a stock run between branches; €18,000 of fashion stock is crushed and soaked. Motor liability pays the other driver — only transport cover pays for the goods."},{"id":"cov_280","name":"Firmen-Rechtsschutz","desc":"legal costs for retail's two chronic disputes: the commercial lease and employment.","signal":"index-rent letters, staffing churn.","when":"","cross":"","claim":"The landlord invokes an index clause for a steep rent increase; contesting the calculation takes €8,000 in legal fees and ends in a compromise the shop could live with — a fight it could only afford because the policy paid the lawyers."}],"opt":[{"id":"cov_281","name":"Betriebsschließungsversicherung (ordered-closure cover)","desc":"pays when the health authority closes a food retailer under the Infection Protection Act.","signal":"any shop selling unpackaged food.","when":"","cross":"","claim":"A rodent finding closes a delicatessen for a week of pest control and deep cleaning — €12,000 in lost margin and destroyed open goods, plus the cleanup bill."},{"id":"cov_282","name":"Commercial building cover","desc":"for the retailer who owns the building: fire, water, storm, and the natural-hazards question asked out loud.","signal":"owner-occupied premises.","when":"","cross":"","claim":"Storm damage to the facade and roof runs to €40,000 — a building-policy claim that neither contents nor interruption cover touches."},{"id":"cov_283","name":"Gruppen-Unfall / bKV (benefits)","desc":"accident lump sums beyond the statutory system and a health top-up, as retention tools in branch operations that constantly hire.","signal":"multiple branches, chronic vacancies.","when":"","cross":"","claim":"A branch manager who gets employer-paid dental and a private accident lump sum after a cycling crash tells every new hire about it — cheaper than one recruiter invoice."}]}},{"id":"immobilien","icon":"ti-building-skyscraper","accent":"#545241","bg":"var(--en-warmgrey-light)","title":"Real Estate & Property Management","types":["Property managers (WEG & rental)","portfolio landlords","estate agents","small-scale development","facility owners","holiday letting"],"policies":{"must":[{"id":"cov_284","name":"Vermögensschaden-Haftpflichtversicherung (professional indemnity)","desc":"pays when a professional mistake costs clients money without anything being physically damaged: a missed deadline, a wrong statement, a botched owners' resolution. For residential property managers and estate agents this cover is required by professional law — and pure financial loss is precisely what the Betriebshaftpflicht excludes.","signal":"every licensed manager and agent; verify the level against the current statutory minimums.","when":"","cross":"","claim":"A manager lets a WEG building's insurance lapse during a carrier switch; a fire then finds the building underinsured, and the owners sue the manager for the €100,000+ difference. That claim lands on the PI policy — or on the manager personally."},{"id":"cov_285","name":"Betriebshaftpflicht incl. property-owner liability (Haus- und Grundbesitzerhaftpflicht)","desc":"pays when someone is injured because of the building or the ground: the icy pavement, the loose step, the falling tile. Managers carry it for managed objects, owners for their own.","signal":"every managed or owned building.","when":"","cross":"","claim":"A loose roof tile comes down in a gust and injures a pedestrian — a €50,000 bodily-injury claim against the owner for breached maintenance duty, defended and paid by the property-owner liability cover."},{"id":"cov_286","name":"Commercial building cover","desc":"the core asset protection for portfolio holders: fire, water, storm — and the natural-hazards (Elementar) module raised proactively, because heavy-rain losses are the fastest-growing claim in the segment.","signal":"every owned building; ask which ones have Elementar.","when":"","cross":"","claim":"A cloudburst backs up the sewer and floods a building's basement and heating plant — €70,000. Without the Elementar module, the standard building policy pays nothing on backflow and surface water."}],"rec":[{"id":"cov_287","name":"Mietkautionsversicherung (rental deposit insurance)","desc":"replaces the cash deposit with a guarantee, so tenants don't tie up three months' rent and landlords still hold security.","signal":"every landlord conversation about new lettings.","when":"","cross":"","claim":"A commercial tenant moves in without parking €9,000 cash; the landlord holds an insurer's guarantee instead and lets the unit faster — a product that sells itself in the letting conversation."},{"id":"cov_288","name":"Photovoltaik cover","desc":"insures the rooftop plant itself (storm, hail, fire, technical failure, theft) and the feed-in revenue it earns. Building policies don't automatically pick up a PV plant cleanly.","signal":"PV going onto portfolio roofs, WEG resolutions on solar.","when":"","cross":"","claim":"An inverter fault starts a small roof fire; €35,000 in panel, roof, and revenue loss. The building insurer points at the PV plant, the PV insurer at the roof — unless the allocation was sorted at placement, which is the agent's job."},{"id":"cov_289","name":"Firmen-Rechtsschutz","desc":"legal costs for the disputes that fill a manager's week: rent arrears, evictions, owner-association conflicts.","signal":"any manager with open cases.","when":"","cross":"","claim":"An eviction for arrears grinds through 18 months of court — €12,000 in legal costs before the unit is recovered. The legal-expenses policy carried it; the rent shortfall was bad enough."},{"id":"cov_290","name":"Bauleistungsversicherung (builders risk)","desc":"covers refurbishment and roof projects in the portfolio while they're half-done, when neither the building policy nor the contractor's cover fully protects the owner's interest.","signal":"planned facade, roof, or energy refits.","when":"","cross":"","claim":"Mid-refurbishment, a storm drives rain through the opened roof into three renovated floors — €45,000. The building policy calls it a construction risk; builders risk is the policy built for exactly this window."}],"opt":[{"id":"cov_291","name":"Cyberversicherung","desc":"response and liability when the manager's systems are breached. A management firm holds bank details, service-charge accounts, and personal data for entire owner communities — a rich, soft target.","signal":"digital owner portals, SEPA collection runs.","when":"","cross":"","claim":"The manager's email is compromised and owners receive a convincing \"new account for service-charge payments\" — €30,000 lands with a fraudster across a dozen owners before anyone calls. Response costs, notification, and liability follow."},{"id":"cov_292","name":"Kunstversicherung","desc":"agreed-value cover for art in representative lobbies and managed prestige objects.","signal":"originals in entrance halls.","when":"","cross":"","claim":"Movers damage a lobby sculpture during a refit — €10,000 at agreed value, no depreciation argument."}]}},{"id":"beratung","icon":"ti-briefcase","accent":"#b31767","bg":"var(--en-violet-light)","title":"Professional & Financial Services","types":["Management consulting","financial & insurance intermediaries","payroll & bookkeeping services","surveyors & experts","recruiting","translation"],"policies":{"must":[{"id":"cov_293","name":"Vermögensschaden-Haftpflichtversicherung (professional indemnity)","desc":"pays when advice, a calculation, or a missed deadline costs the client money. This is the segment's core policy because the product *is* the advice, and errors here never break anything physical — they only destroy value, which is exactly what general liability excludes. For several licensed professions it is legally mandatory.","signal":"every advisory business; check mandatory status and minimums per license.","when":"","cross":"","claim":"A payroll service applies the wrong social-contribution parameters for a year; the client faces €60,000 in back payments and penalties and passes the bill straight to the provider. PI defends, negotiates, and pays what's owed."},{"id":"cov_294","name":"Betriebshaftpflicht","desc":"the ordinary premises-and-people liability: a visitor trips, a laptop bag knocks a client's equipment off the desk. Small next to the PI risk, but the claims are real and cheap to cover.","signal":"any office with visitors or work at client sites.","when":"","cross":"","claim":"A client's representative trips over a presentation cable in the meeting room and fractures an elbow — €12,000, cleanly a general-liability claim, cleanly excluded from PI."},{"id":"cov_295","name":"Cyberversicherung","desc":"response, restoration, notification, and liability when client data leaks or systems lock. For an advisory firm the data *is* the relationship: mandates, financials, personal records.","signal":"cloud tools, remote work, client portals.","when":"","cross":"","claim":"Ransomware encrypts the file server including years of client records; recovery, forensics, and GDPR notification to every affected client cost €30,000 — and the funded, professional response is what keeps the top three mandates from leaving."}],"rec":[{"id":"cov_296","name":"Contents + Elektronikversicherung","desc":"replacement-value cover for the office and an all-risk layer for the hardware it actually runs on: laptops, servers, presentation tech — including drops, surges, and theft from the car, which contents policies exclude or cap.","signal":"mobile teams, financed IT.","when":"","cross":"","claim":"A burst pipe over the weekend soaks the server cabinet and four workstations — €22,000, split between the contents claim (furniture, fit-out) and the electronics claim (the hardware, at conditions a plain contents policy wouldn't match)."},{"id":"cov_297","name":"Firmen-Rechtsschutz","desc":"legal costs for the firm's own fights, above all unpaid fees and employment disputes — the two cases advisory firms swallow most often because suing a client feels expensive.","signal":"receivables complaints, growing headcount.","when":"","cross":"","claim":"A client refuses a €25,000 project fee claiming the deliverable \"wasn't usable\"; two instances of litigation cost €11,000 in fees — paid by the policy, and the firm collected rather than writing it off."},{"id":"cov_298","name":"Dienstreiseversicherung (business travel)","desc":"medical, evacuation, luggage, and liability cover for staff traveling on business, where statutory and private health cover leave gaps abroad.","signal":"consultants at client sites, international projects.","when":"","cross":"","claim":"A consultant collapses with appendicitis at a client site abroad; treatment and medically escorted return run to €15,000 — a travel-policy claim the firm would otherwise have paid from goodwill."}],"opt":[{"id":"cov_299","name":"bAV / bKV (pension & health benefits)","desc":"employer-funded pension and health top-ups, the standard currency in the competition for qualified staff.","signal":"hiring frustration, counteroffers.","when":"","cross":"","claim":"A senior analyst weighing two offers takes the one with a funded bAV and employer bKV — benefits that cost the firm a fraction of the salary bump the competitor would have needed."},{"id":"cov_300","name":"Gruppen-Unfallversicherung (group accident)","desc":"lump-sum accident cover reaching where the statutory system doesn't: leisure time, and the owner, who often has no statutory accident cover at all.","signal":"owner-managers with no personal accident policy.","when":"","cross":"","claim":"The founding partner tears knee ligaments skiing — three months of reduced capacity, zero statutory benefits because it was private and she's the owner. The group accident policy's lump sum bridges what her absence costs."}]}},{"id":"it","icon":"ti-code","accent":"#0f6f9c","bg":"#e6f3fa","title":"IT & Digital Services","types":["Software development","IT system houses & managed services","web development","IT consulting","hosting & cloud","e-commerce services"],"policies":{"must":[{"id":"cov_301","name":"Vermögensschaden-Haftpflicht for IT (IT professional indemnity)","desc":"pays when the firm's code, configuration, or advice costs the client money without breaking anything physical: the botched update, the misconfigured firewall, the data migration that loses records. This is the IT firm's core liability, because its errors are almost never property damage.","signal":"every firm shipping software or managing client systems; check the IT wording and how it combines with general liability.","when":"","cross":"","claim":"A faulty release halts a client's production planning for two days; the client invoices €120,000 in standstill costs. General liability shrugs — nothing was damaged. The IT-PI policy defends and pays."},{"id":"cov_302","name":"Betriebshaftpflicht","desc":"the physical-world liability that still exists in a digital business: the technician who drops a client's switch, the visitor who trips in the office. Usually bundled with the IT-PI, and the bundle is the point.","signal":"on-site work at client premises.","when":"","cross":"","claim":"During a rack migration, a technician's slip sends a client's storage unit to the floor — €18,000 of hardware. Physical damage, so this is the general-liability half of the package paying."},{"id":"cov_303","name":"Cyberversicherung (the firm's own)","desc":"response, restoration, interruption, and liability when the IT firm itself is breached. Doubly critical here: the firm's downtime cascades into every client it manages, and an IT provider that can't fund its own professional incident response loses the room.","signal":"admin access to client systems, managed-services contracts.","when":"","cross":"","claim":"An attacker compromises the MSP's remote-management tool and pivots toward client networks. Containment, forensics across environments, and client notification cost €80,000 — and the insurer's response team working alongside the firm is what keeps clients from leaving."}],"rec":[{"id":"cov_304","name":"Elektronikversicherung","desc":"all-risk cover for the development and server hardware, including surge, drop, and theft — the failure modes contents policies exclude.","signal":"own rack, high-spec workstations.","when":"","cross":"","claim":"A failed UPS lets a surge through and cooks two servers and a switch — €16,000, paid as an electronics claim."},{"id":"cov_305","name":"Firmen-Rechtsschutz","desc":"legal costs for the sector's signature dispute: the client who won't sign off. Project acceptance, scope, and payment fights are where IT firms bleed quietly.","signal":"\"the client won't accept the release.\"","when":"","cross":"","claim":"A client refuses acceptance of a €60,000 platform build citing \"missing features\" that were never in scope; the legal battle to enforce payment costs €14,000 in fees — carried by the policy, and the invoice gets paid."},{"id":"cov_306","name":"Contents + fixed-cost cover","desc":"replacement value for the office and the fixed costs that run if it's unusable. Lean, but real once premises and people exist.","signal":"own office, growing team.","when":"","cross":"","claim":"An electrical fire makes the office unusable for a month; €10,000 of rent and recurring costs run against a team working from kitchens — the fixed-cost cover pays while the lease doesn't care."}],"opt":[{"id":"cov_307","name":"bAV (company pension)","desc":"employer-funded pension, near hygiene-factor in IT recruiting.","signal":"every hiring conversation in this sector.","when":"","cross":"","claim":"A developer choosing between offers asks about the pension scheme in the first interview — the firm with a funded bAV answers in one sentence; the firm without loses candidates it never hears about."},{"id":"cov_308","name":"Dienstreiseversicherung (business travel)","desc":"medical and evacuation cover for project staff at client sites.","signal":"consultants embedded at customers, international rollouts.","when":"","cross":"","claim":"An engineer on a rollout abroad lands in hospital after a scooter accident; treatment and return transport cost €12,000 — a travel-policy claim, not a payroll dispute."}]}},{"id":"agentur","icon":"ti-palette","accent":"#9b2fae","bg":"var(--en-violet-light)","title":"Agencies, Marketing & Media","types":["Advertising & creative agencies","social media & performance marketing","photo & video production","PR & communications","design & branding","publishing & content"],"policies":{"must":[{"id":"cov_309","name":"Betriebshaftpflicht + Vermögensschaden-Haftpflicht (with media wording)","desc":"the pair that covers agency life: general liability for the physical world (the set, the office, the event), and PI for the real agency risk — published work that infringes someone's rights or a campaign error that costs the client money. Rights infringement and flawed execution are pure financial losses, and only a media-aware PI wording carries them.","signal":"every firm that publishes for clients; verify which module carries rights infringement before quoting.","when":"","cross":"","claim":"A campaign ships with a stock photo whose license didn't cover outdoor advertising; the photographer's agency claims €20,000. Second classic: a booking error runs the client's ad in the wrong market, and the client invoices the wasted €45,000 media spend."},{"id":"cov_310","name":"Cyberversicherung","desc":"response and liability when the agency's accounts or systems are hit. Agencies hold something uniquely dangerous: admin access to clients' ad accounts, shops, and social channels, plus budget authority over other people's money.","signal":"managed ad accounts, client logins in a password tool.","when":"","cross":"","claim":"A phished login lets an attacker into a client's ad account overnight; €35,000 of the client's budget is burned on fraud placements before the alarm. The client wants it back from the agency — cyber cover funds the response and the liability discussion."}],"rec":[{"id":"cov_311","name":"Elektronikversicherung","desc":"all-risk cover for camera, edit, and production gear, including the failure modes that matter on location: drop, theft from the vehicle, water.","signal":"shoots, kits that travel.","when":"","cross":"","claim":"A camera kit worth €28,000 is stolen from the crew van during a location lunch — an electronics/equipment claim; the office contents policy stopped applying at the office door."},{"id":"cov_312","name":"Contents + fixed-cost cover","desc":"replacement value for studio and fit-out plus the fixed costs that run if the space is out of action.","signal":"own studio, edit suites.","when":"","cross":"","claim":"A sprinkler fault soaks the studio and edit suite — €30,000 in fit-out and idle weeks of rent, split between the contents and fixed-cost claims."},{"id":"cov_313","name":"Firmen-Rechtsschutz","desc":"legal costs for the agency's chronic fights: fees and usage rights after the relationship sours.","signal":"scope-creep stories, clients using work beyond the license.","when":"","cross":"","claim":"A former client keeps running campaign assets two years after the license ended; enforcing the usage rights costs €9,000 in legal fees — carried by the policy, and the settlement paid for the year."}],"opt":[{"id":"cov_314","name":"Dienstreiseversicherung (business travel)","desc":"medical, evacuation, and equipment-adjacent cover for productions and pitches away from base.","signal":"shoots abroad, traveling crews.","when":"","cross":"","claim":"A producer breaks an ankle on a foreign location; treatment and early return cost €8,000 — a travel-policy claim, not a production overrun."},{"id":"cov_315","name":"Kunstversicherung","desc":"agreed-value cover for agencies with collections or exhibition space.","signal":"originals on the walls, gallery-style offices.","when":"","cross":"","claim":"A client event leaves a €12,000 piece damaged; the art policy pays at agreed value while a contents policy would have argued depreciation."}]}},{"id":"heilberufe","icon":"ti-stethoscope","accent":"#009284","bg":"var(--en-leaf-light)","title":"Healthcare & Care Services","types":["Physiotherapy","occupational & speech therapy","alternative practitioners (Heilpraktiker)","outpatient care services","midwife practices","podiatry"],"policies":{"must":[{"id":"cov_316","name":"Business & professional liability (Betriebs-/Berufshaftpflicht)","desc":"pays when treatment injures a patient, and defends when a patient merely alleges it did. In hands-on professions, bodily injury from treatment is the core risk, professional law usually requires the cover, and the defense function matters as much as the payout: the unfounded allegation still needs experts and lawyers.","signal":"every treating practice; verify the professional-law requirement per profession.","when":"","cross":"","claim":"A physiotherapy manipulation is blamed for worsening a disc injury; the patient claims €70,000. The expert battle takes two years — the policy funds the defense throughout and pays only what's actually owed."},{"id":"cov_317","name":"Contents + Elektronikversicherung","desc":"replacement value for the practice fit-out plus all-risk cover for the treatment devices, which are financed, sensitive, and worth more than anyone remembers.","signal":"device-heavy practices, leasing contracts.","when":"","cross":"","claim":"A weekend water leak ruins the shockwave unit and two treatment tables — €25,000, with the device paid under the electronics cover at terms a plain contents policy wouldn't offer."},{"id":"cov_318","name":"Fixed-cost cover (Betriebskosten)","desc":"pays the rent and salaries that continue while the practice can't treat or bill. Practices bill per session; when the rooms close, revenue is zero on day one.","signal":"high fit-out financing, salaried therapists.","when":"","cross":"","claim":"Water damage closes the practice for five weeks; €30,000 of rent, salaries, and leasing fall due against no billable sessions — the fixed-cost cover pays and the practice reopens solvent."}],"rec":[{"id":"cov_319","name":"Cyberversicherung","desc":"response, restoration, and notification when patient data is exposed or the practice software locks. Patient records are health data — the most sensitive GDPR category, with the strictest duties and the ugliest headlines.","signal":"digital patient files, online booking.","when":"","cross":"","claim":"Ransomware encrypts the practice software on a Monday: no schedules, no records, no billing. Recovery and mandatory notification cost €22,000 — and the funded incident response is what keeps a data-protection complaint from becoming a fine."},{"id":"cov_320","name":"Firmen-Rechtsschutz","desc":"legal costs for the disputes practices actually face: billing clawbacks from payers, employment conflicts, professional-law proceedings. Sector-specific healthcare variants exist — check availability.","signal":"payer audits, growing staff.","when":"","cross":"","claim":"A health-insurer audit demands €18,000 in billing clawbacks; contesting it with specialized counsel costs €7,000 and cuts the clawback by two-thirds — a fight worth having only because the policy paid for it."},{"id":"cov_321","name":"Fleet cover","desc":"for outpatient care services, the cars *are* the operation: a dozen small vehicles on daily tours mean motor claims are a monthly reality, and one uninsured gap stops tours.","signal":"care services with route plans.","when":"","cross":"","claim":"A carer's morning tour ends in a junction collision — injury liability plus a written-off car. The fleet contract absorbs both and swaps in a replacement vehicle before the afternoon tour."}],"opt":[{"id":"cov_322","name":"Gruppen-Unfall / bKV (benefits)","desc":"accident lump sums beyond the statutory system and an employer health top-up — which is doubly credible coming from a health-sector employer.","signal":"physically loaded teams, recruiting pain.","when":"","cross":"","claim":"A carer herniates a disc lifting at home — private, so no statutory accident benefits. The group accident policy pays a lump sum, and the employer's bKV fast-tracks her physio; both stories travel through the team."},{"id":"cov_323","name":"Betriebsschließungsversicherung (ordered-closure cover)","desc":"pays when the health authority closes a facility under the Infection Protection Act.","signal":"day-care structures, group settings.","when":"","cross":"","claim":"A norovirus outbreak closes a day-care facility for a week of disinfection — lost fees and cleaning costs around €10,000, covered where the wording includes the facility type; verify scope."}]}},{"id":"pflegefitness","icon":"ti-scissors","accent":"#c0246f","bg":"var(--en-rose-50)","title":"Personal Care & Fitness","types":["Hair salons","cosmetics & nail studios","barbershops","gyms","yoga & personal training","non-therapeutic massage"],"policies":{"must":[{"id":"cov_324","name":"Betriebshaftpflicht","desc":"pays when the service itself injures the client — the chemical burn, the allergic reaction, the training injury from faulty instruction — and when the premises do it: the wet floor, the loose mat. In this segment the \"treatment damage\" clause is the heart of the policy, because the injury happens *through* the service.","signal":"every hands-on or instruction-based business; ask about new services (peels, EMS) the wording may not know.","when":"","cross":"","claim":"A coloring goes wrong and the client suffers scalp burns and patchy hair loss — €18,000 in damages and treatment costs. In the gym version, a trainer's misloaded machine drops a weight on a member's foot."},{"id":"cov_325","name":"Contents + fixed-cost cover","desc":"replacement value for the fit-out and equipment plus the rent and wages that continue while the studio is closed. These businesses are their rooms; no rooms, no revenue.","signal":"fresh renovations, leased equipment.","when":"","cross":"","claim":"A night fire guts a salon a week after its refit — €40,000 in fit-out and stock, plus six weeks of rent and wages carried by the fixed-cost cover while the rebuild runs."}],"rec":[{"id":"cov_326","name":"Cyberversicherung","desc":"response and notification when booking systems and member data are exposed. Studios hold names, health notes, and payment mandates — a full identity kit.","signal":"booking apps, subscription billing.","when":"","cross":"","claim":"The booking platform account is breached and member payment data exposed; notification, forensics, and platform migration cost €12,000 — and the calm, funded response is what keeps members from cancelling."},{"id":"cov_327","name":"Elektronikversicherung","desc":"all-risk cover for studio and treatment technology: EMS units, laser and cosmetic devices, sound systems — financed gear that dies from surges and spills, which contents policies exclude.","signal":"device-based services.","when":"","cross":"","claim":"A surge kills the EMS system — €9,000 and a cancelled week of sessions; paid as an electronics claim."},{"id":"cov_328","name":"Firmen-Rechtsschutz","desc":"legal costs for the lease and the team, the two disputes this segment actually has.","signal":"rent negotiations, trainer churn.","when":"","cross":"","claim":"The landlord contests the permitted use when the salon adds cosmetic treatments; sorting the lease dispute costs €6,000 in fees — carried by the policy."}],"opt":[{"id":"cov_329","name":"bKV / Gruppen-Unfall (benefits)","desc":"health top-up and accident lump sums as retention tools in a high-churn trade where trained staff can open next door.","signal":"churn complaints.","when":"","cross":"","claim":"A stylist stays through a poaching attempt because the employer's bKV covered her €800 dental bill last spring — loyalty bought at a fraction of a rehire."},{"id":"cov_330","name":"Commercial building cover","desc":"for the owner-occupied studio: fire, water, storm on the building itself.","signal":"owned premises.","when":"","cross":"","claim":"Storm damage to the studio's roof and glazing runs €20,000 — a building claim neither contents nor interruption cover touches."}]}},{"id":"kfz","icon":"ti-car","accent":"#4a4838","bg":"var(--en-warmgrey-light)","title":"Automotive Trades","types":["Independent workshops","body & paint","tire service","detailing","car dealers","towing & roadside"],"policies":{"must":[{"id":"cov_331","name":"Betriebshaftpflicht with an automotive-trade wording","desc":"pays for injury and damage from the operation, and — the existential part — for damage to customer vehicles in the firm's custody: moving them, working on them, storing them. A standard liability policy classically *excludes* property in custody, which in this trade is the entire business model. The trade solution also carries dealer plates and test drives.","signal":"every yard full of customer cars; verify the custody wording and red-plate cover before promising anything.","when":"","cross":"","claim":"An employee moving a customer's car in the yard misjudges a pillar — €22,000 on a premium vehicle. On a standard policy: excluded as custody damage. On the trade wording: paid. Second classic: the test drive that ends in a junction."},{"id":"cov_332","name":"Geschäftsinhaltsversicherung (contents)","desc":"replacement value for the workshop's working capital: lifts, diagnostics, tools, and the parts inventory.","signal":"recently upgraded diagnostic and calibration equipment the sum insured predates.","when":"","cross":"","claim":"A break-in targets exactly what resells: €30,000 of diagnostic units and tool trolleys gone in a night — replaced at today's prices because the sum insured was current."},{"id":"cov_333","name":"Environmental modules","desc":"the liability extensions for what a workshop necessarily handles: oils, fuels, coolants, batteries. When they escape, the bill is a public-law cleanup order, not a normal damages claim — and only the environmental modules respond.","signal":"every workshop; ask how fluids are stored and where the separator drains.","when":"","cross":"","claim":"A failed oil separator lets waste oil into the soil; the authority orders excavation and remediation — €50,000, payable regardless of fault. Verify the environmental liability and environmental-damage scope in the conditions."}],"rec":[{"id":"cov_334","name":"Fixed-cost cover","desc":"pays the rent, wages, and leasing that run while the workshop can't work. Bays full of half-finished jobs earn nothing during a rebuild.","signal":"leased premises, financed equipment.","when":"","cross":"","claim":"An electrical fire closes the workshop for seven weeks; €35,000 of fixed costs fall due against zero throughput — paid by the interruption cover, and the customer base survives the closure because the firm does."},{"id":"cov_335","name":"Maschinenversicherung (machinery breakdown)","desc":"pays for the internal failure of high-value stationary equipment — the breakdown from within that fire and contents policies don't cover.","signal":"lifts, alignment rigs, paint booths.","when":"","cross":"","claim":"A lift's hydraulic system fails mid-service — €15,000 in repair and the near-miss report that changes how everyone reads \"machinery breakdown.\""},{"id":"cov_336","name":"Firmen-Rechtsschutz","desc":"legal costs for the trade's permanent condition: disputed repair invoices and warranty accusations.","signal":"stories of customers refusing to pay.","when":"","cross":"","claim":"A customer disputes a €4,000 engine repair and threatens court; the legal-expenses policy pays for the lawyer and the expert who proves the diagnosis — the invoice gets paid and the Google review war stays short."}],"opt":[{"id":"cov_337","name":"Cyberversicherung","desc":"response cover for the workshop's digital spine: planning software, diagnostic systems, customer data.","signal":"digital job cards, connected diagnostics.","when":"","cross":"","claim":"Ransomware locks the workshop-management system; no job cards, no history, no invoicing for a week — €14,000 in recovery and lost throughput."},{"id":"cov_338","name":"Gruppen-Unfall / bKV (benefits)","desc":"accident lump sums and a health top-up for a trade competing hard for mechanics.","signal":"open positions measured in months.","when":"","cross":"","claim":"A mechanic breaks a wrist mountain-biking — no statutory cover, six weeks out; the group accident policy pays the daily benefit that keeps him financially whole."},{"id":"cov_339","name":"Kautionsversicherung (surety)","desc":"insurer-issued bonds where franchise or partner contracts demand security.","signal":"brand-partner agreements with bond clauses.","when":"","cross":"","claim":"A service-partner contract requires a €25,000 guarantee; the surety line issues it without touching the credit line."}]}},{"id":"bildung","icon":"ti-school","accent":"#0f7fa0","bg":"var(--en-iceblue-light)","title":"Education & Training","types":["Private training providers","tutoring institutes","driving schools","music & art schools","coaching & seminars","language schools"],"policies":{"must":[{"id":"cov_340","name":"Betriebshaftpflicht","desc":"pays when participants are injured on the premises, at events, or on excursions — and defends the supervision-duty allegation that follows every incident involving a minor. Parents' expectations are high and emotional; the policy's defense function matters as much as its payout.","signal":"minors in courses, off-site activities, group sizes.","when":"","cross":"","claim":"On a course excursion a nine-year-old falls from a climbing frame and breaks an arm; the parents allege inadequate supervision and claim €40,000. The policy funds the defense and pays what the supervision facts actually support."},{"id":"cov_341","name":"Contents + Elektronikversicherung","desc":"replacement value for classrooms and equipment, with all-risk cover for the technology — and, for music schools, the instruments, whose valuation and off-premises use need explicit attention.","signal":"instrument inventories, laptop classrooms.","when":"","cross":"","claim":"A burst radiator pipe over a holiday weekend ruins a music school's piano and three student cellos — €20,000, paid correctly only because the instruments were listed and valued rather than lumped into \"contents.\""}],"rec":[{"id":"cov_342","name":"Cyberversicherung","desc":"response and notification when participant data or course platforms are hit. Education providers hold children's data and parents' payment details — a combination with zero public tolerance for sloppy handling.","signal":"online course platforms, installment billing.","when":"","cross":"","claim":"The registration platform is breached and participant data including children's records exposed; forensics and notification to every family cost €15,000 — and the professionally handled response is what keeps enrollment from collapsing."},{"id":"cov_343","name":"Firmen-Rechtsschutz","desc":"legal costs for the disputes providers actually face: refund demands, contract fights with participants, disagreements with freelance instructors.","signal":"cancellation-policy arguments.","when":"","cross":"","claim":"A parent demands a full refund plus damages after a course is restructured mid-year; the dispute runs to court and €6,000 in fees — carried by the policy."},{"id":"cov_344","name":"Vermögensschaden-Haftpflicht (professional indemnity)","desc":"pays when wrong advice or administrative error costs a participant money without physical harm: the missed exam registration, the wrong qualification pathway. Relevant the moment outcomes are promised.","signal":"certified qualifications, exam-prep promises.","when":"","cross":"","claim":"An exam-prep provider gives wrong registration-deadline advice and a student loses a year; the family quantifies tuition and lost income at €15,000 — a pure financial loss only PI covers."}],"opt":[{"id":"cov_345","name":"Fleet cover","desc":"for driving schools the vehicles are the classroom: dual-control cars in constant learner use, which is a motor risk profile of its own with a dedicated wording to match.","signal":"every driving school.","when":"","cross":"","claim":"A learner freezes at a junction and the instructor's brake comes a half-second late — €12,000 across two vehicles. Frequency is the story here; the dedicated driving-school wording prices and manages it."},{"id":"cov_346","name":"Gruppen-Unfallversicherung (group accident)","desc":"participant accident cover as a quality marker private providers can offer, since statutory pupil accident insurance covers school contexts, not private courses.","signal":"parents asking about insurance on the enrollment form.","when":"","cross":"","claim":"A participant sprains an ankle in a dance course; the provider's group accident policy pays a benefit without any liability question — and the enrollment brochure that mentions this cover wins the next comparison against the studio that doesn't."},{"id":"cov_347","name":"Dienstreiseversicherung (business travel)","desc":"medical and evacuation cover for traveling instructors and trainers.","signal":"trainers on the road, seminars delivered abroad.","when":"","cross":"","claim":"A trainer falls ill at a seminar abroad; treatment and rebooking cost €5,000 — a travel-policy claim."}]}},{"id":"events","icon":"ti-confetti","accent":"#d4651a","bg":"var(--en-orange-light)","title":"Events & Entertainment","types":["Event agencies","event technology & rental","trade-fair construction","catering & mobile food","DJs & artist services","wedding & event planning"],"policies":{"must":[{"id":"cov_348","name":"Betriebshaftpflicht with an organizer wording (Veranstalterhaftpflicht)","desc":"pays when visitors are injured or property is damaged at the event: the structure that fails, the cable run someone trips on, the assumed traffic-safety duties of the whole venue. Standard business liability doesn't automatically carry organizer risk, and tariffs cap the event sizes and types they'll accept.","signal":"every firm running or building events; clarify covered sizes and formats in advance.","when":"","cross":"","claim":"A truss element comes down during a show and seriously injures a visitor — a €150,000 bodily-injury claim against the organizer. This is the claim the organizer wording exists for, and the one a standard policy would fight about."},{"id":"cov_349","name":"Elektronikversicherung + transport cover","desc":"the pair that follows the gear: all-risk electronics cover for sound, light, and video (including rented and loaned units), and transport cover for the hours in the van — because the stationary contents policy ends at the warehouse door and event gear lives on the road.","signal":"loaded vans overnight before shows, rented kit in the mix.","when":"","cross":"","claim":"The night before a festival, €60,000 of lighting rig is stolen from the van at a motorway hotel. Contents policy: not on premises, denied. The electronics/transport combination: paid, and a rental replacement funded in time for doors."},{"id":"cov_350","name":"Fleet cover","desc":"legally required liability per vehicle, and operationally the backbone: vans and trailers moving heavy, awkward loads on deadline.","signal":"every technology and build operation.","when":"","cross":"","claim":"A trailer of stage decking jackknifes on a wet ramp, damaging the trailer, the load, and a parked car — liability, own-damage, and cargo questions in one incident, sorted cleanly only because fleet, transport, and equipment covers were placed to interlock."}],"rec":[{"id":"cov_351","name":"Montageversicherung (erection cover)","desc":"protects stages, stands, and structures during build-up and tear-down, the phase where most physical losses happen and where the boundary to liability cover needs to be drawn deliberately.","signal":"own stage or trade-fair construction.","when":"","cross":"","claim":"During build-up a stage section collapses, wrecking the section and gouging the venue's floor — €25,000 across own-structure damage (erection cover) and venue damage (liability). Knowing which policy takes which half is the placement work."},{"id":"cov_352","name":"Contents cover","desc":"replacement value for the warehouse and workshop where the gear winters.","signal":"off-season storage full of value.","when":"","cross":"","claim":"A January warehouse fire takes staging, cabling, and casework — €45,000, at a moment when there's no revenue to absorb it."},{"id":"cov_353","name":"Firmen-Rechtsschutz","desc":"legal costs for the sector's constant fights: cancellations, contract disputes, unpaid fees.","signal":"cancellation stories, deposit arguments.","when":"","cross":"","claim":"A corporate client cancels a produced event two weeks out and refuses the cancellation fee; enforcing the €30,000 contract costs €8,000 in legal fees — paid by the policy."}],"opt":[{"id":"cov_354","name":"Cyberversicherung","desc":"response and notification when ticketing systems and attendee data are hit.","signal":"own ticket shops, attendee databases.","when":"","cross":"","claim":"The ticket shop is skimmed for a month; card-data notification and forensics cost €18,000 before the refund wave."},{"id":"cov_355","name":"Gruppen-Unfall (group accident)","desc":"lump sums for riggers and build crews whose risk profile doesn't end with the shift.","signal":"crews working at height.","when":"","cross":"","claim":"A rigger is hurt climbing privately on a day off — no statutory cover; the group accident lump sum bridges the months of recovery."},{"id":"cov_356","name":"Event cancellation (Veranstaltungsausfallversicherung)","desc":"covers the costs and lost revenue when an event can't happen (weather, illness of key performers, venue failure). A specialty line with narrow appetite and event-by-event underwriting.","signal":"whenever a client's whole year hangs on one date.","when":"","cross":"","claim":"An open-air event is rained off and €80,000 in sunk costs evaporate — the loss cancellation cover exists for. Log the need and place it case by case; never improvise an answer on terms."}]}},{"id":"produktion","icon":"ti-building-factory-2","accent":"#246b8f","bg":"#e6f3fa","title":"Light Manufacturing & Wholesale Distribution","types":["Metal & plastics processing","small food production","packaging & assembly","technical wholesale","building-materials trade","import & distribution"],"policies":{"must":[{"id":"cov_357","name":"Betriebshaftpflicht / industrial liability with extended product liability","desc":"pays when the firm's product injures someone or damages something after it leaves the gate. The moment goods are produced, processed, or sold under the firm's own name, the extended product-liability wording (erweiterte Produkthaftpflicht) is the core — it covers the expensive downstream scenarios like the customer's costs of removing and reinstalling a defective part. Recall costs (Rückrufkosten) need to be raised proactively, because a recall hits even the faultless supplier in the chain. Beyond a certain size, this becomes an industrial placement rather than a standard commercial tariff.","signal":"own-name products, private-label production, supplying into larger brands.","when":"","cross":"","claim":"A machined component fails inside a customer's assembly; the customer recalls the batch and passes on €90,000 in removal, reinstallation, and recall logistics. Basic product liability would pay a fraction; the extended wording with recall cover carries it."},{"id":"cov_358","name":"Contents + Maschinenversicherung (contents + machinery breakdown)","desc":"replacement value for plant and warehouses, plus machinery-breakdown cover for the failure *from within* — the spindle crash, the drive failure — that fire policies don't touch.","signal":"production lines, CNC parks, full raw-material stores.","when":"","cross":"","claim":"A CNC spindle crash wrecks the machining center — €45,000 in repair. No fire, no storm, no burglary: only the machinery policy responds, and the interruption cover (next) picks up the standstill."},{"id":"cov_359","name":"Business interruption","desc":"pays the lost contribution margin and continuing costs while production stands. In manufacturing the bottleneck is existential: one machine, one warehouse, one key customer.","signal":"ask which single machine's failure stops everything.","when":"","cross":"","claim":"A fire on the single production line stops output for three months; €250,000 of contribution margin and running costs are the real loss — several times the fire damage itself. This is the cover that decides whether the customer list survives."}],"rec":[{"id":"cov_360","name":"Transport cover (goods / carrier liability)","desc":"insures the firm's goods in motion, inbound and outbound, and the liability of carrying for others where relevant. In wholesale, goods in transit are the second inventory.","signal":"import containers, own delivery fleet, Incoterms talk.","when":"","cross":"","claim":"An inbound container arrives seawater-damaged — €35,000 of stock ruined before it ever reached the warehouse the contents policy protects. Transport cover pays; the contents policy never could."},{"id":"cov_361","name":"Fleet cover","desc":"legally required per vehicle and operationally central for delivery operations.","signal":"own trucks on daily routes.","when":"","cross":"","claim":"A delivery truck accident writes off the vehicle and injures another driver — the fleet contract absorbs the liability and own-damage sides and keeps the delivery schedule alive with a replacement."},{"id":"cov_362","name":"Cyberversicherung","desc":"response, restoration, and interruption cover for the production IT: ERP, warehouse management, machine controls. Ransomware downtime is the modern business interruption, and property policies don't cover it.","signal":"ERP-run planning, connected machines.","when":"","cross":"","claim":"Ransomware encrypts the ERP and warehouse system; picking, production planning, and invoicing stop for ten days — €120,000 in interruption and recovery, none of it a property claim."}],"opt":[{"id":"cov_363","name":"Montageversicherung (erection cover)","desc":"protects delivered machinery during installation and commissioning at the customer, the window where it's paid for by no one and exposed to everything.","signal":"delivery-plus-installation contracts.","when":"","cross":"","claim":"A machine is damaged by a rigging slip during commissioning at the customer — €30,000, in the exact gap between the transport cover (ended at delivery) and the customer's property policy (not yet accepted)."},{"id":"cov_364","name":"Photovoltaik cover","desc":"plant-and-yield cover for the hall roof array.","signal":"production halls with PV.","when":"","cross":"","claim":"Hail wrecks a third of the rooftop array — €40,000 in panels and lost feed-in, a PV-policy claim the building cover would dispute."},{"id":"cov_365","name":"Kautionsversicherung (surety)","desc":"bonds for supply and framework contracts that demand security.","signal":"bond clauses in customer contracts.","when":"","cross":"","claim":"A framework agreement requires a €50,000 performance bond; the surety line issues it and the credit line stays free for raw materials."},{"id":"cov_366","name":"bAV / Gruppen-Unfall / bKV (benefits)","desc":"pension, accident, and health benefits as the retention package for skilled industrial workers.","signal":"machinists taking months to hire.","when":"","cross":"","claim":"A machine operator injured in a private motorcycle accident gets the group accident lump sum and keeps his standard of living through recovery — and the story does more for retention than any poster."},{"id":"cov_367","name":"Betriebsschließungsversicherung (ordered-closure cover)","desc":"pays for authority-ordered closure in food production under the Infection Protection Act.","signal":"any food line.","when":"","cross":"","claim":"A listeria finding closes production for two weeks of deep cleaning and batch destruction — €60,000 in lost output and disposal; verify the covered-pathogen list in the current wording."}]}},{"id":"landwirtschaft","icon":"ti-tractor","accent":"#4e7a27","bg":"var(--en-leaf-light)","title":"Agriculture & Direct Marketing","types":["Arable farming","livestock","special crops & orchards","agricultural contractors","farm shops & direct marketing","energy farming (biogas/PV)"],"policies":{"must":[{"id":"cov_368","name":"Agricultural liability (landwirtschaftliche Betriebshaftpflicht)","desc":"pays for the injuries and damage a farm generates by existing: animals that escape, slurry that runs, machines on public roads, visitors on the yard. Animal keeper's liability alone is strict — the keeper is liable for what the animal does regardless of fault.","signal":"every farm; verify the wording covers the actual mix (livestock, contracting, visitors, events).","when":"","cross":"","claim":"Cattle break through a fence onto the road at dusk; a car hits one and the driver is seriously injured — a €200,000 claim under strict animal-keeper liability, no negligence required. This single scenario justifies the policy."},{"id":"cov_369","name":"Agricultural contents cover (landwirtschaftliche Inhaltsversicherung)","desc":"replacement value for what the farm holds: harvest, stores, feed, equipment, and livestock within the wording. A farm's wealth sits in its barns, and fire is its oldest enemy.","signal":"full stores after harvest, mixed storage of hay and machinery.","when":"","cross":"","claim":"A barn fire takes the hay store and two parked machines — €120,000 in one night. The payout matched the loss only because the sums were revalued after harvest; ask when that last happened."},{"id":"cov_370","name":"Mobile machinery + commercial building cover","desc":"machinery cover for the self-propelled fleet (tractors, harvesters — enormous capital that works outdoors and burns or breaks in season) and building cover for the farm structures against fire, storm, and natural hazards.","signal":"every mechanized farm; ask what the combine is worth and what its downtime costs mid-harvest.","when":"","cross":"","claim":"A combine catches fire in the field in week one of harvest — €150,000 machine loss plus the scramble for replacement capacity while the crop stands. The machinery policy pays the machine; the building policy would have handled the barn it thankfully wasn't parked in."}],"rec":[{"id":"cov_371","name":"Photovoltaik cover","desc":"plant-and-yield insurance for roof and ground-mounted arrays, which for many farms are a revenue line of their own now.","signal":"feed-in income on the books, expansion plans.","when":"","cross":"","claim":"A hailstorm destroys €40,000 of panels on the barn roof and months of feed-in revenue — a PV-policy claim covering both the hardware and the yield."},{"id":"cov_372","name":"Firmen-Rechtsschutz","desc":"legal costs for the farm's characteristic fights: lease (Pacht) disputes, neighbor conflicts, subsidy clawbacks, employment. Dedicated agricultural variants exist — check availability.","signal":"leased land, subsidy dependence.","when":"","cross":"","claim":"A landowner terminates a long-standing Pacht arrangement irregularly; defending the lease through court costs €9,000 in fees — carried by the policy, and the land stays in the rotation."},{"id":"cov_373","name":"Fixed-cost cover","desc":"pays the running costs after a major loss while the operation rebuilds.","signal":"financed operations with debt service.","when":"","cross":"","claim":"After the barn fire above, feed purchases, debt service, and wages run on for months before the operation normalizes — €30,000 of continuing costs the fixed-cost cover absorbs."}],"opt":[{"id":"cov_374","name":"Product liability / closure cover for direct marketing","desc":"the farm shop turns the farmer into a food business, with food-product liability and the exposure to authority-ordered closure.","signal":"farm shops, processing, market stalls, online sales.","when":"","cross":"","claim":"A batch of raw-milk cheese from the farm dairy is linked to illness; recall, destruction, and a two-week ordered closure of the shop cost €25,000 — claims that live in the product-liability and closure covers, not the basic farm policy. Verify the wording covers the processing and retail activity."},{"id":"cov_375","name":"Cyberversicherung","desc":"response cover for the farm's digital core: milking robots, feeding systems, barn controls, herd-management data.","signal":"automated barns, smart-farming tools.","when":"","cross":"","claim":"The herd-management and milking system is encrypted by ransomware; manual operation, recovery, and lost milk-quality data cost €20,000 across a bad week."},{"id":"cov_376","name":"Gruppen-Unfall / bKV (benefits)","desc":"accident lump sums and health top-ups where the agricultural statutory system stops: leisure time, benefit level, and the contributing family members whose status is often unclear.","signal":"family labor, generational handover.","when":"","cross":"","claim":"The farmer's son is badly hurt in a private sports accident during his years of working into the operation — statutory benefits are thin, and the group accident lump sum is what bridges the family through it. Crop-yield and livestock-mortality covers are specialty lines with their own market — say so openly and place them separately."}]}}],"verticals":[{"id":"ver_377","deck":"vertical","title":"Construction & Finishing Trades","tagline":"crews on other people's property, value in the van","icon":"ti-tools","category":"Liability","products":[{"id":"enp_0_0","name":"Post-handover liability","why":"Trade defects surface long after the invoice is paid, and the claim lands on the firm whether or not the crew still remembers the job — without the completed-work and working-damage clauses, the policy walks away exactly then.","pivot":"Who pays when your work causes damage months after acceptance?","listen":"callbacks, warranty visits, \"we're in someone's house every day.\""},{"id":"enp_0_1","name":"Tools in transit","why":"The building-based contents policy stops at the workshop door, and a trade firm's capital rides around in vans — the gap is total, not partial.","pivot":"What's the replacement value of what's sitting in the vans right now?","listen":"\"my whole setup is in the bus,\" trailers loaded overnight"},{"id":"enp_0_2","name":"Bauleistung / Montage","why":"An unfinished structure and a delivered-but-uninstalled system belong to nobody's finished-property policy — the contractor carries the loss until handover.","pivot":"Are you on new builds, or installing high-value systems?","listen":"shell construction, delivered units waiting on site"},{"id":"enp_0_3","name":"Kaution","why":"Cash retentions and bank guarantees tie up the firm's liquidity for years; insurer-issued bonds release it — this is a financing conversation wearing an insurance label.","pivot":"Are clients withholding retentions or demanding guarantees?","listen":"\"the bank line is tight,\" public tenders"}]},{"id":"ver_378","deck":"vertical","title":"Cleaning & Facility Services","tagline":"keys in hand, inside client space","icon":"ti-spray","category":"Liability","products":[{"id":"enp_1_0","name":"Key loss & working damage","why":"The two most likely losses in this trade — the lost master key and the damaged surface being cleaned — are exactly the two things basic liability policies restrict or cap.","pivot":"Do you hold master keys or alarm codes?","listen":"after-hours access, \"we have the master key.\""},{"id":"enp_1_1","name":"Rechtsschutz (employment)","why":"High headcount plus high turnover makes the labour court this industry's most probable legal venue, and at first instance each side pays its own lawyer win or lose.","pivot":"How many people, and how much turnover in the team?","listen":"dismissal stories, wage disputes"},{"id":"enp_1_2","name":"Fleet","why":"Daily multi-site driving turns motor claims into a frequency cost that single policies manage badly and a fleet contract manages well.","pivot":"How do the crews move between sites?","listen":"multiple objects serviced per day"},{"id":"enp_1_3","name":"Cyber","why":"The scheduling software holds client alarm codes and floor plans — a breach here is a physical-security incident for every client at once.","pivot":"Where do access codes and schedules live?","listen":"scheduling apps, client portals"}]},{"id":"ver_379","deck":"vertical","title":"Landscaping & Grounds","tagline":"machines in the open, duties on other people's ground","icon":"ti-plant-2","category":"Liability","products":[{"id":"enp_2_0","name":"Winter service liability","why":"Gritting contracts transfer the property owner's traffic-safety duty to the firm — one icy morning can produce a six-figure injury claim aimed squarely at the contractor.","pivot":"Do you plow or grit in winter?","listen":"\"snow keeps us busy year-round,\" seasonal contracts"},{"id":"enp_2_1","name":"Mobile machinery","why":"Excavators and mowers work and sleep outdoors where no contents policy reaches, and they're the easiest high-value theft in commercial Germany.","pivot":"Does equipment stay on trailers or sites overnight?","listen":"\"it all stays on the trailer.\""},{"id":"enp_2_2","name":"Environmental modules","why":"Spray drift and fuel spills produce public-law cleanup orders that standard liability wording excludes — the authority doesn't care whose fault it was.","pivot":"Do you apply plant-protection products?","listen":"\"we treat lawns,\" spraying programs"},{"id":"enp_2_3","name":"Bauleistung","why":"Walls, paving, and plantings belong to the contractor until handover — weather damage before acceptance is his loss alone.","pivot":"Any larger new installations this season?","listen":"tender language, staged projects"}]},{"id":"ver_380","deck":"vertical","title":"Food Service & Hospitality","tagline":"guests, food, and an authority that can close you","icon":"ti-tools-kitchen-2","category":"Property & income","products":[{"id":"enp_3_0","name":"Betriebsschließung","why":"The health authority can close a food business by administrative order, and neither the liability nor the property policy pays a cent for it — this is the one closure risk unique to food.","pivot":"What happens if the health office closes you for a week?","listen":"inspection stories, hygiene audits"},{"id":"enp_3_1","name":"Contents underinsurance","why":"Hospitality reinvests constantly, so sums insured age faster here than anywhere — and an outdated sum triggers proportional payout cuts exactly when the kitchen burns.","pivot":"When did the sum insured last see your kitchen-equipment invoices?","listen":"recent renovation, new kitchen line"},{"id":"enp_3_2","name":"Business interruption","why":"Thin margins on high fixed costs mean the closure usually outdamages the fire — rent and payroll don't pause for repairs.","pivot":"How long can rent and payroll run on reserves?","listen":"thin-margin talk, high fixed rent"},{"id":"enp_3_3","name":"bKV / benefits","why":"In the sector with Germany's worst staffing shortage, a visible health benefit differentiates an employer more per euro than any wage increase.","pivot":"How hard is hiring right now?","listen":"\"we're closed Mondays because we have no staff.\""}]},{"id":"ver_381","deck":"vertical","title":"Retail","tagline":"stock is the capital, footfall is the risk","icon":"ti-building-store","category":"Property & income","products":[{"id":"enp_4_0","name":"Seasonal underinsurance","why":"Stock value at the seasonal peak can be double the annual average, and the burglar knows the calendar too — a March sum insured meets a November loss.","pivot":"What's on the floor and in the back at the seasonal peak — versus what's in the policy?","listen":"\"the warehouse is full for Christmas.\""},{"id":"enp_4_1","name":"Cyber / POS","why":"The till and the webshop are the revenue pipe — when they stop, the shop is open but earning nothing, and card data brings notification duties on top.","pivot":"What happens when the till system is down on a Saturday?","listen":"webshop mentions, card-only checkout"},{"id":"enp_4_2","name":"Business interruption","why":"An A-location lease keeps billing through the rebuild — the rent is the loss even when the stock is saved.","pivot":"Would the landlord pause the rent after a water damage? Neither would ours","listen":"prime-location rent talk"},{"id":"enp_4_3","name":"Transport","why":"Goods in the owner's own van between wholesaler and branches are covered by nothing — the contents policy ends at the shop door and motor cover pays only the other party.","pivot":"Do goods move between branches or from your own pickups?","listen":"own van runs to the wholesaler"}]},{"id":"ver_382","deck":"vertical","title":"Real Estate & Property Management","tagline":"other people's money and buildings","icon":"ti-building-skyscraper","category":"Professional","products":[{"id":"enp_5_0","name":"Mandatory PI","why":"Managers' and agents' errors destroy money, not property — and professional law makes the cover a license condition, so an outdated level is a compliance gap and a personal-liability gap at once.","pivot":"Is your professional indemnity at the level your license requires?","listen":"new WEG mandates, growing units under management"},{"id":"enp_5_1","name":"Elementar","why":"Heavy-rain and backflow losses are the fastest-growing building claims in Germany, and the standard building policy pays nothing on them without the natural-hazards module.","pivot":"Which buildings in the portfolio have natural-hazards cover?","listen":"heavy-rain stories, basement flooding"},{"id":"enp_5_2","name":"Photovoltaik","why":"A PV plant is neither clearly building nor clearly contents — unallocated, both insurers point at each other after the fire.","pivot":"Any PV going onto the roofs?","listen":"owner-association resolutions on solar"},{"id":"enp_5_3","name":"Rechtsschutz","why":"Tenancy and WEG disputes are the operating noise of this business, and legal costs decide which fights are affordable.","pivot":"How many open tenancy disputes right now?","listen":"eviction cases, arrears"}]},{"id":"ver_383","deck":"vertical","title":"Professional & Financial Services","tagline":"advice is the product, liability is personal","icon":"ti-briefcase","category":"Professional","products":[{"id":"enp_6_0","name":"Vermögensschaden-Haftpflicht","why":"When the product is advice, every error is a pure financial loss — the one category general liability explicitly excludes and, for licensed professions, the one the law requires covered.","pivot":"What happens if advice turns out demonstrably wrong and the client quantifies it?","listen":"growing mandate sizes, new licensed activities"},{"id":"enp_6_1","name":"Cyber","why":"Client data is the entire relationship; a leak is simultaneously a GDPR case, a liability case, and a reputation event — and only funded, professional response contains all three.","pivot":"Where does client data live, and who can reach it?","listen":"cloud tools, home-office setups"},{"id":"enp_6_2","name":"Rechtsschutz","why":"Advisory firms write off unpaid fees because suing feels expensive — legal-expenses cover converts write-offs back into receivables.","pivot":"Ever had a fee go unpaid and thought about court?","listen":"receivables complaints"},{"id":"enp_6_3","name":"Benefits","why":"In a people business the assets leave every evening — pension and health benefits are the cheapest way to make them come back.","pivot":"How do you keep good people from being poached?","listen":"hiring frustration"}]},{"id":"ver_384","deck":"vertical","title":"IT & Digital Services","tagline":"your error becomes the client's downtime","icon":"ti-code","category":"Professional","products":[{"id":"enp_7_0","name":"IT professional indemnity","why":"Software errors don't break things, they stop things — and a stopped client production line is a pure financial loss only the IT-PI wording covers.","pivot":"If your update halts their production, who pays the standstill?","listen":"SLAs, go-live dates, managed-services contracts"},{"id":"enp_7_1","name":"Own cyber cover","why":"An IT firm's breach cascades into every client it manages, and a provider that can't fund its own incident response loses its credibility asset overnight.","pivot":"Would your clients stay if you were the one breached?","listen":"admin access to client systems"},{"id":"enp_7_2","name":"Elektronik","why":"The firm's production plant is its hardware, and the ways hardware actually dies — surge, drop, theft — are exactly what contents policies exclude.","pivot":"What's the hardware worth in the office and the rack?","listen":"own server room, dev workstations"},{"id":"enp_7_3","name":"Rechtsschutz","why":"Acceptance and scope disputes are this sector's signature conflict, and they're won with funded lawyers, not email threads.","pivot":"Any disputes over project acceptance?","listen":"\"the client won't sign off.\""}]},{"id":"ver_385","deck":"vertical","title":"Agencies, Marketing & Media","tagline":"published work, third-party rights","icon":"ti-palette","category":"Professional","products":[{"id":"enp_8_0","name":"Media liability / PI","why":"Everything an agency ships is publication, and publication risk — image rights, trademarks, personality rights — is pure financial loss that only a media-aware wording carries.","pivot":"Who clears image, music, and trademark rights — and who pays when it goes wrong?","listen":"stock-photo use, influencer campaigns"},{"id":"enp_8_1","name":"Cyber","why":"Admin access to client ad accounts plus authority over client budgets means one phished login spends someone else's money — and the client will want it back from the agency.","pivot":"Do you hold client ad accounts and budgets?","listen":"\"we run their whole performance spend.\""},{"id":"enp_8_2","name":"Elektronik","why":"Production gear earns on location and gets stolen from vans — precisely where the office contents policy no longer applies.","pivot":"What travels to a shoot in one van?","listen":"camera lists, rented gear"},{"id":"enp_8_3","name":"Rechtsschutz","why":"Usage-rights and fee fights arrive after the relationship ends, when goodwill is gone and only funded enforcement works.","pivot":"Ever fought over usage rights after a project ended?","listen":"scope-creep stories"}]},{"id":"ver_386","deck":"vertical","title":"Healthcare & Care Services","tagline":"bodily contact plus the most sensitive data","icon":"ti-stethoscope","category":"Liability","products":[{"id":"enp_9_0","name":"Professional liability","why":"Hands-on treatment makes bodily-injury allegations statistically inevitable, and the defense of the unfounded allegation costs as much as the payout of the founded one.","pivot":"Who defends the treatment-error allegation — justified or not?","listen":"new treatment methods, delegated staff treatments"},{"id":"enp_9_1","name":"Cyber","why":"Patient records are health data — the GDPR's most protected category — and a locked practice system stops treatment, scheduling, and billing simultaneously.","pivot":"What happens if the practice software is encrypted on a Monday?","listen":"digital patient files, online booking"},{"id":"enp_9_2","name":"Fixed-cost cover","why":"Practices bill per session; a closed room means zero revenue from day one while rent, salaries, and device leasing continue in full.","pivot":"If the practice stands still four weeks, what keeps getting billed to you?","listen":"high fit-out financing"},{"id":"enp_9_3","name":"Fleet","why":"For outpatient care the vehicles are the service — a dozen small cars on daily tours generate monthly motor claims and can't afford a day without a replacement vehicle.","pivot":"How many cars are on tour daily?","listen":"route plans, staff drivers"}]},{"id":"ver_387","deck":"vertical","title":"Personal Care & Fitness","tagline":"hands on the client, all day","icon":"ti-scissors","category":"Liability","products":[{"id":"enp_10_0","name":"Treatment/training injuries","why":"The injury here happens *through* the service — chemicals on skin, loads on bodies — so the treatment-damage clause is the policy's heart, and new service lines outrun old wordings.","pivot":"What if a coloring, a treatment, or a session causes an injury?","listen":"new offerings (chemical peels, EMS training)"},{"id":"enp_10_1","name":"Contents + BI","why":"These businesses are their rooms — no studio, no revenue — while rent and leased equipment keep billing through the rebuild.","pivot":"The studio burns Saturday night — when do you reopen, and who pays the rent meanwhile?","listen":"fresh renovations, leased equipment"},{"id":"enp_10_2","name":"Cyber","why":"Booking and subscription systems hold members' identity and payment kits, and a small studio's breach response is unaffordable without cover.","pivot":"Where do member and payment data sit?","listen":"booking apps, subscription billing"},{"id":"enp_10_3","name":"Benefits","why":"Trained staff can open next door with a chair and a mirror — retention benefits are cheaper than the revenue they walk out with.","pivot":"How do you keep trained people from opening next door?","listen":"churn complaints"}]},{"id":"ver_388","deck":"vertical","title":"Automotive Trades","tagline":"custody of customer vehicles","icon":"ti-car","category":"Motor & fleet","products":[{"id":"enp_11_0","name":"Custody damage","why":"Standard liability excludes damage to property in the firm's custody — which in this trade is the entire business model, every car on the lot.","pivot":"Whose policy pays for the customer's car on your lot overnight — or on the test drive?","listen":"full yards, dealer plates"},{"id":"enp_11_1","name":"Environmental","why":"Oils, fuels, and batteries produce public-law cleanup orders when they escape — payable regardless of fault and excluded from basic wordings.","pivot":"How are oils, fuels, and batteries stored and disposed of?","listen":"EV work, tank talk"},{"id":"enp_11_2","name":"Contents / machinery","why":"Diagnostics and lifts are the earning capacity, they're theft magnets, and machinery fails from within in ways fire policies never cover.","pivot":"What would it cost to re-equip the workshop from zero?","listen":"new diagnostics, calibration rigs"},{"id":"enp_11_3","name":"Rechtsschutz","why":"Disputed invoices are this trade's permanent weather, and the expert report that wins them costs more than most invoices.","pivot":"How often do repair invoices get disputed?","listen":"warranty arguments"}]},{"id":"ver_389","deck":"vertical","title":"Education & Training","tagline":"supervision duty, often over minors","icon":"ti-school","category":"Liability","products":[{"id":"enp_12_0","name":"Supervision liability","why":"Providers stand in for parents' duty of care, and every incident involving a minor arrives with a supervision allegation attached — the defense is the product here.","pivot":"Who is liable if a child is hurt during a lesson or on an excursion?","listen":"group sizes, off-site activities"},{"id":"enp_12_1","name":"Cyber","why":"Children's data plus parents' payment details is the combination with zero public tolerance for sloppy handling.","pivot":"Where do participant data and course platforms run?","listen":"online offerings, payment plans"},{"id":"enp_12_2","name":"Vermögensschaden-Haftpflicht","why":"Wrong registration advice or a botched qualification pathway costs a participant money and time — pure financial loss the liability policy excludes.","pivot":"Do you certify outcomes or prepare people for examinations?","listen":"promised qualifications"},{"id":"enp_12_3","name":"Gruppen-Unfall","why":"Statutory pupil accident cover applies to school contexts, not private courses — so participant accident cover is both a real gap and a visible quality marker.","pivot":"What accident cover do participants have with you — and do parents ask?","listen":"enrollment-form questions"}]},{"id":"ver_390","deck":"vertical","title":"Events & Entertainment","tagline":"value that travels, crowds that gather","icon":"ti-confetti","category":"Property & income","products":[{"id":"enp_13_0","name":"Gear in transit","why":"Event equipment earns on the road and in halls — exactly where the stationary contents policy has already stopped applying — and the theft happens the night before the show.","pivot":"Where does the rig sleep the night before the show?","listen":"loaded vans at motorway hotels"},{"id":"enp_13_1","name":"Organizer liability","why":"Crowd and structure risk isn't automatically in a business liability policy, and tariffs cap the event sizes they accept — growth into bigger formats silently outruns the cover.","pivot":"What's the biggest crowd you've had — and the biggest you're bidding for?","listen":"growth into larger formats"},{"id":"enp_13_2","name":"Montage","why":"Build-up and tear-down is where structures fall and venues get damaged, in a deliberate boundary zone between erection cover and liability.","pivot":"Do you build stages or stands yourselves?","listen":"rigging, trade-fair projects"},{"id":"enp_13_3","name":"Cyber","why":"An own ticket shop means holding thousands of card transactions for strangers — a breach is a mass-notification event with refunds attached.","pivot":"Do you run the ticketing and hold attendee data?","listen":"own shop systems"}]},{"id":"ver_391","deck":"vertical","title":"Light Manufacturing & Wholesale","tagline":"one machine, one recall, one bottleneck","icon":"ti-building-factory-2","category":"Property & income","products":[{"id":"enp_14_0","name":"Product liability / recall","why":"Once a product carries the firm's name, downstream failures travel back up the chain — and recall logistics hit even the faultless supplier, at costs basic wordings don't carry.","pivot":"What happens if one batch has to come back from the market?","listen":"private-label production, supplying into larger brands"},{"id":"enp_14_1","name":"Machinery + BI","why":"Machines fail from within — no fire, no burglary, no property trigger — and the standstill behind the bottleneck machine usually costs several times the repair.","pivot":"Which single machine's failure stops everything?","listen":"\"everything runs through that line.\""},{"id":"enp_14_2","name":"Transport","why":"In wholesale, the second inventory is permanently on the road or on the water, where the warehouse contents policy has never applied.","pivot":"Who carries the risk on inbound and outbound goods?","listen":"Incoterms talk, own delivery fleet"},{"id":"enp_14_3","name":"Cyber","why":"Ransomware in the ERP is a full production standstill without any property trigger — the modern interruption that property policies structurally can't see.","pivot":"Is production planning digital — and what happens when it's encrypted?","listen":"ERP and warehouse-management systems"}]},{"id":"ver_392","deck":"vertical","title":"Agriculture & Direct Marketing","tagline":"farm, home, and firm in one yard","icon":"ti-tractor","category":"Liability","products":[{"id":"enp_15_0","name":"Agricultural liability","why":"Animal-keeper liability is strict — the keeper pays for what the animal does, fault or no fault — and farms generate liability by existing: roads, visitors, emissions.","pivot":"Animals, machines on public roads, visitors on the yard — where does your policy draw the line?","listen":"new branches (farm events, boarding animals)"},{"id":"enp_15_1","name":"Contents & machinery values","why":"A farm's wealth sits in barns and machines whose values swing with the harvest calendar — sums insured set in spring meet fires in autumn.","pivot":"When were harvest, stores, and machine park last revalued?","listen":"new harvest technology, full stores"},{"id":"enp_15_2","name":"Photovoltaik / energy","why":"Roof and land arrays are a second business line with their own hardware and yield risk, sitting awkwardly between farm and building policies unless placed deliberately.","pivot":"Is the roof or the land earning yet?","listen":"feed-in talk, biogas plans"},{"id":"enp_15_3","name":"Direct marketing","why":"The farm shop makes the farmer a food business — with product liability and the health authority's closure power that the basic farm policy never contemplated.","pivot":"Does the farm shop make you a food business?","listen":"processing, markets, online sales"}]}],"objections":[{"id":"obj_393","deck":"objection","title":"My agent/broker handles all of that — I've been with him for 20 years","icon":"ti-heart-handshake","category":"Incumbent","root":"Loyalty and convenience, not verified coverage quality. Twenty years of relationship often means twenty-year-old sums insured.","reframe":"\"That speaks well of you — good service is worth keeping, and I'm not here to displace anyone. The only question is: when was it last checked whether the contracts still match today's business? Companies change faster than policies.\" Never attack the incumbent — it loses. Offer the factual second opinion with a documented result, and be transparent about your own role and mandate; that transparency pays straight into trust.","bridge":"\"When did someone last hold your sums insured against today's stock value and payroll? That's exactly what I'm offering — no obligation, in writing, and if everything fits, I'll tell you exactly that.\""},{"id":"obj_394","deck":"objection","title":"I'm already insured through the Berufsgenossenschaft","icon":"ti-shield-check","category":"Knowledge","root":"The most widespread coverage illusion in the market — a statutory employer obligation mistaken for comprehensive protection. Not resistance; a knowledge gap.","reframe":"\"Correct, and you need it. The Berufsgenossenschaft covers your employees' workplace accidents. It covers neither your liability toward customers, nor your equipment, nor you as the owner — those are three completely separate construction sites.\" Never pitch anything the client holds by statute. Handling that boundary cleanly — here and with motor liability — builds instant competence trust and separates you from every salesperson they've met before.","bridge":"\"Let's lay out cleanly what you already have by law and where genuinely nothing is in place — then we only talk about the real gaps.\""},{"id":"obj_395","deck":"objection","title":"Send me something in writing first","icon":"ti-mail","category":"Stall","root":"Partly a genuine review wish, partly a polite brush-off. The difference reveals itself in whether a date gets attached.","reframe":"\"Gladly — that's part of my process anyway; you'll get the analysis in writing and traceable. So the paper is actually worth something to you: which two or three points should definitely be in it?\" Don't push back on the written form — deliver it, structure it, and fix the follow-up in the same breath. The document plus the kept deadline *is* the sales argument.","bridge":"\"I'll send it by Thursday. Does early next week work — fifteen minutes to walk through the two flagged points?\""},{"id":"obj_396","deck":"objection","title":"My contract still runs until","icon":"ti-calendar-due","category":"Stall","root":"Usually simply true. Annual contracts with three-month notice are the norm.","reframe":"\"Completely fine — which makes now exactly the right time: we review calmly, without pressure, and if it fits better, we pre-book the renewal date. And some things have no incumbent at all: a cyber policy or a group accident cover you can arrange today, independent of it.\" The answer is a system, not rhetoric: renewal-date list, follow-up discipline, cancellation support — plus consistently selling the incumbent-free gaps (cyber, legal expenses, benefits) ahead of the renewal date.","bridge":"\"When is your main renewal date? I'll set our review three months before it — and until then we close the gaps that are already open today.\""},{"id":"obj_397","deck":"objection","title":"Let me think about it","icon":"ti-clock","category":"Stall","root":"Usually one unspoken concern rather than a real need for time — though sometimes genuine deliberation. The two are distinguishable: real deliberation accepts a concrete follow-up date; the brush-off avoids one.","reframe":"\"Of course — it's your business and it deserves consideration. In my experience, when someone wants to think it over, one specific point isn't settled yet. Which one is it for you — the cover, the cost, or the timing?\" Respect genuine deliberation instead of trying to break it. The winning combination is the same as for the written-form objection: a structured summary plus a fixed date. A scheduled second conversation converts better than a pushed first one.","bridge":"\"What information would make the decision easy for you? I'll bring exactly that to the follow-up — does Tuesday work?\""},{"id":"obj_398","deck":"objection","title":"Too expensive.\" / \"I saw it cheaper elsewhere","icon":"ti-currency-euro","category":"Price","root":"Premium viewed in isolation, not against the risk and almost never against the quality of the conditions. Comparison-portal prices rarely compare equal cover.","reframe":"\"I understand — more expensive than what, exactly? Than another quote, or than what you'd budgeted? And on the other quote: same waiver of underinsurance, same cover for damage to the property being worked on? That's exactly where the differences sit — the ones you only see at claim time.\" Never answer with a discount — it damages your advisor position. The conditions argument wins: replacement value, buffer, waiver of underinsurance, and — where the tariff includes one — a conditions-update guarantee that keeps the contract from aging. Name the feature, confirm the detail in the current conditions.","bridge":"\"What would a single uninsured loss from your own trade cost you — the water damage after handover, the master key? That's the number the premium competes against, not the portal price.\""},{"id":"obj_399","deck":"objection","title":"I need to ask my tax advisor first","icon":"ti-calculator","category":"Trust","root":"The Steuerberater is the most trusted external advisor in the Mittelstand. Not an excuse — the real decision structure, and an opportunity.","reframe":"\"Good idea, he knows your numbers. So he can assess it quickly, I'll summarize the recommendation with reasoning on one page — deductibility, payroll linkage, all on it. On bAV and bKV he'll want a say anyway.\" Never route around the tax advisor — equip and involve him. On bAV and bKV he is a de-facto co-decider, and a convinced Steuerberater refers you onward. Leave tax statements cleanly to him: no tax advice from the intermediary.","bridge":"\"Shall we set the follow-up so you have his okay by then — or bring him in directly on the benefits topics?\""},{"id":"obj_400","deck":"objection","title":"Doesn't my Betriebshaftpflicht already cover all of that?","icon":"ti-stack-2","category":"Knowledge","root":"The liability policy mistaken for all-round protection. The standard confusions: own stock and equipment (needs contents cover), own downtime (business interruption), pure financial loss (Vermögensschaden-Haftpflicht), cyber, and the legal costs of the firm's own disputes (Rechtsschutz).","reframe":"\"The Betriebshaftpflicht pays when you damage *others*. Everything that happens *to you* — your stock, your downtime, your data, your own legal disputes — is a different policy. It's the foundation, not the roof.\" The two-bucket explanation (liability outward vs. own losses inward) is the cleanest framing there is, and it works across every industry in Part 1. Draw it on paper — it survives the meeting.","bridge":"\"Shall we sort your risks into two buckets — damage you cause versus damage you suffer? Then you see in one view what the liability policy carries and what currently nothing carries.\""},{"id":"obj_401","deck":"objection","title":"Nothing has happened here in 30 years","icon":"ti-history","category":"Knowledge","root":"Lived experience beats statistics — understandable and internally consistent.","reframe":"\"And that speaks for your business. Only: you don't insure the past, you insure the one year that goes differently. The colleague with the water damage also had 25 good years before it.\" Fear scenarios and drama repel. What works is sober, same-industry claim examples — ideally regional — and the visible willingness to leave out what's unnecessary.","bridge":"\"Which loss would genuinely hit your business — not the scratch, but the one that takes six months to recover from? That's the only one we'll talk about; the rest we leave out.\""},{"id":"obj_402","deck":"objection","title":"I don't want to be over-insured — you people always just want to sell","icon":"ti-scale","category":"Trust","root":"The legacy of commission-driven structured sales. The client is protecting himself from the salesperson, not from the insurance.","reframe":"\"I understand the objection, and it's legitimate — which is why I document every recommendation with reasoning in the advice record, and I document just as clearly what you *don't* need. If I name two things today you can save yourself, will you take seriously the one gap I genuinely mean?\" The statutory advice and documentation duty is the strongest anti-distrust tool you have. Deselect first, recommend second — the order is the message.","bridge":"\"Let's start with what can go or is duplicated — after that we talk about what's missing.\""},{"id":"obj_403","deck":"objection","title":"Insurers never pay when it matters anyway","icon":"ti-shield-x","category":"Trust","root":"An experienced or retold claims disappointment — almost always caused by underinsurance, breached policyholder duties (Obliegenheiten), or a never-reviewed policy.","reframe":"\"Those stories exist, and almost always the same thing is behind them: the sum was too low, or a duty was breached, and nobody knew either beforehand. That's exactly why we check it *before* the claim — the waiver of underinsurance and the duties you need to keep are in my record, not in the fine print.\" Underinsurance with proportional reduction (Quotelung) is the most common real-world reason for cut payouts — which makes the underinsurance check the direct answer to this objection. Explain Obliegenheiten and the § 19 VVG disclosure duty proactively; transparency about the rules of the game is the sales argument.","bridge":"\"May I show you, on your current policy, the two or three places where it typically jams at claim time?\""},{"id":"obj_404","deck":"objection","title":"Money's tight right now","icon":"ti-receipt","category":"Price","root":"Often a real liquidity constraint, not a negotiating move. Treat it as a prioritization signal.","reframe":"\"Then we should be doubly careful that a single loss doesn't hit exactly that tight liquidity. Let's do triage: which risk would break the business, and which would merely annoy it? We cover the first category and consciously park the rest — documented.\" No discounts. Check payment-cadence options in the current tariff rather than promising them. Record the conscious deferral in the advice record: the documented \"reviewed and postponed\" protects the client, protects you under § 61 VVG, and creates the legitimate re-entry point.","bridge":"\"If we close only the one existential gap today and put the rest on the renewal review — which gap would that be for you?\""},{"id":"obj_405","deck":"objection","title":"My business is too small for all that","icon":"ti-building-store","category":"Cross-sell","root":"Covers like cyber, legal expenses, or business interruption perceived as corporate topics.","reframe":"\"The other way round: the large company absorbs the loss from petty cash — for you, the whole business hangs on the same loss. That's exactly why compact SME tariffs exist: cut for your size.\" Point to the compact SME product lines as visible proof the cover was built for this size of business — then keep the recommendation to the one or two covers that map to an existential loss, not a catalogue.","bridge":"\"How many weeks of standstill can your account absorb before it gets serious? That's the only number that decides 'too small'.\""},{"id":"obj_406","deck":"objection","title":"Cyber doesn't concern us — we're not an IT company","icon":"ti-lock","category":"Cross-sell","root":"Cyber read as a technology topic, not as a business-interruption and payment-fraud topic.","reframe":"\"Attackers aren't looking for IT companies, they're looking for open doors — and the invoice with the altered bank details hits the trade business exactly like the law firm. The question isn't whether you sell IT; it's whether your business runs for a week without email, till, and bookkeeping.\" The effective entry runs through business interruption and payment-diversion fraud, not through data-protection theory; GDPR notification duties are the factual supporting argument, not the lead.","bridge":"\"What concretely happens at your firm if no computer opens tomorrow morning and the last outgoing invoice was paid to the wrong account?\""},{"id":"obj_407","deck":"objection","title":"I'll add the rest later","icon":"ti-arrows-shuffle","category":"Cross-sell","root":"Agreement in principle, deferral in practice — and \"later\" never arrives without a trigger. The notice-period rhythm makes \"later\" feel especially legitimate.","reframe":"\"Fine — but between now and later, the gap is real. Let's do two things: sort what genuinely can wait from what can't, and put 'later' in the calendar. An open-ended 'later' is a friendly no, and neither of us needs that.\" Anchor \"later\" to the concrete renewal date and enter the deferral in the advice record. A dated, documented commitment gets kept in a way a verbal \"we'll circle back\" never is.","bridge":"\"Which date do we write down for the second tranche — and is there anything on the list that would keep you up at night before then?\""},{"id":"obj_408","deck":"objection","title":"Now's not a good time — come back after the season","icon":"ti-snowflake","category":"Stall","root":"For seasonal businesses (hospitality, landscaping, events, retail) often simply true — and simultaneously risky, because peak season is peak exposure.","reframe":"\"Precisely because this is your strongest period, it's also your biggest risk — full warehouse, full order book, full floor. I don't need a decision on everything today: just the one gap that hurts during the season, and a firm date afterwards for the rest.\" Resolve it through a firmly agreed, documented follow-up date rather than forcing a first-contact close. A dated \"no, but in November\" is, as a rule, kept — treat it as pipeline, not as a loss.","bridge":"\"Which week after season-end shall I book firmly — and until then, may I at least have the sum insured adjusted for the full warehouse?\""}],"resources":[],"sections":[{"id":"cob","label":"Industries & Coverages","icon":"ti-shield-half","eyebrow":"Industry · coverage discovery","headline":"Know the cover before they know the risk.","blurb":"Sixteen industry groupings, the covers that matter in each, and the client cue that tells you to raise them. Open an industry to see what to bind, what to recommend, and what to keep in your back pocket.","notice":{"on":false,"tone":"info","title":"","body":""}},{"id":"vertical","label":"Spot the Need","icon":"ti-building-store","eyebrow":"SPOT THE NEED","headline":"Spot the gap before they describe the business.","blurb":"The same sixteen industries, the conversational cues in each, and the cross-sell openings worth probing. Flip a card to reveal the opening questions and what to listen for.","notice":{"on":false,"tone":"info","title":"","body":""}},{"id":"objection","label":"Objection Handling","icon":"ti-messages","eyebrow":"Objection handling","headline":"Turn the pushback into the next step.","blurb":"The objections you will actually hear, what is really driving each one, and the bridge question that keeps the conversation moving. Flip a card for the move.","notice":{"on":false,"tone":"info","title":"","body":""}},{"id":"resources","label":"Resources","icon":"ti-folder","eyebrow":"Field resources","headline":"Everything you need between calls.","blurb":"The guides, cheat sheets, and people that back up every conversation in this playbook.","notice":{"on":false,"tone":"info","title":"","body":""}}],"resSections":[],"settings":{"toolName":"Producer Hub","toolTagline":"Agent sales enablement","banner":{"on":false,"tone":"info","text":""},"tiers":{"must":{"label":"Must-have","sub":"Bind before the doors open"},"rec":{"label":"Recommended","sub":"Raise on every qualifying account"},"opt":{"label":"Situational","sub":"Know the cue, bring it up when it appears"}}},"_contentVer":999},"cats":{"vertical":["Liability","Professional","Property & income","Motor & fleet"],"objection":["Incumbent","Price","Stall","Trust","Cross-sell","Knowledge"]},"tint":{"Liability":{"bg":"var(--en-rose-50)","dot":"var(--en-burgundy)"},"Professional":{"bg":"var(--en-violet-light)","dot":"#b31767"},"Property & income":{"bg":"var(--en-yellow-light)","dot":"var(--en-amber)"},"Motor & fleet":{"bg":"var(--en-iceblue-light)","dot":"#0f94a7"},"Incumbent":{"bg":"var(--en-rose-50)","dot":"var(--en-burgundy)"},"Price":{"bg":"var(--en-yellow-light)","dot":"var(--en-amber)"},"Stall":{"bg":"var(--en-iceblue-light)","dot":"#0f94a7"},"Trust":{"bg":"var(--en-violet-light)","dot":"#b31767"},"Cross-sell":{"bg":"var(--en-leaf-light)","dot":"#009284"},"Knowledge":{"bg":"var(--en-warmgrey-light)","dot":"#545241"}},"ui":{"spot":"Spot the need: ","when":"When: ","claimLabel":"Claims example","listen":"Listen for","reveal":"Reveal","tap":"Tap to handle","flip":"flip back","back":"All industries","noMatch":"Nothing matches this filter.","searchInd":"Search industries…","searchObj":"Search objections…","covWord":"coverages","typesWord":"business types","gaps":"cross-sell gaps","rootLabel":"What's really going on","reframeLabel":"Validate & reframe","bridgeLabel":"The bridge","all":"All","langBtn":"Auf Deutsch anzeigen","loading":"Loading playbook…"}}};
